["Here's a basic example of how you could implement this using POSIX pthreads for thread synchronization, and C11 atomics for lock-free concurrency control. 

```c
#include <pthread.h>
#include <stdatomic.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int protocolVersion;
    unsigned sequenceNumber;
    time_t timestamp;
    size_t payloadLength;
} PacketHeader;

// The dynamic array
PacketHeader *headers = NULL;
size_t headersSize = 0, headersCapacity = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addHeader(PacketHeader header) {
    pthread_mutex_lock(&lock); // Lock for atomicity.

    if (headersSize >= headersCapacity) {
        headersCapacity = headersCapacity * 2 + 1;
        headers = realloc(headers, headersCapacity * sizeof(*headers));
    }

    memcpy(&headers[headersSize], &header, sizeof(PacketHeader)); // Ensure no races.
    ++headersSize;

    pthread_mutex_unlock(&lock);
}

void updateHeader(size_t index, PacketHeader header) {
    pthread_mutex_lock(&lock);

    if (index < headersSize) {
        memcpy(&headers[index], &header, sizeof(PacketHeader)); // Ensure no races.
    }

    pthread_mutex_unlock(&lock);
}
```
This code uses a simple dynamic array approach with reallocation for growth. It uses a mutex to ensure that add and update operations are atomic relative to each other, meaning no two threads can concurrently modify the headers structure at once. 

For more complex scenarios or performance critical applications, you might want to use lock-free data structures like the ones available in the stdatomic library (c11), but note that these require much care to be used correctly and are not as universally supported. The tradeoff is improved performance and lower latency for operations.
"]

["```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
} Record;

// Hash table for storing long offset values and int keys
struct hash_entry_s {
    Record *record;
    unsigned char *value;
    struct hash_entry_s *next;
};

typedef struct hash_entry_s hash_entry_t;

static const int HASH_SIZE = 1024; // Change based on your needs
static hash_entry_t **hash_table = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_records(int num_unique_keys) {
    hash_table = (hash_entry_t**) calloc(HASH_SIZE, sizeof(hash_entry_t*));
    if (!hash_table) exit(-1); // Error handling for memory allocation failures

    srand(time(NULL));
    int i;
    for (i = 0; i < num_unique_keys; i++) {
        int key = rand();
        while (get_record(key)) {
            key = rand();
        }

        Record *new_rec = malloc(sizeof(*new_rec));
        if (!new_rec) exit(-1); // Error handling for memory allocation failures
        new_rec->key = key;

        hash_entry_t *new_hash_ent = malloc(sizeof(*new_hash_ent));
        if (!new_hash_ent) {
            free(new_rec);
            exit(-1); // Error handling for memory allocation failures
        }
        new_hash_ent->record = new_rec;

        unsigned int hash = key % HASH_SIZE;
        new_hash_ent->next = hash_table[hash];
        hash_table[hash] = new_hash_ent;
    }
}

Record *get_record(int key) {
    pthread_mutex_lock(&mutex); // Locking for thread safety 

    unsigned int hash = key % HASH_SIZE;
    hash_entry_t *curr_ent;
    for (curr_ent = hash_table[hash]; curr_ent != NULL; curr_ent = curr_ent->next) {
        if (curr_ent->record->key == key) {
            pthread_mutex_unlock(&mutex); // Unlocking after found 
            return curr_ent->record;
        }
    }

    pthread_mutex_unlock(&mutex); // Unlocking if not found 
    return NULL;
}

int cmpfunc(const void *a, const void *b) {
   return (((Record*) a)->key - ((Record*) b)->key);
}

void sort_records(Record* records, int size) {
    qsort(records, size, sizeof(*records), cmpfunc); 
}
```
This code block creates a hash table for storing `long` offset values and `int` keys. The `init_records()` function is responsible for initializing the records with unique random values within a specified range. It also handles memory allocation failures by exiting with an error if it fails to allocate memory for either the record or hash entry. 
The `get_record()` function retrieves the record associated with a given key, ensuring thread-safe access using a mutex. If no record is found, it returns NULL.
Finally, `sort_records()` sorts an array of records based on their `int` field values in ascending order using the standard library's `qsort()` function. This function is efficient for large datasets as it uses the QuickSort algorithm and performs well with already sorted or nearly-sorted data.
"]

