// Structure to hold the cache entry
typedef struct {
    char *hostname;
    u_char ipaddr[4];
    time_t timestamp;
} dns_cache_entry_t;

dns_cache_entry_t* dns_cache = NULL;  // Global cache
int dns_cache_size = 0;              // Cache size
time_t ttl;                          // Time to live

// Function to resolve DNS and cache result
u_char *resolve(const char *hostname) {
    u_char ipaddr[4];
    static int init = 0;

    if (!init) {
        dns_cache = malloc(sizeof(dns_cache_entry_t));  // Initializing cache
        if (dns_cache == NULL) {
            perror("malloc");
            exit(EXIT_FAILURE);
        }
        init = 1;
    }

    for (int i = 0; i < dns_cache_size; ++i) {  // Checking cache
        if (!strcmp(dns_cache[i].hostname, hostname)) {
            if (time(NULL) - dns_cache[i].timestamp <= ttl) {  // If TTL has not passed yet
                memcpy(ipaddr, dns_cache[i].ipaddr, sizeof(u_char)*4);
                return ipaddr;
            } else {  // Remove expired cache entry
                free(dns_cache[i].hostname);
                for (int j = i; j < dns_cache_size - 1; ++j)
                    dns_cache[j] = dns_cache[j+1];
                --dns_cache_size;
            }
        }
    }

    struct hostent *h;
    if ((h=gethostbyname(hostname)) == NULL) {  // If not in cache, resolve it
        herror("gethostbyname");
        exit(EXIT_FAILURE);
    }
    memcpy(ipaddr, h->h_addr, sizeof(u_char)*4);

    dns_cache = realloc(dns_cache, (dns_cache_size+1) * sizeof(dns_cache_entry_t));  // Allocating more memory to cache it
    if (dns_cache == NULL && dns_cache_size > 0) {
        perror("realloc");
        exit(EXIT_FAILURE);
    } else {
        dns_cache[dns_cache_size].hostname = strdup(hostname);  // Adding to cache
        memcpy(dns_cache[dns_cache_size].ipaddr, ipaddr, sizeof(u_char)*4);
        dns_cache[dns_cache_size].timestamp = time(NULL);
        ++dns_cache_size;
    }

    return ipaddr;
}

int main() {
    FILE *file = fopen("large.log", "r");  // Reading log file
    if (file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {  // Processing each line
        u_char ipaddr[4];
        char hostname[256];

        sscanf(line, "%s", hostname);  // Extracting hostname from the log entry. Depends on format of log file.
        memcpy(ipaddr, resolve(hostname), sizeof(u_char)*4);
        printf("%s -> %d.%d.%d.%d\n", hostname, ipaddr[0], ipaddr[1], ipaddr[2], ipaddr[3]);
    }

    free(line);  // Freeing resources after processing log file
    fclose(file);

    exit(EXIT_SUCCESS);
}
```
