['Here's a basic C code solution without error handling and sorting. However, this does not include memory management or error handling which are part of engineering challenges. Also note that this example uses integer input from standard input and searches the largest integer in the list using linear search instead of binary search as per problem statement. For an efficient Binary Search to find the maximum value, a sorted array is required which can be achieved by sorting the linked list.
```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node *next;
} Node;

Node* insert(Node *head,int data) {
   Node *temp =  (Node*)malloc(sizeof(Node));
   temp->data = data; 
   temp->next = NULL;     

   if(head == NULL){
       head = temp;  
    } else{
        Node *current_node = head;
        while (current_node->next !=NULL) {
            current_node = current_node->next;
        }

        current_node->next = temp;
    }               
   return head;
} 

int findMax(Node *head){
    int max = 0;
    Node* current = head;

    while (current != NULL) {
        if(current->data > max){
            max = current->data;
        }
        current = current->next;
    }  
    return max; 
}

int main() {
    Node *head = NULL;
    int data, i=0;

    printf("Enter number of inputs: ");
    scanf("%d", &i);

    for(int j = 0; j < i; ++j){
        printf("\nEnter the number \n");
        if (scanf("%d", &data) == 1){  // error handling for non-integer input
            head = insert(head, data);
        } else {
            printf("Invalid Input. Exiting.\n");
            return -1;
        }
    }

    int max = findMax(head);
    printf("\nMaximum: %d", max); 

    return 0;
}
```
This code creates a linked list and then finds the maximum value in it.
