["Below is a basic implementation in C using pthread mutexes for thread safety and snprintf with va_list for handling variable arguments in log messages:

```c
#include <stdio.h>
#include <pthread.h>
#include <stdarg.h>
#include <string.h>
#include <unistd.h>

typedef struct {
    char* buffer;
    size_t capacity;
    size_t front;
    size_t back;
    pthread_mutex_t mutex;
} CircularBuffer;

CircularBuffer* create_buffer(size_t capacity) {
    CircularBuffer* cb = malloc(sizeof(CircularBuffer));
    cb->buffer = malloc(capacity * sizeof(char));
    cb->capacity = capacity;
    cb->front = 0;
    cb->back = 0;
    pthread_mutex_init(&cb->mutex, NULL);
    return cb;
}

void log_event(CircularBuffer* cb, const char* format, ...) {
    va_list args;
    va_start(args, format);

    pthread_mutex_lock(&cb->mutex);

    int len = vsnprintf(NULL, 0, format, args);
    if (len < 0 || cb->front + len + 1 >= cb->capacity) {
        // buffer is full or error in snprintf. Resize the buffer
        size_t newCapacity = 2 * cb->capacity;
        char* newBuffer = malloc(newCapacity * sizeof(char));

        memcpy(newBuffer, &cb->buffer[cb->front], cb->back - cb->front);

        free(cb->buffer);
        cb->buffer = newBuffer;
        cb->capacity = newCapacity;
    }

    vsnprintf(&cb->buffer[cb->back], len + 1, format, args);
    cb->back += len;

    pthread_mutex_unlock(&cb->mutex);
}
``` 

This is just a simple example and does not include the features you requested such as flushing to disk and dynamic buffer sizing. It also lacks error checking, for simplicity it assumes that `malloc` always returns a valid pointer, which may not be true in more complex programs. You'd want to add checks for these kind of things in real-world code.
"]

