    private static final String POKEMON_API = "https://pokeapi.co/api/v2/pokemon/";

    private Map<String, Integer> typeDatabase1 = new HashMap<>(); // mock DB 1
    private Map<String, Integer> typeDatabase2 = new HashMap<>(); // mock DB 2

    public Pokemon getPokemon(String name) {
        CloseableHttpClient httpclient = HttpClients.createDefault();

        try {
            HttpGet request = new HttpGet(POKEMON_API + name);
            HttpResponse response = httpclient.execute(request);

            String jsonStr = EntityUtils.toString(response.getEntity());
            JsonObject pokemonJson = new Gson().fromJson(jsonStr, JsonObject.class);

            int level = 1; // extract level from JSON response
            if (level < 1 || level > 100) throw new InvalidPokemonLevelException();

            String type1 = pokemonJson.get("type").getAsString();
            Integer strength1 = typeDatabase1.get(type1);
            if (strength1 == null) {
                // mythical Pokemon case
                strength1 = calculateStrengthMythicalPokemon(pokemonJson, typeDatabase2);
            }

            String type2 = pokemonJson.get("secondaryType").getAsString();
            Integer strength2 = typeDatabase2.get(type2);

            int potentialBattles = calculatePotentialBattles(level, type1, type2); // replace with actual logic

            Pokemon pokemon = new Pokemon(name, level, type1, type2, strength1 + strength2 / 2.0, potentialBattles);
            return pokemon;
        } catch (Exception e) {
            throw new RuntimeException("Error occurred while fetching Pokemon data", e);
        } finally {
            try {
                httpclient.close();
            } catch (IOException ioe) {}
        }
    }

    private int calculatePotentialBattles(int level, String type1, String type2) {
        // replace with actual battle calculation logic
        return (level + typeDatabase1.getOrDefault(type1, 0) + typeDatabase2.getOrDefault(type2, 0)) / 3;
    }

    private int calculateStrengthMythicalPokemon(JsonObject pokemonJson, Map<String, Integer> secondaryTypeDb) {
        String mythicalType = pokemonJson.get("mythicalType").getAsString();
        return secondaryTypeDb.getOrDefault(mythicalType, 0);
    }

    class Pokemon {
        private String name;
        private int level;
        private String primaryType;
        private String secondaryType;
        private double strength;
        private int potentialBattles;

        public Pokemon(String name, int level, String primaryType, String secondaryType, double strength, int potentialBattles) {
            this.name = name;
            this.level = level;
            this.primaryType = primaryType;
            this.secondaryType = secondaryType;
            this.strength = strength;
            this.potentialBattles = potentialBattles;
        }

