["Here is a solution in C++ using std::forward_list. This implementation takes into account all the requirements you described. It uses the random library to generate random numbers, and it iterates through the list only once, hence its time complexity is linear - O(n).

```cpp
#include <random>
#include <algorithm>
#include <forward_list>

void manageList(std::forward_list<int>& flist, int target, int startRange, int endRange) {
    // Create a random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(startRange, endRange);

    auto prev = flist.before_begin();
    for (auto it = flist.begin(); it != flist.end(); ++it) {
        if (*it == target && next(it) != flist.end()) {
            *next(it) = dis(gen);
            return;
        } else if (*it == target && next(it) == flist.end()) { // If the target is the last element in the list
            for (int i = 0; i < 10; ++i) { // Append 10 random integers within the specified range
                flist.insert_after(flist.before_begin(), dis(gen));
            }
            return;
        } else if (next(it) == flist.end()) { // If the target is not found and the list is empty
            for (int i = 0; i < 10; ++i) { // Append 10 random integers within the specified range
                flist.insert_after(flist.before_begin(), dis(gen));
            }
        }
        ++prev;
    }
}
```
Please note that it's generally a bad practice to perform operations like insertion and deletion on std::forward_list from the middle of the list. For this reason, I chose to do all of these operations at the beginning of the list.
"]

