        if (File.Exists(xmlPath))
        {
            var doc = new XmlDocument();

            try 
            {
                doc.Load(xmlPath);

                // Parse and merge settings, handle defaults...
            }
            catch (XmlException e)
            {
                Console.WriteLine("The XML file at " + xmlPath + " is malformed.");
                return;
            }
        }
    }

    public async Task StartWatchingForChangesAsync()
    {
        watcher = new FileSystemWatcher(configuration["XmlPath"])  // Dynamically load path from config
        {
            NotifyFilter = NotifyFilters.LastWrite,
            EnableRaisingEvents = true
        };

        watcher.Changed += async (sender, e) => 
        {
            if(e.ChangeType != WatcherChangeTypes.Changed) 
                return;

            // Reload config...
            await LoadConfigAsync();
        };
    }

    public void StopWatchingForChanges()
    {
        watcher?.Dispose();
    }
}
