function processFilesInDirectory(dirPath, callback) {
  fs.readdir(dirPath, function (err, files) {
    if (err) return callback(err);

    async.eachLimit(files, 10, function (fileName, done) { // Process max 10 files at a time
      let filePath = path.join(dirPath, fileName);

      fs.readFile(filePath, 'utf8', function (err, data) {
        if (err) return done(err);

        validateData(data, function (validationError) {
          if (validationError) return done(validationError);

          transformData(data, function (transformError, transformedData) {
            if (transformError) return done(transformError);

            // Add the transformed data to a result set or process it immediately
            callback(null, transformedData); 
            done();
          });
        });
      });
    }, function (err) { // Process all files have been processed
      if (err) return callback(err);

      // Here you can return the aggregated results or handle the completion of file processing
      callback(null, 'All files processed');
    });
  });
}
