['Here's your requested JavaScript function as per your specifications:

```javascript
function renderFooterScripts(scripts) {
    if (!Array.isArray(scripts)) {
        throw new Error("Input must be an array.");
    }

    let result = '';
    scripts.forEach((script, index) => {
        if (typeof script !== 'object') {
            throw new Error(`Element at index ${index} is not an object. All elements in the array must be objects.`);
        }

        // Default values:
        let type = script.type || "text/javascript";
        let async = script.async === false ? "" : 'async';
        let defer = script.defer === false ? "" : 'defer';
        let charset = script.charset || "UTF-8"; // Default charset
        let src = script.src;

        if (!src) {
            throw new Error(`Element at index ${index} is missing a source URL ('src').`);
        }

        result += `<script type="${type}" src="${src}" charset="${charset}" ${async} ${defer}></script>\n`;
    });

    return result ? `<footer class='site-footer'>${result}</footer>` : '';
}
```

This function works by iterating through each script object in the input array, dynamically generating a new script tag for each one. It also ensures that required attributes (`src`) are present and defaults to `text/javascript` and `UTF-8` if they're not specified in the script objects.
']

