#include <iostream>
#include <forward_list>
#include <string>

void insertAfterTarget(std::forward_list<std::string> &lst, const std::string &target, const std::string &toInsert) {
    auto prev = lst.before_begin();
    for (auto it = lst.begin(); it != lst.end(); ++it) {
        if (*it == target) {
            lst.insert_after(it, toInsert);
            return;
        }
        prev = it;
    }

    // If the target is not found, append the insertion string to the end of the list
    lst.insert_after(prev, toInsert);
}

int main() {
    std::forward_list<std::string> myList = {"hello", "world"};

    // Testing function with a target that exists in the list
    insertAfterTarget(myList, "hello", "inserted");
    for (const auto &str : myList) {
        std::cout << str << ' ';  // Expected output: hello inserted world
    }

    // Testing function with a target that doesn't exist in the list
    insertAfterTarget(myList, "target", "inserted");
    for (const auto &str : myList) {
        std::cout << str << ' ';  // Expected output: hello inserted world inserted target
    }

    return 0;
}
