function authenticateUserAndFetchData() {
    session_start();

    $accessToken = $_SESSION['access_token'];
    $ipAddress = $_SESSION['ip_address'];

    $now = time();

    // Check if access token is present and not expired yet.
    if (!$accessToken || (isset($_SESSION['expires']) && $_SESSION['expires'] < $now)) {
        try {
            $authClient = new OAuth2\Client(...);

            // Authenticate with the client and store the access token.
            $result = $authClient->authenticate();
            $accessToken = $result->getAccessToken();

            // Save it in session variables.
            $_SESSION['access_token'] = $accessToken;
            $_SESSION['expires'] = $now + $result->getExpiresIn();
        } catch (Exception $e) {
            error_log($e);
            return false;
        }
