FSAState* manageTransitionList(int* currentStates, int numStates, 
                              FSAStructure* fsaStructure, int targetState, bool optimizeFlag) {
    if (numStates > MAX_STATES) return NULL; // Prevent resource exhaustion.

    pthread_mutex_init(&fsaStructure->lock);  // Initialize mutex for thread safety.

    FSAState* stateList = malloc(sizeof(FSAState) * numStates);
    if (stateList == NULL) return NULL;  // Ensure memory allocation was successful.

    pthread_mutex_lock(&fsaStructure->lock);  // Acquire lock to prevent race conditions.

    for (int i = 0; i < numStates; ++i) {
        stateList[i].current_state = currentStates[i];

        if (optimizeFlag) {
            // Perform optimization-specific operations, e.g., cache utilization optimization.
        }
    }

    pthread_mutex_unlock(&fsaStructure->lock);  // Release lock to allow other threads access.

    return stateList;
}
