};

OctreeNode* initializeOctree(std::istream& stream) {
    std::vector<float> data;

    while (stream.good()) {
        float f;
        try {
            stream >> f;

            // Check for errors in the input stream and handle them gracefully...
            if (stream.fail() || stream.bad()) throw std::runtime_error("Invalid data!");

            data.push_back(f);
        } catch (const std::exception& e) {
            // Handle exception...
            return nullptr;
        }
    }

    if (!data.empty()) {
        OctreeNode* root = new OctreeNode(&data[0], data.size());
        for (size_t i = 1; i < data.size(); ++i) {
            root->insertData(&data[i], 1);
        }

        return root;
    } else {
        // Handle case where no data was read...
        return nullptr;
    }
}
