typedef struct PacketStat {
    _Atomic(int) count;
    _Atomic(uint64_t) checksum;
} PacketStat;

PacketStat window[10];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void processNetworkPackets(char* packet, int size) {
    pthread_mutex_lock(&mutex); // lock the mutex to ensure thread safety

    if (size > 1500 || size < 46) {
        printf("Invalid packet size: %d\n", size);
        return;
    }

    uint64_t checksum = calculateChecksum(packet, size); // implement your own function to calculate the checksum

    for (int i = 0; i < 10; ++i) {
        if (window[i].checksum == checksum) {
            atomic_fetch_add(&window[i].count, 1);
            break;
        } else if(i == 9) { // we are at the last slot of our window
            for (int j = 0; j < 9; ++j) {
                window[j] = window[j + 1]; // shift all elements to the left, discarding the oldest one
            }
            window[9].checksum = checksum; // add new packet info at the end of our window
            atomic_init(&window[9].count, 1);
        }
    }

    pthread_mutex_unlock(&mutex); // unlock the mutex when we're done
}

uint64_t getHighestValidChecksum() {
    uint64_t highest = 0;
    for (int i = 0; i < 10; ++i) {
        uint64_t current = atomic_load(&window[i].checksum);
        if (current > highest) {
            highest = current;
        }
    }

    return highest;
}
