#include <pthread.h>
#include <tiffio.h>

typedef struct {
    uint16_t bps; // bits per sample
    uint16_t samplesPerPixel;
    uint32_t width; 
    uint32_t height; 
    char* md5Hash;
} ImageInfo;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

ImageInfo processTiff(const char *filename, const char *stringInput) {
    TIFF *tif = TIFFOpen(filename, "r");
    if (tif == NULL) {
        // error handling: file not found or could not be opened.
    }

    uint32_t width;
    TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &width);

    uint32_t height;
    TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &height);

    uint16_t samplesPerPixel;
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel);

    uint16_t bps; // bits per sample
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bps);

    // Get extra samples if existent.
    uint16_t extraSamples = 0;
    TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamples); 

    ImageInfo info = { bps, samplesPerPixel + extraSamples, width, height, NULL};

    // Generate MD5 hash.
    pthread_mutex_lock(&lock);
    unsigned char md5Digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)stringInput, strlen(stringInput), md5Digest);

    info.md5Hash = malloc(MD5_DIGEST_LENGTH*2 + 1); // For hexadecimal representation.
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&info.md5Hash[i * 2], "%02x", md5Digest[i]);
    }

    pthread_mutex_unlock(&lock);

    TIFFClose(tif);
    return info;
}
```
