['Sure, here is an implementation of your `initAndCleanAESCipher` function using OpenSSL library. This function derives the AES key from a given password and initializes an AES-256-CBC cipher. It also handles cleanup automatically by calling `EVP_CIPHER_CTX_free` after use:

```c
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <stdlib.h>
#include <string.h>

typedef struct CipherContext {
    EVP_CIPHER_CTX* ctx;
} CipherContext;

// Function to initialize AES-256-CBC cipher using OpenSSL
CipherContext* initAndCleanAESCipher(const char* password) {
    // Allocate memory for context
    CipherContext* cipher = malloc(sizeof(CipherContext));
    if (cipher == NULL) {
        return NULL;
    }

    // Initialize AES-256-CBC cipher
    EVP_CIPHER_CTX_init(cipher->ctx);
    EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);

    // Derive key from password using SHA-256
    unsigned char key[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)password, strlen(password), key);
    EVP_CIPHER_CTX_set_key_length(cipher->ctx, 32);

    // Set IV length to 16 bytes
    unsigned char iv[16];
    memset(iv, 0, sizeof(iv));
    EVP_EncryptInit_ex(cipher->ctx, NULL, NULL, key, iv);

    return cipher;
}

// Function to cleanup AES-256-CBC cipher context
void cleanupAESCipherContext(CipherContext* ctx) {
    EVP_CIPHER_CTX_cleanup(ctx->ctx);
    free(ctx);
}
```
