#include "png++/png.hpp" // you need to install png++ library, this is just a placeholder

namespace fs = std::filesystem;

class ThemeManager {
public:
    ThemeManager(const std::string& cacheRoot) : cacheRoot_(cacheRoot), defaultThemeDir_("default") {}

    void manageThemeCaching() {
        // Check if a theme bitmap is recycled and set it to null
        if (themeBitmap_) {
            delete themeBitmap_;
            themeBitmap_ = nullptr;
        }

        // Verify if a default theme directory is set and initialize it with a specified value
        fs::path defaultThemeDirPath(cacheRoot_);
        defaultThemeDirPath /= defaultThemeDir_;
        if (!fs::exists(defaultThemeDirPath)) {
            fs::create_directory(defaultThemeDirPath);
        }

        // Parse a PNG file from the cache root directory and store it in theme cache
        for (const auto& entry : fs::recursive_directory_iterator(cacheRoot_)) {
            if (entry.path().extension() == ".png") {
                png::image<png::rgb_pixel> image(entry.path());
                themeCache_.insert({entry.path(), image});
            }
        }
    }

