                var startTime = DateTime.Now;
                while (!process.HasExited)
                {
                    if ((DateTime.Now - startTime).TotalMilliseconds > Timeout)
                    {
                        throw new Exception("Site failed to start within the specified timeout period.");
                    }

                    Thread.Sleep(500); // Adjust this as needed for network conditions and server load scenarios
                }

                if (process.ExitCode != 0)
