```java
import java.io.*;
import java.nio.file.Files;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MonitorExec {
    private static final String COMMAND = "ls -l /";
    private static final File TMP_FILE = new File("tempFile");

    public static void main(String[] args) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(10); // adjust according to your needs

        String[] servers = {"server1", "server2", "server3"}; // list of your servers here

        for (String server : servers) {
            executor.execute(() -> {
                try {
                    executeCommand(server);
                } catch (Exception e) {
                    e.printStackTrace();
                }
            });
        }
    }

    private static void executeCommand(String server) throws Exception {
        ProcessBuilder processBuilder = new ProcessBuilder("ssh", server, COMMAND);

        FileOutputStream fileOut = new FileOutputStream(TMP_FILE); // temporary file to store command output

        Process process = processBuilder.start(); 

        try (InputStream inputStream = process.getInputStream()) {
            byte[] buffer = new byte[1024];
            int bytesRead;

            while ((bytesRead = inputStream.read(buffer)) != -1) {
                fileOut.write(buffer, 0, bytesRead);
            }
        }

        process.waitFor(); // wait for the command to finish

        try (BufferedReader reader = 
                     new BufferedReader(new InputStreamReader(process.getErrorStream()))) {

            String line;

            while ((line = reader.readLine()) != null) {
                System.err.println(line); // handle error stream
            }
        }

        fileOut.close(); // close temporary file

        Files.deleteIfExists(TMP_FILE.toPath()); // clean up the temp file
    }
}
``` 
This example assumes you have SSH access to all servers and that 'ls -l /' command exists on all of them. You would need to replace it with your actual commands, adjust thread pool size according to how many servers you plan to monitor, and handle exceptions properly in a production environment. This code also does not include any mechanism for retrying failed commands or handling transient network issues. For such features, you may want to look into libraries like Apache Commons Exec or Guava's RetryingCallable.
