public class Configuration {
    public Credentials credentials;
    public string connectionString;
    public ICallback callbackFunction;
}

public class Credentials {
    public string username;
    public string password;
}

public interface ICallback {
    bool CanHandle(object data);
}

public static string ValidateAndDecryptPassword(Configuration configuration, byte[] key, byte[] iv) {
    if (configuration == null || 
        configuration.credentials == null ||
        String.IsNullOrEmpty(configuration.credentials.username) || 
        String.IsNullOrEmpty(configuration.credentials.password)) {
        throw new Exception("Invalid credentials");
    }

    if (String.IsNullOrEmpty(configuration.connectionString)) {
        throw new Exception("Connection string cannot be empty or null");
    }

    if (configuration.callbackFunction == null) {
        throw new Exception("Callback function cannot be null");
    }

    try {
        using (Aes aes = Aes.Create()) {
            ICryptoTransform decryptor = aes.CreateDecryptor(key, iv);
            byte[] encryptedBytes = Convert.FromBase64String(configuration.credentials.password);

            byte[] decryptedBytes;
            using (MemoryStream msDecrypt = new MemoryStream(encryptedBytes)) {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read)) {
                    using (BinaryReader brDecrypt = new BinaryReader(csDecrypt)) {
                        decryptedBytes = brDecrypt.ReadBytes(encryptedBytes.Length);
                    }
                }
            }

            return Encoding.UTF8.GetString(decryptedBytes);
        }
    } catch (CryptographicException ex) {
        throw new Exception("Error during decryption", ex);
    }
}
```

