    const cJSON *logLevel = cJSON_GetObjectItemCaseSensitive(configJson, "log_level");
    if (!cJSON_IsString(logLevel) || (strcmp(logLevel->valuestring, "INFO") != 0 && strcmp(logLevel->valuestring, "DEBUG") != 0 && strcmp(logLevel->valuestring, "ERROR") != 0)) {
