['Here is a simplified example using C# async/await, StreamReader to read logs line by line, SHA256 for hashing, and ZipArchive to compress files. Error handling and logging are also included:

```CSharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

class Program
{
    static async Task ProcessLogFile(string filePath)
    {
        try
        {
            using (var reader = new StreamReader(filePath))
            {
                string line;
                using (var zipArchive = ZipFile.Open("output.zip", ZipArchiveMode.Create))
                {
                    int entryNumber = 1;
                    while ((line = await reader.ReadLineAsync()) != null)
                    {
                        byte[] bytes = Encoding.UTF8.GetBytes(line);
                        using (var sha256Hash = SHA256.Create())
                        {
                            byte[] hashBytes = sha256Hash.ComputeHash(bytes);
                            string hashString = BitConverter.ToString(hashBytes).Replace("-", String.Empty);

                            var entry = zipArchive.CreateEntry($"{entryNumber}.txt");
                            using (var entryStream = entry.Open())
                            using (var writer = new StreamWriter(entryStream))
                            {
                                await writer.WriteLineAsync(hashString);
                            }
                        }

                        ++entryNumber;
                    }
                }
            }
        }
        catch (Exception e)
        {
            Console.Error.WriteLine("Error while processing file: " + e);
        }
    }

    static void Main(string[] args)
    {
        var tasks = new Task[args.Length];
        for (int i = 0; i < args.Length; ++i)
            tasks[i] = ProcessLogFile(args[i]);

        Task.WhenAll(tasks).Wait();
    }
}
```

This code reads a log file line by line, hashes each line using SHA-256 and writes the hash to an entry in a zip archive. The resulting entries are stored in the output.zip file for long term storage. The function can handle multiple files at once due to the use of asynchronous I/O operations with `async`/`await` and `Task.WhenAll` to start all processing tasks simultaneously, utilizing modern hardware's full parallelism potential.

