['Here is the C# code that meets your criteria: 

```CSharp
using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Threading;
using Serilog;

public class DecryptionManager : IDisposable
{
    private readonly ConcurrentDictionary<string, Aes> _aesInstances = new ConcurrentDictionary<string, Aes>();
    private bool _disposedValue;

    public void Dispose() => Dispose(true);

    protected virtual void Dispose(bool disposing)
    {
        if (!_disposedValue)
        {
            if (disposing)
            {
                foreach (var aes in _aesInstances.Values)
                    aes.Dispose();

                Log.Information("DecryptionManager disposed.");
            }

            _disposedValue = true;
        }
    }

    public void DecryptMessage(string message, byte[] key, byte[] iv, out string decrypted)
    {
        if (key == null || key.Length <= 0) 
            throw new ArgumentNullException(nameof(key));

        if (iv == null || iv.Length <= 0) 
            throw new ArgumentNullException(nameof(iv));

        try
        {
            using var aes = _aesInstances.GetOrAdd(Convert.ToBase64String(key), _ => CreateAes());
            aes.Key = key;
            aes.IV = iv;

            using var decryptor = aes.CreateDecryptor();
            byte[] bytesMessage = Convert.FromBase64String(message);
            byte[] decryptedBytes = decryptor.TransformFinalBlock(bytesMessage, 0, bytesMessage.Length);

            decrypted = System.Text.Encoding.UTF8.GetString(decryptedBytes);

            Log.Information("Successfully decrypted a message.");
        }
        catch (Exception ex)
        {
            Log.Error(ex, "Failed to decrypt a message.");
            throw;
        }
    }

    private static Aes CreateAes()
    {
        var aes = Aes.Create();
        aes.Mode = CipherMode.CBC;
        aes.Padding = PaddingMode.PKCS7;

        return aes;
    }
}
```
This code creates an `AES` instance for each unique encryption key and uses it to decrypt messages in parallel using the `DecryptMessage` method. It uses Serilog, but you can replace it with your logging framework of choice. This class is thread-safe as it only modifies internal state that doesn't leak between threads (i.e., only reads are performed). It's also IDisposable to ensure all resources are properly cleaned up when the `DecryptionManager` goes out of scope or gets disposed.
']

['Here's a basic example of how you might accomplish this task using C# and .NET Core. This code uses GZipStream to read from GZIP compressed files and BinaryFormatter for deserialization. 

```csharp
using System;
using System.IO;
using System.IO.Compression;
using System.Runtime.Serialization.Formatters.Binary;

public static T LoadAndDeserialize<T>(string filePath, CompressionMethod compression) where T : class
{
    try
    {
        using (var sourceStream = new FileStream(filePath, FileMode.Open))
        {
            Stream compressedStream;

            // Decompress the file based on selected method
            switch (compression)
            {
                case CompressionMethod.GZip:
                    compressedStream = new GZipStream(sourceStream, CompressionMode.Decompress);
                    break;

                default:
                    throw new ArgumentException("Unsupported compression method");
            }

            // BinaryFormatter is IDisposable, so wrap it in a using statement to ensure that it gets disposed of properly.
            using (var decompressionStream = compressedStream)
            {
                var formatter = new BinaryFormatter();

                // Read from the stream and deserialize the object graph.
                return (T)formatter.Deserialize(decompressionStream);
            }
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine(ex.Message);  // Replace this with a logging system

        throw;
    }
}

public enum CompressionMethod
{
    GZip,
    Zip  // You may add more compression methods here
}
```

