['Here is a basic Rust implementation of your requirements. It uses std::fs for file system operations and std::env for environment variable management, std::sync::Once for thread-safety, std::sync::atomic for atomic operation, std::thread for handling concurrent threads, and tokio::runtime::Handle for graceful shutdown on application exit.

```rust
use std::fs;
use std::env;
use std::sync::{Once, Arc};
use std::sync::atomic::{AtomicBool, Ordering};
use std::thread;
use tokio::runtime::Handle;

static IS_SET: AtomicBool = AtomicBool::new(false);
static LOGGER: Once = Once::new();

pub fn manage_directory_and_env(dirname: &str, envvar: &str) {
    let dirpath = format!["/tmp/{}", dirname]; // TODO: Use appropriate path for your use case

    let logger;

    {
        let _guard = LOGGER.get_or_init(|| {
            // Initialize a custom logger here
            // e.g., env_logger::builder().filter_level(log::LevelFilter::Info).init();
            None 
        });

        if IS_SET.load(Ordering::Relaxed) {
            let current_value = env::var(envvar).unwrap_or("".to_string());

            if current_value == dirpath {
                return;
            } else {
                // Directory exists, but the environment variable is not set to this directory
                fs::remove_dir_all(&dirpath).expect(format![ "Failed to remove directory: {}", &dirpath]);
            }
        }

        if !fs::metadata(&dirpath).is_some() {
            fs::create_dir(&dirpath)
                .map_err(|e| format!)("Failed to create directory: {}\n{}", &dirpath, e);

            env::set_var(envvar, dirpath);
        } else if !IS_SET.load(Ordering::Relaxed) {
            // Directory already exists, but environment variable is not set
            env::set_var(envvar, &dirpath).unwrap();

            IS_SET.store(true, Ordering::Release);
        }
    }

    let rt = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build().unwrap();

    Handle::<Arc<dyn Send>>::spawn(rt, async {
        thread::sleep(std::time::Duration::from_millis(500)); // Do other tasks here... 
    });
}
```
Please note that this is a simplified example and real-world application would need to handle cases like file system errors, race conditions between threads etc. Also, handling of environment variables might be platform-dependent. This code doesn't show how to integrate with an external logging service or set up custom logger. For performance optimization, one could use caching for directories and environment variable lookups, batch processing for directory creation, async operations when interacting with file system etc.
']

