# Define a class for the JSON Factory 
class JSONFactory:
    registry = {}

    @classmethod
    def register(cls, id: str):
        def inner(wrapped_class) -> None:
            if id in cls.registry:
                print('JSONFactory: updating existing class for ID', id)
            else:
                print('JSONFactory: registering new class for ID', id)
            cls.registry[id] = wrapped_class
        return inner

    @classmethod
