    new_record->value = key + offset;
}

void print_max_records(Record **records, int count) {
    Record *max_record = records[0];
    for (int i = 1; i < count; ++i) {
        if (records[i]->value > max_record->value) {
            max_record = records[i];
        }
    }

    // Print the record with maximum value
    printf("Maximum value: %d\n", max_record->value);
    for (int i = 0; i < count; ++i) {
        if (records[i]->value == max_record->value) {
            printf("Identifier: %s, Key: %d\n", records[i]->identifier, i);
        }
    }
}

void free_memory(Record **records, int count){
