    static std::vector<Record> records;
    static std::mutex mtx;
public:
    void add(int key) {
        if (records.size() >= 100) {
            std::cerr << "Error: Array is full" << std::endl;
            return;
        }
        Record record{key};
        mtx.lock();
        records.push_back(record);
        std::sort(records.begin(), records.end());
        mtx.unlock();
    }

    void remove(int key) {
        mtx.lock();
        auto it = std::find_if(records.begin(), records.end(), 
            [&](const Record & rec){ return rec.val == key; });
        if (it != records.end()) records.erase(it);
        mtx.unlock();
    }
};
std::vector<Record> RecordsManager::records{};
std::mutex RecordsManager::mtx{};
