typedef struct memory_pool {
    pthread_mutex_t lock;
    void* start_addr;
    size_t total_size;
    size_t used_size;
} memory_pool_t;

memory_pool_t* create_memory_pool(size_t size) {
    memory_pool_t* pool = malloc(sizeof(memory_pool_t));
    if (pool == NULL) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->total_size = size;
    pool->start_addr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    return pool;
}

void* allocate_memory(memory_pool_t* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if (pool->total_size - pool->used_size < size) {
        // Handle out of memory condition. Maybe extend the pool?
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    void* addr = pool->start_addr + pool->used_size;
    pool->used_size += size;

    pthread_mutex_unlock(&pool->lock);

    return addr;
}

void deallocate_memory(memory_pool_t* pool, void* addr) {
    // Deallocation is not handled in the current skeleton. 
    // It could be as simple as ignoring the request or could be more complex depending on the requirements.
}

void destroy_memory_pool(memory_pool_t* pool) {
    munmap(pool->start_addr, pool->total_size);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}
```

