        return substr(str_shuffle("0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"), 0, $length);
    }

    public function passwordHash($password) {
        return password_hash($password, PASSWORD_BCRYPT);
    }

    public function verifyPassword($password, $hash) {
        return password_verify($password, $hash);
    }

    private function writeFileAsync($filename, $content) {
        $filePath = $this->directory . '/' . $filename;
        $cmd = "echo '$content' > $filePath &";
        exec($cmd);
    }

    private function readFileAsync($filename) {
        $filePath = $this->directory . '/' . $filename;
        $cmd = "cat $filePath";
        return shell_exec($cmd);
    }

    public function fileOperation($method, $filename, $content = null) {
        $ext = pathinfo($filename, PATHINFO_EXTENSION);
        if (!in_array($ext, $this->allowedExtensions)) return "Invalid extension";

        $mimeType = mime_content_type($filename);
        if (!in_array($mimeType, $this->mimeTypes)) return "Unsupported file format";

        switch ($method) {
            case 'POST':
                if (empty($content)) return "No content provided";
                $this->writeFileAsync($filename, $content);
                break;

            case 'GET':
                return $this->readFileAsync($filename);

            default:
                return "Invalid method";
        }
    }

    public function logRequest($method, $status, $errorMessage = null) {
        $logEntry = $method . ' - ' . date('Y-m-d H:i:s') . ' - ' . $status;

        if (!empty($errorMessage)) $logEntry .= " - Error Message: $errorMessage";

        $file = fopen("./request_log.txt", "a");
        fwrite($file, $logEntry . PHP_EOL);
        fclose($file);
    }
}
?>
