#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/time.h>

typedef struct {
    int protocolVersion;
    int sequenceNumber;
    time_t timestamp;
    size_t payloadLength;
} PacketHeader;

struct PacketArray {
    pthread_mutex_t lock;
    PacketHeader* headers;
    size_t count;
    size_t capacity;
};

typedef struct PacketArray packet_array_t;

packet_array_t* initPacketArray(size_t initialCapacity) {
    packet_array_t* arr = malloc(sizeof(packet_array_t));
    pthread_mutex_init(&arr->lock, NULL);
    arr->count = 0;
    arr->capacity = initialCapacity;
    arr->headers = calloc(initialCapacity, sizeof(PacketHeader));
    return arr;
}

void addToArray(packet_array_t* array, PacketHeader header) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        // Reallocate when full. This operation can cause significant delays.
        size_t newCapacity = array->capacity * 2;
        PacketHeader* newHeaders = realloc(array->headers, newCapacity);
        if (!newHeaders) {
            pthread_mutex_unlock(&array->lock);
            return;
        }

        array->headers = newHeaders;
        array->capacity = newCapacity;
    }

    array->headers[array->count++] = header;

    pthread_mutex_unlock(&array->lock);
}
``` 
