```javascript
function recursiveDOMTraversal(startingNode, selector, callback, options = {}) {
    const results = [];
    let depth = 0;

    function traverseDFS(node) {
        if (!node || depth > options.maxDepth || results.length > options.memoryThreshold) return;

        // Apply the selector check and push to results array
        const element = node.matches ? 
            node.matches(selector) ? node : null :
            node.querySelectorAll(selector);

        if (element !== null) {
            [...element].forEach((node) => {
                results.push(node);
                depth++;
                traverseDFS([...node.children]);
            });
        } else {
            traverseBFS([...node.children])
        }
    }

    function traverseBFS(nodes) {
        if (!nodes || nodes.length === 0 || depth > options.maxDepth || results.length > options.memoryThreshold) return;

        const nextLevelNodes = [];
        for (let node of nodes) {
            traverseDFS(node);
            nextLevelNodes.push(...node.children);
        }
        depth++;
        traverseBFS(nextLevelNodes);
    }

    if (options.depthFirstTraversal) {
        traverseDFS(startingNode);
    } else {
        traverseBFS([startingNode]);
    }

    // Apply the callback to each found node, if provided
    results.forEach((node) => {
        if (callback && typeof callback === "function") {
            callback(node);
        }
    });
}
```
