void test_suite(char* label, void(*f)()) {
    printf("Test Suite: %s\n", label);

    // Load the module
    void* handle = dlopen("./module.so", RTLD_LAZY); 
    if (!handle) { 
        fprintf(stderr, "dlopen failed: %s\n", dlerror()); 
