extern "C" void manageRecords() {
    sem_t sem;
    if (sem_init(&sem, 0, 1) == -1) {
        std::cerr << "Semaphore initialization failed." << std::endl;
        exit(EXIT_FAILURE);
    }

    const int SIZE = 100;
    long offsets[SIZE];
    int keys[SIZE];

    // Generate unique random integer values.
    for (int i = 0; i < SIZE; ++i) {
        std::uniform_int_distribution<int> dis(0, 10000);
        while (true) {
            keys[i] = dis(MTRandomGenerator::gen);

            // Check for uniqueness
            bool unique = true;
            for (int j = 0; j < i; ++j) {
                if (keys[j] == keys[i]) {
                    unique = false;
                    break;
                }
            }

            if (unique) {
                break;
            }
        }
    }

    // Dynamically allocate memory for records array.
    record* records = nullptr;
    try {
        records = new record[SIZE];
    } catch(std::bad_alloc& ba) {
        std::cerr << "Memory allocation failed: " << ba.what() << '\n';
        exit(EXIT_FAILURE);
    }

    // Safely access and manipulate records using semaphore.
    if (sem_wait(&sem) == -1) {
        std::cerr << "Semaphore wait failed." << std::endl;
        exit(EXIT_FAILURE);
    }

    // Manipulation of 'records' here...

    if (sem_post(&sem) == -1) {
        std::cerr << "Semaphore post failed." << std::endl;
        exit(EXIT_FAILURE);
    }

    delete[] records; // Don't forget to deallocate memory.
    sem_destroy(&sem);  // Clean up semaphore.
}
```
