// Custom memory pools for better performance with high throughput
struct mempool {
    void *data;
    struct mempool *next;
};
typedef struct mempool Mempool;

Mempool *head = NULL, *tail = NULL;
pthread_mutex_t mutex; // Mutex for thread safety

// Custom hash table to store unique keys and their counts
