// Allocate or reuse existing memory for the dataset
void* allocDataset(size_t size) {
    pthread_mutex_lock(&mutex);
    Mempool *node = head;
    while (node != NULL && node->data != NULL) 
        node = node->next;

    if (node == NULL || node->data == NULL) { // No available memory, allocate new
        void* data = malloc(size);
        Mempool *newNode = malloc(sizeof(Mempool));
        newNode->data = data;
        newNode->next = NULL;

        if (head == NULL) head = tail = newNode; // First allocation
        else { // Append to existing list
            tail->next = newNode;
            tail = newNode;
        }
        pthread_mutex_unlock(&mutex);
        return data;
    } 

    node->data = NULL; // Mark as reused
    pthread_mutex_unlock(&mutex);
    return node->next->data; // Return existing memory
}

// Sorting function (quicksort here, can be optimized)
