class DataRecord {
public:
    int userId;
    double transactionAmount;
    std::time_t timestamp;
    bool statusFlag;
};

class RecordManager {
private:
    std::vector<DataRecord*> records;
    size_t maxSize;
    std::mutex mtx; // For concurrency control
public:
    explicit RecordManager(size_t N) : maxSize(N) {}
    ~RecordManager() {
        for (auto& record : records) {
            delete record;
        }
    }

    void addDataRecord(int userId, double transactionAmount, std::time_t timestamp, bool statusFlag){
        if (records.size() >= maxSize) {
            throw std::out_of_range("Records list overflow");
        }

        DataRecord* newRecord = new DataRecord{userId, transactionAmount, timestamp, statusFlag};

        std::lock_guard<std::mutex> lock(mtx); // Lock the mutex to synchronize access from multiple threads
        records.push_back(newRecord);
    }

    DataRecord* getDataRecord(size_t index) {
        if (index >= records.size()) {
            throw std::out_of_range("Index out of range");
        }

        return records[index]; 
    }

    void updateDataRecord(size_t index, double newAmount, bool newFlag) {
        if (index >= records.size()) {
            throw std::out_of_range("Index out of range");
        }

        DataRecord* recordToUpdate; 

        { // lock scope
            std::lock_guard<std::mutex> lock(mtx); // Lock the mutex to synchronize access from multiple threads
            recordToUpdate = records[index];
        }

        if (recordToUpdate) {
            DataRecord tmp(*recordToUpdate); 

            tmp.transactionAmount = newAmount;
            tmp.statusFlag = newFlag;

            std::lock_guard<std::mutex> lock(mtx); // Lock the mutex to synchronize access from multiple threads
            *recordToUpdate = tmp;
        }
    }
};
