```c
#include <openssl/evp.h>
#include <openssl/err.h>
#include <openssl/aes.h>
#include <string.h>

// Define the PBKDF2 iteration count (this can be configured)
#define ITERATIONS 10000

EVP_CIPHER_CTX *initializeAES(char* password, unsigned char** key) {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher = EVP_aes_256_cbc();

    if(!(ctx = EVP_CIPHER_CTX_new())) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    // Derive encryption key from the password using PBKDF2 (with a configurable number of iterations)
    if(!PKCS5_PBKDF2_HMAC(password, strlen(password), NULL, 0, ITERATIONS, EVP_sha384(), AES_KEYLEN, *key)) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize the cipher with the derived key and IV (initialization vector)
    if(!EVP_EncryptInit_ex(ctx, cipher, NULL, *key, NULL)) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Return the context for further use with encryption and decryption functions
    return ctx;
}
```
