#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int NAS_MESSAGE;
} NAS_MESSAGE;

typedef struct {
    int UE_ID;
} UE_ID;

typedef struct NR_UPLINK_NAS_TRANSPORT {
    NAS_MESSAGE nas_message;
    UE_ID ue_id;
    int sequence_number;
    int message_type;
} NR_UPLINK_NAS_TRANSPORT;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocateMemory(size_t nr, size_t *successfulAllocations) {
    pthread_mutex_lock(&mutex);  // lock thread to prevent race conditions

    NR_UPLINK_NAS_TRANSPORT* list = malloc(nr * sizeof(NR_UPLINK_NAS_TRANSPORT));
    if (list == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    } 

    for (int i = 0; i < nr; ++i) {
        // Here, you would typically use an external source of random numbers. 
        list[i].sequence_number = rand() % INT_MAX;  

        int messageType = rand() % INT_MAX;
        if (i > 0 && list[i-1].message_type == messageType) { // Ensure no two consecutive messages have the same type
            --i;  // retry with a different message type
            continue;
        }

        list[i].message_type = messageType;  
    }

    pthread_mutex_unlock(&mutex);  // unlock thread

    *successfulAllocations = nr;
    return (void*)list;
}
```
This function takes as input the number of elements to allocate, and a pointer to an integer that will be used to store the number of successfully allocated memory blocks. It then performs a series of checks to ensure that the allocation was successful, if not, it outputs an error message and returns NULL. 

The mutex is locked before the memory allocation is attempted to prevent other threads from trying to allocate memory at the same time, which could result in data corruption or race conditions. After the memory has been successfully allocated, the mutex is unlocked so that other threads can access the function concurrently. 

After this, a for loop iterates over each element of the list and populates its fields with random values using `rand()` which returns a pseudo-random integer. The `message_type` field is checked to ensure that no two consecutive messages have the same type. If they do, it decrements `i` so that the current iteration can be tried again with different message types. 

Finally, the pointer to the allocated memory is casted and returned as a void pointer for flexibility when used in other contexts. The count of successfully allocated structures is stored in the passed integer variable through pointer de-referencing.
']

