['Here is a basic C code example for your task:

```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <sys/stat.h>

typedef struct {
    long int offset;
    int key;
} record;

int validateJpeg(const char* fileName) {
    struct stat st;
    if (stat(fileName, &st) == 0) {
        FILE *fp = fopen(fileName, "rb");
        if (!fp) return 0; // Unable to open the file

        int header[2];
        if(fread(header, sizeof(int), 2, fp) != 2) {
            fclose(fp);
            return 0; // Invalid JPEG Header
        }

        fclose(fp);
        if (header[0] == 0xFFD8FF && header[1] >= 0xE0 && header[1] <= 0xEF) {
            return 1; // Valid JPEG File
        } else {
            return 0; // Invalid JPEG File
        }
    } else {
        return 0; // Unable to access the file
    }
}

int processImageAndGenerateReport(const char* inputFileName, const char* outputPdfName, int maxRecordValue) {
    if (!validateJpeg(inputFileName)) {
        printf("Error: Invalid JPEG Image.\n");
        return -1;
    }

    // Conversion to PDF using external tool (imagemagick convert in this case)
    char command[256];
    sprintf(command, "convert %s %s", inputFileName, outputPdfName);
    if (system(command)) {
        printf("Error: Failed to Convert JPEG Image.\n");
        return -1; // Conversion Error
    }

    long int *offsetArray = malloc(sizeof(long int) * maxRecordValue);
    int *keyArray = calloc(maxRecordValue, sizeof(int));
    record *recordArray = malloc(sizeof(record) * maxRecordValue);

    if (!offsetArray || !keyArray || !recordArray) {
        printf("Error: Memory Allocation Failed.\n");

        free(offsetArray);
        free(keyArray);
        free(recordArray);

        return -1; // Memory Error
    }

    for (int i = 0; i < maxRecordValue; i++) {
        recordArray[i].offset = rand();
        recordArray[i].key = rand() % maxRecordValue;
    }

    printf("Success: PDF Converted and Records Generated.\n");

    free(offsetArray);
    free(keyArray);
    free(recordArray);

    return 1; // Success
}
```
This code uses `stat` to check if the file exists and is accessible, then checks the JPEG header to validate the image. It runs a system command using the `system` function to convert the input JPEG image into a PDF output file. Memory for three arrays (offsetArray, keyArray, and recordArray) are allocated before filling them with random values. Finally, it frees all the allocated memory and returns an appropriate status code indicating whether or not the operation was successful.
']

