```C
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct PHY_FRAME_HEADER_T {
    int SEQUENCE_NUMBER;
    int PREAMBLE_TYPE;
    double TRANSMIT_POWER;
    char CHANNEL_QUALITY_INDICATOR;
} PHY_FRAME_HEADER_T;

typedef struct frame_node {
    PHY_FRAME_HEADER_T* frame;
    struct frame_node* next;
} frame_node_t;

frame_node_t* head = NULL;
pthread_mutex_t lock;
int count = 0;

bool addFrame(PHY_FRAME_HEADER_T* frame) {
    // Ensure no two consecutive frames share the same PREAMBLE_TYPE and SEQUENCE_NUMBER combination.
    pthread_mutex_lock(&lock);
    if (head != NULL && head->frame->PREAMBLE_TYPE == frame->PREAMBLE_TYPE 
        && head->frame->SEQUENCE_NUMBER == frame->SEQUENCE_NUMBER) {
        pthread_mutex_unlock(&lock);
        return false;
    }

    // Allocate memory for the new node and assign the frame to it.
    frame_node_t* newNode = malloc(sizeof(frame_node_t));
    if (newNode == NULL) { 
        pthread_mutex_unlock(&lock);
        return false; // Handle memory allocation failure.
    }

    newNode->frame = frame;

    // Add the node to the linked list and update head pointer.
    newNode->next = head;
    head = newNode;

    count++;  // Update count of frames in the list.
    pthread_mutex_unlock(&lock);

    return true;
}
```
This is a simplified version and it doesn't cover all the constraints mentioned above such as handling variable load, concurrency and scalability, real-time processing, performance monitoring, modularity and extensibility, resource constraints etc. 

