char* process_string(const char *input, size_t limit, bool enforce_strict_limit) {
    // Handle null pointers and return NULL if both input string and size limit are null.
    if (input == NULL || limit == 0) {
        return NULL;
    }

    // Allocate memory for the new string. Add one to account for the space or slash character.
    char *new_str = malloc(limit + 2); 
    if (!new_str) {
        return NULL; // Handle allocation failure gracefully by returning NULL.
    }

    // Copy input string upto limit, ensuring trailing spaces are removed.
    size_t i = 0;
    for (; i < limit - 1 && input[i] != '\0'; ++i) {
        new_str[i] = input[i];
    }

    // Remove trailing spaces, if any.
    while (new_str[i-1] == ' ') {
        --i;
    }

    // Depending on the flag, append space or slash character and null terminator to new string. 
    if (enforce_strict_limit && i < limit - 1) {
        new_str[i] = ' ';
        new_str[++i] = '\0';
    } else if (!enforce_strict_limit && input[limit-1] != '\0') {
        new_str[i] = '/';
        new_str[++i] = '-';
        new_str[++i] = '\0';
    } else {
        new_str[i] = '\0';
    }

    return new_str;
}
```

