['Here is a simple C function that fulfills your requirements. It uses dynamic memory allocation to store 'record' structures and random number generation for initializing integer fields. 

```c
#include <stdlib.h>
#include <time.h>
#include <signal.h>

typedef struct record {
    long offset;
    int key;
    double timestamp;
} Record;

static size_t currentSize = 0, maxMemoryLimit = 1024 * 1024 * 1024; //1 GB default limit
static Record* records = NULL;
static struct sigaction oldAction;

void signalHandler(int signum) {
    free(records);
    sigaction(signum, &oldAction, NULL);
}

Record* createRecords(size_t n, int keyRangeStart, int keyRangeEnd) {
    if (currentSize + sizeof(Record) * n > maxMemoryLimit) {
        fprintf(stderr, "Not enough memory.\n");
        return NULL;
    }

    struct sigaction newAction = {{ signalHandler }};
    sigemptyset(&newAction.sa_mask);
    newAction.sa_flags = 0;
    sigaction(SIGINT, &newAction, &oldAction); //handles SIGINT and other signals that could interrupt allocation

    if (!records) { 
        records = malloc(sizeof(Record) * n); //first time allocation
    } else {
        records = realloc(records, currentSize + sizeof(Record) * n); //resize
    }

    for (size_t i = 0; i < n; ++i) {
        Record* r = &records[currentSize / sizeof(Record) + i];

        r->offset = currentSize; //placeholder, may be adjusted according to actual use case
        r->key = keyRangeStart + rand() % (keyRangeEnd - keyRangeStart + 1); 
        r->timestamp = time(NULL);
    }

    currentSize += sizeof(Record) * n; //update size counter
    return records + currentSize / sizeof(Record) - n; //return pointer to the first new record
}
```

This code uses dynamic memory allocation, and also handles resizing of the array when needed. It ensures that a signal interruption during memory allocation does not leave partially allocated memory behind. 

However, it's worth noting that due to the nature of dynamic allocation (which may require frequent system calls for larger allocations) this might be less performant than static memory allocation in situations where performance is critical and there are not many interruptions or process terminations. Also note that the handling of fragmentation depends on the specific C runtime library implementation, and usually involves complex algorithms to maintain a free list which may impact performance.
']

