    if (records == NULL) {
        free(offsets);
        free(keys);
        perror("Memory allocation failed for 'record'");
        exit(EXIT_FAILURE);
    }

    // Assuming we have a function getRandomMessage that returns a random string from a predefined list.
    char* (*getRandomMessage)() = &randomString;

    int value;
    size_t index = 0;
    srand(time(NULL));  // For generating a random seed.

    while (fscanf(file, "%d", &value) == 1) {
        if (index >= bufferSize) {
            bufferSize *= 2;
            offsets = realloc(offsets, sizeof(long) * bufferSize);
            keys = realloc(keys, sizeof(int) * bufferSize);
            records = realloc(records, sizeof(Record) * bufferSize);

            if (offsets == NULL || keys == NULL || records == NULL) {
                free(offsets);
                free(keys);
                for (size_t i = 0; i < index; ++i) {
                    free(records[i].message);
                }
                free(records);

                perror("Reallocation failed");
                exit(EXIT_FAILURE);
            }
        }

        offsets[index] = ftell(file);  // Store file position.
        keys[index] = value;  // Store input value as key.
        records[index].value = rand() % 1000;  // Generate random int.
        records[index].message = strdup((*getRandomMessage)());  // Copy dynamically allocated message string.
        ++index;
    }

    if (ferror(file)) {
        perror("Error reading file");
        free(offsets);
        free(keys);
        for (size_t i = 0; i < index; ++i) {
            free(records[i].message);
        }
        free(records);
        exit(EXIT_FAILURE);
    }

    // Process the arrays...

    free(offsets);
    free(keys);
    for (size_t i = 0; i < index; ++i) {
        free(records[i].message);
    }
    free(records);
}
```
