['Here is a simplified version of how this function might be implemented in C using pthread for thread safety and qsort with custom comparator function for sorting:
```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} Record;

int cmpfunc(const void *a, const void *b) {
    return ( (*((Record *)a))->key - (*((Record *)b))->key );
}

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
void* calculate(void* arg){
    pthread_mutex_lock(&lock);

    srand(time(NULL));
    int size, range;
    printf("Enter the size and the range: ");
    scanf("%d %d", &size, &range);
    if (size > 1000 || size <= 0) {
        puts("Invalid input!");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    Record* records = malloc(size * sizeof(Record));
    int i, j, uniqueCount = 0;
    for (i = 0; i < size; i++) {
        // generate a random key
        int newKey = rand() % range;

        // check if it's already in the records
        bool isUnique = true;
        for (j = 0; j < uniqueCount; j++) {
            if (records[j].key == newKey) {
                i--;  // retry with a different key
                isUnique = false;
                break;
            }
        }

        if (isUnique) {
            records[uniqueCount].offset = 0;  // fill the offset as necessary in your context
            records[uniqueCount].key = newKey;
            uniqueCount++;
        }
    }

    qsort(records, size, sizeof(Record), cmpfunc);

    for (i = 0; i < uniqueCount; i++) {
        printf("Offset: %ld Key: %d\n", records[i].offset, records[i].key);
    }

    free(records);

    pthread_mutex_unlock(&lock);
}
```
Note that this is a simple demonstration and does not include error checking for malloc or scanf, file-based logging, pagination & batch processing, handling large datasets efficiently in distributed systems and unit tests. Implementing these would significantly increase the complexity of the function. The random number generation algorithm used here is rand() % range which might not be suitable for all use cases.
