// Custom memory pool class
class MemoryPool {
public:
    static constexpr size_t POOL_SIZE = 10'000; // Adjust as per requirements.

    MemoryPool() : records_(POOL_SIZE) {}

    Record* allocate() {
        if (index_ >= POOL_SIZE) return nullptr;
        return &records_[index_++];
    }

    void deallocate(Record*) { /* Do nothing, or implement a basic free list. */ }
private:
    std::vector<Record> records_;
    size_t index_{0};
};

// Logging mechanism class.
class Semaphore {
public:
    static unsigned long acquireCount;
    static double totalHoldTime;

    void wait() {
        auto start = std::chrono::high_resolution_clock::now();
        sem_wait(&sem_);
        ++acquireCount;
        auto end = std::chrono::high_resolution_clock::now();
        totalHoldTime += std::chrono::duration<double>(end-start).count();
    }

    void post() { sem_post(&sem_); }
private:
    sem_t sem_;
};
unsigned long Semaphore::acquireCount = 0;
double Semaphore::totalHoldTime = 0.0;

int main() {
    MemoryPool pool;
    Semaphore sem;

    for (size_t i=0; i<1'000'000; ++i) { // Adjust as per requirements.
