#include <errno.h>

typedef struct {
    long offset;
    int key;
    double timestamp;
} record_t;

static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
FILE* logfile;
const char *logfilename = "/var/log/converter.log";
int successfulConversions = 0;

void writeLog(char *msg) {
    pthread_mutex_lock(&log_lock);
    fprintf(logfile, "%s\n", msg);
    pthread_mutex_unlock(&log_lock);
}

int createDirIfNotExists(const char *dirname) {
    struct stat st = {0};
    if (stat(dirname, &st) == -1) {
        mkdir(dirname, 0755); // or whatever permissions you want
    }
}

void* convertFileToPdfAsync(void *arg) {
    char *filename = (char *)arg;

    clock_t startTime = clock();
    if (system("third-party-tool --input " + filename + " --output outputDir/") < 0) {
        writeLog(strcat(filename, ": Conversion failed"));
        pthread_exit((void *)-1);
    } else {
        successfulConversions++;
        clock_t endTime = clock();
        double elapsedTime = (double)(endTime - startTime) / CLOCKS_PER_SEC;

        char msg[256];
        sprintf(msg, "%s: Conversion successful. Elapsed time: %f", filename, elapsedTime);
        writeLog(msg);
    }

    pthread_exit((void *)0);
}

int convertAndProcessFile(const char *filename, const char *outputDir) {
    if (access(filename, F_OK) == -1 || access(filename, R_OK) == -1) {
        return 1; // file does not exist or is unreadable
    }

    createDirIfNotExists(outputDir);

    pthread_t threadId;
    int ret = pthread_create(&threadId, NULL, convertFileToPdfAsync, (void *)filename);
    if (ret != 0) {
        writeLog("Thread creation failed");
        return 1; // could not create thread for conversion
    }

    void *status;
    pthread_join(threadId, &status);
    if ((long)status == -1) {
        return 1; // conversion failed
    }

    long *offsets = (long *)malloc(sizeof(long)*1024*1024); // large allocation
    int *keys = (int *)malloc(sizeof(int)*1024*1024); 
    double *timestamps = (double *)malloc(sizeof(double)*1024*1024);

    if (!offsets || !keys || !timestamps) {
        return 1; // memory allocation failed
    }

    srand(time(NULL)); // initialize random seed
    for (int i = 0; i < 1024*1024; i++) {
        offsets[i] = rand(); // set to a random value within its range
        keys[i] = rand() % 65536 - 32768; // between -32768 and 32767
        timestamps[i] = (double)rand() / RAND_MAX; // between 0 and 1
    }

    record_t *records = malloc(sizeof(record_t)*1024*1024);
    if (!records) {
        return 1; // memory allocation failed
    }

    for (int i = 0; i < 1024*1024; i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].timestamp = timestamps[i];
    }

    // ... continue with processing the data in records

    free(records);
    free(timestamps);
    free(keys);
    free(offsets);

    return 0;
}
```
This code is intended to be a starting point, and may require additional adjustments based on the specific third-party tool you are using. The memory management strategy used here is quite naive for large data sets and is not suitable for production use, but it should illustrate how you might approach this problem in C. 

Please note that error handling and logging are kept simple for the sake of brevity, and real-world code would need to provide more detailed logs and handle a variety of error cases better. For example, if the third-party tool fails repeatedly or consistently, you could consider adding a retry mechanism, or using an alternative tool as needed.
']

