void populate_crc_indications(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if(newNode == NULL) {
        printf("Memory allocation failed. Could not add new node\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    newNode->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->RNTI = RNTI;
    newNode->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->CRCFLAG = rand(); // Generating a random number as unique CRCFLAG.

    NFAPI_CRC_INDICATION_PDU_T *temp = head;

    if(temp == NULL) {
        newNode->next = NULL;
        head = newNode;
    } else {
        while(temp->next != NULL) { 
            // Check for uniqueness of CRCFLAG within the list.
            if(temp->CRCFLAG == newNode->CRCFLAG) {
                printf("Generated non-unique CRCFLAG, generating again.\n");
                newNode->CRCFLAG = rand(); 
                continue;
            }
            temp = temp->next;
        }   

        if(temp->CRCFLAG == newNode->CRCFLAG) {
            printf("Generated non-unique CRCFLAG, generating again.\n");
            newNode->CRCFLAG = rand(); 
        } else {
            temp->next = newNode;
            newNode->next = NULL;
        }
    }

    pthread_mutex_unlock(&lock);
}
