// Simple dynamic array implementation
typedef struct {
    PacketHeader *array;
    size_t used;
    size_t size;
} Array;

void initArray(Array *a, size_t initialSize) {
    a->array = malloc(initialSize * sizeof(PacketHeader));
    a->used = 0;
    a->size = initialSize;
}

void insertArray(Array *a, PacketHeader element) {
    if (a->used == a->size) {
        a->size *= 2;
        a->array = realloc(a->array, a->size * sizeof(PacketHeader));
    }
    a->array[a->used++] = element;
}

void freeArray(Array *a) {
    free(a->array);
    a->array = NULL;
    a->used = a->size = 0;
}
