#include <vector>
#include <mutex>
#include <thread>
#include <atomic>
#include <boost/log/trivial.hpp>
#include <snappy.h>

struct TransactionRecord {
  // fields go here
};

class TransactionPool {
private:
  std::vector<TransactionRecord*> pool;
  std::mutex mtx;
  std::atomic<bool> compressing{false};
public:

  void add(TransactionRecord *record) {
    std::lock_guard<std::mutex> lock(mtx);
    pool.push_back(record);

    if (pool.size() > SOME_LIMIT && !compressing) {
      compressing = true;

      std::thread([&](){
        BOOST_LOG_TRIVIAL(info) << "Compression started";

        // Perform compression here...

        BOOST_LOG_TRIVIAL(info) << "Compression ended";
        compressing = false;
      }).detach();
    }
  }

  TransactionRecord* get() {
    std::lock_guard<std::mutex> lock(mtx);

    if (pool.empty()) return nullptr;

    auto record = pool.back();
    pool.pop_back();
    return record;
  }
};
```
This code provides a very basic approach to a thread-safe memory pool using a `std::vector` as the backing data structure. When the pool is full, it will compress the existing data in a separate thread without blocking other operations. The actual implementation of compression (which would depend on your specific requirements) and error handling have been left out for brevity. 

