```c
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <zlib.h>  // you need to install libz-dev package in Linux (sudo apt install zlib1g-dev)

typedef struct {
    int value;
} Record;

int deserialize(const char* file, long** offsets_out, int** keys_out, Record*** records_out) {
    gzFile fp = gzopen(file, "rb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file %s: %s\n", file, strerror(errno));
        return -1;
    }

    // Read size of arrays and allocate memory
    long array_size = 0;
    gzread(fp, &array_size, sizeof(long));
    *offsets_out = malloc(array_size * sizeof(**offsets_out));
    *keys_out = malloc(array_size * sizeof(**keys_out));
    *records_out = malloc(array_size * sizeof(**records_out));

    if (*offsets_out == NULL || *keys_out == NULL || *records_out == NULL) {
        fprintf(stderr, "Failed to allocate memory: %s\n", strerror(errno));
        gzclose(fp);
        return -1;
    }

    // Read array data
    if (gzread(fp, *offsets_out, sizeof(*offsets_out)) != sizeof(*offsets_out) ||
        gzread(fp, *keys_out, sizeof(*keys_out)) != sizeof(*keys_out) ||
        gzread(fp, *records_out, sizeof(*records_out)) != sizeof(*records_out)) {
        fprintf(stderr, "Failed to read data from file: %s\n", strerror(errno));
        gzclose(fp);
        return -1;
    }

    gzclose(fp);
    return array_size;
}
```
This is a basic example that assumes the file format is a sequence of numbers: first the size of arrays, then the array data. The actual code would be more complex and depend on the specifics of your files. 

