```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char* name;
    double value;
} Item;

typedef struct {
    Item* items;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    double minValue;
    double maxValue;
} DynamicCollection;

DynamicCollection* createDynamicCollection(size_t initialCapacity, double minValue, double maxValue) {
    DynamicCollection* collection = malloc(sizeof(DynamicCollection));
    if (collection == NULL) return NULL;

    pthread_mutex_init(&collection->lock, NULL);
    collection->items = malloc(initialCapacity * sizeof(Item));
    if (collection->items == NULL) {
        free(collection);
        return NULL;
    }

    collection->capacity = initialCapacity;
    collection->count = 0;
    collection->minValue = minValue;
    collection->maxValue = maxValue;
    srand((unsigned int) time(NULL));

    return collection;
}

int addItem(DynamicCollection* collection, const char* name, double value) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        Item* newItems = realloc(collection->items, newCapacity * sizeof(Item));

        if (newItems == NULL) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Failed to allocate memory
        }

        collection->items = newItems;
        collection->capacity = newCapacity;
    }

    Item* item = &collection->items[collection->count++];
    size_t nameLength = strlen(name);
    item->name = malloc(nameLength + 1);

    if (item->name == NULL) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Failed to allocate memory
    }

    strcpy(item->name, name);
    item->value = value;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Successfully added the item
}

// This function should be improved. Currently it just returns a random item from the collection.
Item* getRandomItem(DynamicCollection* collection) {
    if (collection->count == 0) return NULL;

    size_t index = rand() % collection->count;
    return &collection->items[index];
}

void freeDynamicCollection(DynamicCollection* collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->items[i].name);
    }

    free(collection->items);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
``` 

This implementation provides basic functionality for creating, adding, and retrieving items from a dynamic collection. It uses `pthread` library for thread safety, where it locks the mutex when accessing or modifying the item collection to prevent concurrent modifications. The randomness of the value is achieved by seeding the random number generator with the current time, which may not be suitable for all use-cases.

It's important to note that this code doesn't handle all error conditions as specified in the task (e.g., external data sources), and there are many ways to make it more efficient, user-friendly, and maintainable depending on your needs. For example, you might want to optimize reallocations by allocating more memory at once rather than doubling each time, or use a different method for generating random numbers if performance is a concern.
