#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    int value;
    char *buffer;
} Record;

void allocateMemory(long **offsets, size_t offsetCount, int **keys, size_t keyCount, 
                    Record ***records, size_t recordCount, size_t bufferSize) {
    srand((unsigned int)time(NULL)); // seed the random number generator

    *offsets = malloc(sizeof(long) * offsetCount);
    if (*offsets == NULL) exit(EXIT_FAILURE);

    *keys = malloc(sizeof(int) * keyCount);
    if (*keys == NULL) {
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    *records = malloc(sizeof(Record*) * recordCount);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < recordCount; ++i) {
        Record *record = malloc(sizeof(Record));
        if (record == NULL) { // error handling for malloc failure
            free(*offsets);
            free(*keys);
            for (int j = 0; j < i; ++j) {
                free((*records)[j]->buffer);
                free((*records)[j]);
            }
            free(*records);
            exit(EXIT_FAILURE);
        }

        record->value = rand(); // assigning random value to the record
        record->buffer = malloc(sizeof(char) * (bufferSize + 1));
        if (record->buffer == NULL) { 
            free(*offsets);
            free(*keys);
            for (int j = 0; j <= i; ++j) {
                free((*records)[j]->buffer);
                free((*records)[j]);
            }
            free(*records);
            exit(EXIT_FAILURE);
        }

        for (int j = 0; j < bufferSize; ++j) { // generating a unique string
            record->buffer[j] = 'a' + rand() % 26;
        }
        record->buffer[bufferSize] = '\0';
        (*records)[i] = record;
    }
}
