} Collection;

Collection* collection_new(size_t max_items) {
    Collection* col = malloc(sizeof *col);
    if (col == NULL || pthread_mutex_init(&col->mutex, NULL)) goto error;

    atomic_store(&col->count, 0);
    col->max_size = max_items;
    col->items = malloc(max_items * sizeof *col->items);

    if (col->items == NULL) goto error;
    return col;
error:
    free(col->items);
    free(col);
    assert(0 && "memory allocation failed");
}

void collection_destroy(Collection* col) {
    pthread_mutex_lock(&col->mutex);
    for (size_t i = 0; i < atomic_load(&col->count); ++i) {
        free(col->items[i].name);
    }
    pthread_mutex_unlock(&col->mutex);
    pthread_mutex_destroy(&col->mutex);
    free(col->items);
    free(col);
}

int collection_add(Collection* col, const char* name, double value) {
    if (atomic_load(&col->count) >= col->max_size) return 0;

    pthread_mutex_lock(&col->mutex);
    size_t index = atomic_fetch_add(&col->count, 1);
    assert(index < col->max_size);

    Item* item = &col->items[index];
    if (name) {
        item->name = strdup(name);
        if (!item->name) goto error;
    } else {
        item->name = NULL;
    }

    item->value = value;
    pthread_mutex_unlock(&col->mutex);
    return 1;
error:
    atomic_fetch_sub(&col->count, 1);
    pthread_mutex_unlock(&col->mutex);
    assert(0 && "memory allocation failed");
}

Item* collection_get(Collection* col, const char* name) {
    for (size_t i = 0; i < atomic_load(&col->count); ++i) {
        if (name && strcmp(col->items[i].name, name) == 0) return &col->items[i];
    }
    return NULL;
}
```
In this example:
* The `Collection` struct is a thread-safe container for the items.
* Memory allocation failure checks are performed using C's assert macro to halt the program execution when memory allocation fails. This ensures that further operations can proceed safely under partial failure scenarios by checking the return value of malloc and other functions that may fail.
* The `atomic_int_fast64_t` type is used for thread-safe access to shared data.
* The function uses a mutex lock on most operations to ensure thread safety, with exception being direct reads after an atomic load. This ensures low latency but might decrease throughput. Other forms of concurrency control like fine-grained locks or optimistic synchronization can be used depending on the specific requirements and circumstances.
* All functions check if memory allocation fails before modifying shared data. If a failure occurs, all changes are reverted using atomic operations and assert to halt execution.
']

