std::mutex RandomGenerator::s_mutex;

struct record{
    int value;
    char buffer[256];
    int* key;
};

extern "C" {
void manageRecords(long size, int rangeMin, int rangeMax) {
    static std::vector<RandomGenerator> instances;
    static std::mutex mtx;

    if (size <= 0 || rangeMin >= rangeMax) return;

    std::lock_guard<std::mutex> lock(mtx);

    long offsets[size];
    int keys[size];
    record* records = static_cast<record*>(malloc(size * sizeof(record)));
    if (records == NULL) {  // handle memory allocation failures
        std::cerr << "Failed to allocate memory" << std::endl;
        return;
    }

    for (int i = 0; i < size; ++i) {
