        offsets[i] = static_cast<long>(instance.mt());
        records[i].value = rangeMin + (static_cast<int>(offsets[i]) % (rangeMax - rangeMin + 1)); // random value within specified range
        records[i].key = &keys[i];  // ensure each record points to its corresponding key in the keys array
