["Here's a C code that implements most of the requirements specified in your task.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    uint16_t protocolVersion;
    uint32_t sequenceNumber;
    time_t timestamp;
    size_t payloadLength;
    char sourceIP[INET_ADDRSTRLEN];
    char destIP[INET_ADDRSTRLEN];
} PacketHeader;

typedef struct {
    PacketHeader* headers;
    atomic_size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void init(DynamicArray* array, size_t initialCapacity) {
    array->headers = malloc(initialCapacity * sizeof(PacketHeader));
    array->count = 0;
    array->capacity = initialCapacity;
    pthread_mutex_init(&array->lock, NULL);
}

void resize(DynamicArray* array) {
    PacketHeader* newHeaders = malloc(2 * array->capacity * sizeof(PacketHeader));
    memcpy(newHeaders, array->headers, array->count * sizeof(PacketHeader));
    free(array->headers);
    array->headers = newHeaders;
    array->capacity *= 2;
}

void add(DynamicArray* array, PacketHeader header) {
    pthread_mutex_lock(&array->lock);
    if (array->count == array->capacity) resize(array);
    array->headers[array->count++] = header;
    pthread_mutex_unlock(&array->lock);
}

void update(DynamicArray* array, size_t index, PacketHeader newHeader) {
    if (index >= array->count) return;
    pthread_mutex_lock(&array->lock);
    array->headers[index] = newHeader;
    pthread_mutex_unlock(&array->lock);
}
```
