["Here is a simplified implementation in C that covers some of these aspects:

```C
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

typedef struct HashNode {
    int key;
    Record* record;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    size_t capacity;
    size_t size;
    HashNode** nodes;
} HashTable;

HashTable* createHashTable(size_t initialCapacity) {
    HashTable* h = malloc(sizeof(HashTable));
    if (!h) return NULL; // Allocation failure

    h->capacity = initialCapacity;
    h->size = 0;
    h->nodes = calloc(initialCapacity, sizeof(HashNode*));
    if (!h->nodes) { 
        free(h);
        return NULL; // Allocation failure
    }

    return h;
}

void insertRecordIntoTable(HashTable* table, int key, Record* record) {
    size_t index = key % table->capacity; 
    HashNode* node = malloc(sizeof(HashNode));
    if (!node) return; // Allocation failure

    node->key = key;
    node->record = record;
    node->next = table->nodes[index];
    table->nodes[index] = node;
    table->size++; 
}

void destroyHashTable(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode* current = table->nodes[i];

        while (current) {
            HashNode* next = current->next; 
            free(current);
            current = next;
        }
    }

    free(table->nodes);
    free(table);
}

void processData() {
    const size_t initialCapacity = 1024;
    HashTable* table = createHashTable(initialCapacity);
    if (!table) return; // Allocation failure

    long* offsets = malloc(sizeof(long) * 1024);
    if (!offsets) { destroyHashTable(table); return; } // Allocation failure

    int* keys = malloc(sizeof(int) * 1024);
    if (!keys) { free(offsets); destroyHashTable(table); return; } // Allocation failure

    Record* records = calloc(initialCapacity, sizeof(Record));
    if (!records) { free(keys); free(offsets); destroyHashTable(table); return; } // Allocation failure

    srand(time(0)); 
    for (size_t i = 0; i < initialCapacity; ++i) {
        keys[i] = rand(); 
        records[i].value = rand();
        insertRecordIntoTable(table, keys[i], &records[i]);
    }

    // More processing...

    free(records);
    free(keys);
    free(offsets);
    destroyHashTable(table);
}
```
