class CRCHandler {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> list;
    RandomGenerator rndGen;

    sem_t semaphore;
    int acquireCount = 0;
    std::chrono::steady_clock::time_point startTime, endTime;

public:
    CRCHandler() {
        if (sem_init(&semaphore, 0, 1) != 0) {
            throw std::runtime_error("Semaphore initialization failed.");
        }
    }

    ~CRCHandler() {
        sem_destroy(&semaphore);
    }

    void acquireLock() {
        startTime = std::chrono::steady_clock::now();
        ++acquireCount;
        if (sem_wait(&semaphore) != 0) {
            throw std::runtime_error("Semaphore acquisition failed.");
        }
    }

    void releaseLock() {
        endTime = std::chrono::steady_clock::now();
        if (sem_post(&semaphore) != 0) {
            throw std::runtime_error("Semaphore release failed.");
        }
    }

    void printLockStats() const {
        auto elapsed = std::chrono::duration<double>(endTime - startTime).count();
        std::cout << "Acquire count: " << acquireCount << ", Total lock time: " << elapsed << "s" << std::endl;
    }

    void addStructure(NFAPI_CRC_INDICATION_PDU_T newStruct) {
        // Check the last structure's CRCFLAG with the new one. If same, generate a new random value for it until different.
        acquireLock();

        list.push_back(newStruct);

        releaseLock();
    }

};
```
