```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

// Define record structure
typedef struct Record {
    int unique_key;
    int value;
} Record;

// Define a hash table to manage records
#define TABLE_SIZE 10007
Record* hashTable[TABLE_SIZE];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

atomic_int next_key = 0;

// Hash function for keys
unsigned int hash(int key) { return key % TABLE_SIZE; }

void* allocateMemory(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        // Handle memory allocation failure
        printf("Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

// Function to insert a new record
void insertRecord(_Atomic(int)* key, int value) {
    if (value >= TABLE_SIZE || value < 0) {
        printf("Value out of range\n");
        exit(1);
    }
    unsigned int hashIndex = hash(*key);

    pthread_mutex_lock(&lock);
    while (hashTable[hashIndex] != NULL && hashTable[hashIndex]->unique_key != -1) {
        ++hashIndex;
        hashIndex %= TABLE_SIZE;
    }
    hashTable[hashIndex] = allocateMemory(sizeof(Record));
    hashTable[hashIndex]->unique_key = *key;
    hashTable[hashIndex]->value = value;
    pthread_mutex_unlock(&lock);
}

// Function to get a record based on key
Record* lookup(_Atomic(int)* key) {
    unsigned int hashIndex = hash(*key);

    while (hashTable[hashIndex] != NULL) {
        if (hashTable[hashIndex]->unique_key == *key)
            return hashTable[hashIndex];
        ++hashIndex;
        hashIndex %= TABLE_SIZE;
    }
    return NULL;
}
```
