record* create_records(int numRecords, long *offsetsMax, int *keysMax) {
    srand(time(0));

    // Allocate memory for records array
    record *records = malloc(numRecords * sizeof(record));
    if (records == NULL) return NULL;  // Failed to allocate memory

    // Generate offsets and keys
    long *offsets = calloc(*offsetsMax, sizeof(long));
    int *keys = calloc(*keysMax, sizeof(int));
    if (offsets == NULL || keys == NULL) goto error;  // Failed to allocate memory

    for (int i = 0; i < numRecords; ++i) {
        long offset_temp;
        do {
            offset_temp = rand() % *offsetsMax + 1;  // Generates a random number between 1 and offsetsMax
        } while (*offsets + offset_temp > 5000);  // Check if the sum exceeds 5000

        records[i].offset = offset_temp;

        int key_temp;
        do {
            key_temp = rand() % *keysMax + 1;  // Generates a random number between 1 and keysMax
        } while (keys[key_temp] != 0);  // Check if the key is already taken

        records[i].key = key_temp;
        keys[key_temp] = 1;  // Mark the key as used
    }

    free(offsets);
    free(keys);

    return records;

error:  // Cleanup on failure
    if (records != NULL) {
        for (int i = 0; i < numRecords; ++i) {
            if (records[i].buffer != NULL) free(records[i].buffer);
        }
        free(records);
    }

    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);

    return NULL;
}
