#include <stdatomic.h>

// Typedefs for convenience
typedef long Offset;
typedef int Key;
typedef struct Record { /* fields */ } Record;

// Memory pools
Offset* offsetPool = NULL;
Key* keyPool = NULL;
Record** recordPool = NULL;
int poolSize = 0;
