        pthread_mutex_lock(&mutex);  // lock for thread safety

        offsetPool = (Offset*)malloc(array_size * sizeof(Offset));
        keyPool = (Key*)malloc(array_size * sizeof(Key));
        recordPool = (Record**)malloc(array_size * sizeof(Record*));

        if (!offsetPool || !keyPool || !recordPool) {  // handle allocation failures
            free(offsetPool);
            free(keyPool);
            free(recordPool);
            exit(-1);
        }

        for (size_t i = 0; i < array_size; ++i) {  // initialize records
            recordPool[i] = (Record*)malloc(sizeof(Record));
        }
        pthread_mutex_unlock(&mutex);  // unlock after initialization
    }
}
