['Here is the code to solve this problem using pthread, ctime, string.h libraries in C programming language. This solution assumes that the number of unique priorities will not be too large (since it uses a fixed-size array), and thus there are no problems with collisions or resizing. 

```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct task {
    int timestamp;
    int priority_level;
    char* description;
} Task;

#define TABLE_SIZE 1024
Task** hashTable[TABLE_SIZE];
pthread_rwlock_t locks[TABLE_SIZE] = {PTHREAD_RWLOCK_INITIALIZER};

int customHash(int priority) {
    return priority % TABLE_SIZE;
}

void addTaskToHashTable(Task* task) {
    int bucketIndex = customHash(task->priority_level);

    pthread_rwlock_wrlock(&locks[bucketIndex]);

    // Resize the array in the hash table if necessary.
    Task** tasksInBucket = hashTable[bucketIndex];
    int numTasks = 0;
    while (tasksInBucket && tasksInBucket[numTasks]) {
        numTasks++;
    }

    // Allocate a new array if needed.
    Task** newArray;
    if (!tasksInBucket || !tasksInBucket[numTasks]) {
        newArray = calloc(sizeof(Task*), numTasks + 2);  // +1 for the new task, +1 for null terminator.
        memcpy(newArray, tasksInBucket, sizeof(Task*) * numTasks);
    } else {
        newArray = tasksInBucket;
    }

    // Add the task to the end of the array.
    newArray[numTasks] = task;
    newArray[numTasks + 1] = NULL;  // Null terminator for iteration.
    hashTable[bucketIndex] = newArray;

    pthread_rwlock_unlock(&locks[bucketIndex]);
}

Task** getTasksByPriority(int priority) {
    int bucketIndex = customHash(priority);

    pthread_rwlock_rdlock(&locks[bucketIndex]);
    Task** tasksInBucket = hashTable[bucketIndex];
    Task** result = malloc(sizeof(Task*) * TABLE_SIZE);  // Start with a large array.

    for (int i = 0; i < TABLE_SIZE && tasksInBucket && tasksInBucket[i]; i++) {
        if (tasksInBucket[i]->priority_level == priority) {
            result[i] = tasksInBucket[i];
        }
    }

    pthread_rwlock_unlock(&locks[bucketIndex]);

    return result;
}

void initializeTaskSystem(int numTasks) {
    srand((unsigned int) time(NULL));

    for (int i = 0; i < numTasks; i++) {
        Task* task = malloc(sizeof(Task));
        task->timestamp = rand();
        task->priority_level = rand() % TABLE_SIZE;  // Arbitrary priority level.

        char description[256];
        sprintf(description, "Common English word %d", i);  // Randomly chosen string for demonstration purposes.
        task->description = strdup(description);

        addTaskToHashTable(task);
    }
}
```
The `customHash` function uses the modulus operator to distribute tasks across the hash table buckets, and the `addTaskToHashTable` and `getTasksByPriority` functions handle reading and writing to and from the hash table concurrently using pthread rwlocks. The `initializeTaskSystem` function initializes the task system with a given number of randomly generated tasks.
']

