// Global lock to protect memory allocation and random number generation
static pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER;

record* allocateAndInitialize(int arraySize, long minValue, long maxValue, int seed) {
    if (arraySize <= 0) return NULL;

    // Lock to prevent concurrent memory allocation and random number generation
    pthread_mutex_lock(&globalLock);

    // Allocate arrays
    long* offsets = malloc(sizeof(long) * arraySize);
    int* keys = malloc(sizeof(int) * arraySize);
    record* records = calloc(arraySize, sizeof(record));

    if (offsets == NULL || keys == NULL || records == NULL) {
        // Handle memory allocation failure
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_unlock(&globalLock);
        return NULL;
    }

    srand(seed);  // Seed the random number generator

    for (int i = 0; i < arraySize; ++i) {
        int value;
        do {
            value = rand() % ((maxValue - minValue + 1)) + minValue;
        } while (!isUnique(records, i, value));  // Check uniqueness of the random number

        records[i].value = value;
    }

    for (int i = 0; i < arraySize; ++i) {
        keys[i] = rand();
        records[i].offset = &offsets[i];  // Assign a pointer to the offset array in each record
        records[i].key = keys[i];  // Copy key from the key array into each record
    }

    pthread_mutex_unlock(&globalLock);

    return records;
}
