['Here's an example of how you could approach this problem in C, using dynamic memory allocation, hash tables for unique key detection and counting, random number generation and sorting for data distribution. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Record structure
typedef struct {
    int key;
} record_t;

// Hash table for unique keys, using linear probing for collision resolution
record_t* hashTable[10000];
int maxRecords = 0;

void insertHash(int key) {
    int index = abs(key % 10000);
    while (hashTable[index] != NULL && hashTable[index]->key != -1) {
        index++;
        if (index == 10000) {
            index = 0;
        }
    }
    hashTable[index] = malloc(sizeof(record_t));
    hashTable[index]->key = key;
}

int countUniqueKeys() {
    int count = 0;
    for (int i = 0; i < 10000; i++) {
        if (hashTable[i] != NULL && hashTable[i]->key != -1) {
            count++;
        }
    }
    return count;
}

// Random number generation for data distribution
int getRandomInt(int min, int max) {
    return rand() % (max + 1 - min) + min;
}

void randomizeRecords(record_t** records, int recordCount) {
    srand(time(NULL));
    for (int i = 0; i < recordCount; i++) {
        int value = getRandomInt(0, 2147483647); // max int value
        while (hashTable[value % 10000] != NULL && hashTable[value % 10000]->key == value) {
            value = getRandomInt(0, 2147483647); // regenerate if duplicate found in hash table
        }
        records[i]->key = value;
    }
}

// Sorting function for record distribution
int compareRecords(const void* a, const void* b) {
    return ((record_t*)a)->key - ((record_t*)b)->key;
}

void sortRecords(record_t** records, int recordCount) {
    qsort(records, recordCount, sizeof(record_t*), compareRecords);
}

int main() {
    // Memory allocation for offset and key arrays
    long* offsets = malloc(1000 * sizeof(long));
    int* keys = calloc(1000, sizeof(int));

    if (offsets == NULL || keys == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Allocation for unique key records
    int uniqueKeys = 0;
    record_t** records = malloc(uniqueKeys * sizeof(record_t*));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Dynamically resize memory blocks and hash table to accommodate more keys
    for (int i = 0; i < 10000; i++) {
        insertHash(keys[i]);

        if (i % 5 == 0 && i != 0) {
            uniqueKeys = countUniqueKeys();

            // Resize memory blocks and hash table
            offsets = realloc(offsets, (1000 + (i / 5) * 1000) * sizeof(long));
            keys = realloc(keys, (1000 + (i / 5) * 1000) * sizeof(int));

            // Resize records array
            records = realloc(records, uniqueKeys * sizeof(record_t*));
        }
    }

    randomizeRecords(records, uniqueKeys);
    sortRecords(records, uniqueKeys);

    // Cleanup
    free(offsets);
    free(keys);
    for (int i = 0; i < uniqueKeys; i++) {
        free(records[i]);
    }
    free(records);

    return 0;
}
```
This is a simplified example and real-world applications would require more robust error checking, synchronization mechanisms (e.g., mutexes or atomic operations for thread safety), and logging capabilities to fully handle errors and monitor performance metrics.
