#include <pthread.h>

typedef struct {
    double measurement;
    char status_flag;
    size_t identifier;
} DataEntry;

struct Arrays {
    double* measurements;
    char* statuses;
    size_t* identifiers;
};

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize(size_t n, struct Arrays* arrays) {
    if (n < 500) n = 500;
    arrays->measurements = malloc(n * sizeof(double));
    arrays->statuses = malloc(n * sizeof(char));
    arrays->identifiers = malloc(n * sizeof(size_t));
}

void destroy(struct Arrays* arrays) {
    free(arrays->measurements);
    free(arrays->statuses);
    free(arrays->identifiers);
}

int compare_entries(const void * a, const void * b) {
   double f = ((DataEntry*)b)->measurement - ((DataEntry*)a)->measurement; 
   if (f > 0.0) return 1;
   else if (f < 0.0) return -1;
   else return 0;
}

void sort(size_t n, DataEntry* entries) {
    qsort(entries, n, sizeof(DataEntry), compare_entries);
}

size_t count_unique_ids(size_t n, struct Arrays* arrays) {
    size_t *uniques = calloc(n, sizeof(size_t));
    if (!uniques) return 0; // Handle memory allocation failure.

    size_t unique_count = 0;
    for (size_t i = 0; i < n; ++i) {
        pthread_mutex_lock(&lock);
        int already_exists = 0;
        for (size_t j = 0; j < unique_count && !already_exists; ++j) {
            if(uniques[j] == arrays->identifiers[i]) 
                already_exists = 1;
        }

        pthread_mutex_unlock(&lock);

        if (!already_exists) uniques[unique_count++] = arrays->identifiers[i];
    }

    free(uniques); // Avoid memory leak.
    return unique_count;
}
``` 
