        (*records)[i].value = rand();  // Generate random integer value for records
        (*records)[i].log_msg = strdup(log_msg); // Allocate log message and copy it

        struct Node *newNode = malloc(sizeof(struct Node));
        if (newNode == NULL) { error("Memory allocation failed for hash table node"); }

        newNode->key = keys[i];
        newNode->index = i;
        size_t index = hash((*hashTable)[i], size);  // Calculate hash value
        newNode->next = (*hashTable)[index];
        (*hashTable)[index] = newNode;  // Insert into hash table at calculated index
    }
}
```

Please note, that in real application you should consider how to free the allocated memory (records and hashtable) once it is no longer needed. This code just shows the basic idea of using dynamically allocated data structures like arrays and linked lists for records and hash table respectively.
