class TransactionRecord {
public:
    int id;
    double balance;
    std::string type;
    std::time_t timestamp;
    double amount;
};

class TransactionManager {
private:
    std::vector<TransactionRecord> transactions;
    size_t capacity;
    std::mutex mtx;  // mutex for thread safety
public:
    TransactionManager(size_t maxCapacity) : capacity(maxCapacity) {}

    void addTransaction(const TransactionRecord& record) {
        if (transactions.size() == capacity) {
            throw std::out_of_range("Maximum transaction limit reached");
        } else if (!record.type.empty() && record.amount > 0) {
            std::lock_guard<std::mutex> lock(mtx);  // ensures thread safety during push_back operation
            transactions.push_back(record);
        } else {
            throw std::invalid_argument("Invalid transaction");
        }
    }

    TransactionRecord& getTransaction(size_t index) {
        if (index >= transactions.size()) {
            throw std::out_of_range("Index out of range");
        } else {
            std::lock_guard<std::mutex> lock(mtx);  // ensures thread safety during access
            return transactions[index];
        }
    }

    size_t getCapacity() const {
        return capacity;
    }
};
```
In this code, the `TransactionRecord` structure contains fields for transaction ID, account balance, transaction type (credit or debit), timestamp, and transaction amount. The `TransactionManager` class manages a dynamic list of these transactions with an initial maximum capacity set at construction time. The `addTransaction` method adds a new transaction to the list while checking if it's within the limit and valid. The `getTransaction` method returns a reference to a specific transaction, throwing an exception if the index is out of range.

