typedef struct Collection {
    long* offsets;
    int* keys;
    Record* records;
    size_t size;
    pthread_mutex_t mutex;
} Collection;

Collection* init_collection(size_t size) {
    Collection* collection = malloc(sizeof(Collection));
    if (!collection) return NULL;

    collection->offsets = malloc(size * sizeof(long));
    collection->keys = calloc(size, sizeof(int)); // Initialized to zeros
    collection->records = calloc(size, sizeof(Record)); // Initialized to zeros
    collection->size = size;

    if (pthread_mutex_init(&collection->mutex, NULL) != 0) {
        free(collection->offsets);
        free(collection->keys);
        free(collection->records);
        free(collection);
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    return collection;
}

void populate_collection(Collection* collection, int min_value, int max_value) {
    pthread_mutex_lock(&collection->mutex);

    for (size_t i = 0; i < collection->size; ++i) {
        collection->records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    pthread_mutex_unlock(&collection->mutex);
}

void reset_collection(Collection* collection) {
    pthread_mutex_lock(&collection->mutex);

    for (size_t i = 0; i < collection->size; ++i) {
        collection->records[i].value = 0; // or some default value
    }

    pthread_mutex_unlock(&collection->mutex);
}
```

