    void* outputBuffer = malloc(outputBufferSize);
    if (outputBuffer == NULL) {
        printf("Memory allocation failed: %s\n", strerror(errno));
        return 0;
    }

    // Fork a new process for the command execution
    processID = fork();
    if (processID < 0) {
        printf("Failed to create child process: %s\n", strerror(errno));
        free(outputBuffer);
        return 0;
    } else if (processID == 0) { // Child process
        execl("/bin/sh", "sh", "-c", commandToMonitor, NULL);
        printf("Failed to execute command: %s\n", strerror(errno));
        free(outputBuffer);
        exit(-1);
    } else { // Parent process
