            printf("Wait for child failed: %s\n", strerror(errno));
            free(outputBuffer);
            return 0;
        }

        // Check the exit status of the command
        if (WIFEXITED(status)) {
            int exitStatus = WEXITSTATUS(status);

            if (exitStatus != 0) {
