```c
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    char data[50];
} record;

struct result {
    long* offsets;
    int* keys;
    record* records;
    size_t count;
};

struct result* create_records(long* offsets, int* keys, size_t n, int min, int max) {
    if (!offsets || !keys || n <= 0 || min >= max) return NULL;

    srand((unsigned int) time(NULL));
    struct result *res = (struct result*) malloc(sizeof(struct result));
    if (!res) return NULL;

    res->offsets = (long*) malloc(n * sizeof(long));
    res->keys = (int*) malloc(n * sizeof(int));
    res->records = (record*) calloc(n, sizeof(record));
    if (!res->offsets || !res->keys || !res->records) {
        free(res->offsets);
        free(res->keys);
        free(res->records);
        free(res);
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        if (offsets[i] < 1 || keys[i] < min || keys[i] > max) continue;

        res->offsets[res->count] = offsets[i];
