typedef struct {
    char *mode;
    char *key;
} encryption_config_t;

int load_encryption_configuration(char* filename, encryption_config_t *config) {
    FILE *file = fopen(filename, "r");

    if (file == NULL) {
        printf("Failed to open file\n");
        return -1;
    }

    yaml_parser_t parser;
    yaml_token_t token;

    if (!yaml_parser_initialize(&parser)) {
        printf("Failed to initialize parser!\n");
        fclose(file);
        return -1;
    }

    yaml_parser_set_input_file(&parser, file);

    int done = 0;
    while (!done) {
        if(!yaml_parser_scan(&parser, &token)) {
            printf("Parser error %d\n", parser.error);
            break;
        }

        switch(token.type){
            case YAML_KEY_TOKEN: 
                // Extract the key name
                if (strcmp((char*) token.data.scalar.value, "mode") == 0) {
                    done = 1;
                    break;
                } else if (strcmp((char*) token.data.scalar.value, "key") == 0) {
                    yaml_parser_scan(&parser, &token);
                    config->key = strdup((char*) token.data.scalar.value);
                }
                break;
            case YAML_SCALAR_TOKEN: 
                // Extract the scalar value
                if (strcmp((char*) token.data.scalar.value, "mode") == 0) {
                    yaml_parser_scan(&parser, &token);
                    config->mode = strdup((char*) token.data.scalar.value);
                } 
            default: break;
        }
    }

    yaml_parser_delete(&parser);
    fclose(file);

    return 0;
}
```
