['Here is a basic implementation of such a data structure in C using pthreads for multithreading, and an array-based approach with dynamic resizing to handle contention and space efficiency. This example does not implement compaction since it can be quite complex due to the need for efficient key search (usually requiring hashing or trees), and also needs careful handling of concurrency issues which is beyond the scope here.

```C
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    double timestamp;
} Record;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity, count;
    Record* records;
} Collection;

Collection* collection_new(size_t initialCapacity) {
    Collection* c = malloc(sizeof(Collection));
    if (c == NULL) return NULL;

    pthread_mutex_init(&c->lock, NULL);
    c->capacity = initialCapacity;
    c->count = 0;
    c->records = malloc(initialCapacity * sizeof(Record));
    if (c->records == NULL) {
        free(c);
        return NULL;
    }

    return c;
}

void collection_free(Collection* c) {
    pthread_mutex_destroy(&c->lock);
    free(c->records);
    free(c);
}

int collection_insert(Collection* c, Record r) {
    pthread_mutex_lock(&c->lock);

    if (c->count >= c->capacity) {
        size_t newCapacity = c->capacity * 2;
        Record* newRecords = realloc(c->records, newCapacity * sizeof(Record));

        // Reallocation failed.
        if (newRecords == NULL) {
            pthread_mutex_unlock(&c->lock);
            return -1;
        }

        c->capacity = newCapacity;
        c->records = newRecords;
    }

    // Simple linear search for now, could be replaced by more efficient structure.
    size_t index = 0;
    while (index < c->count && c->records[index].key != r.key) ++index;

    if (index == c->count) {
        c->records[c->count++] = r;
    } else {
        c->records[index] = r;
    }

    pthread_mutex_unlock(&c->lock);
    return 0;
}

Record* collection_find(Collection* c, int key) {
    pthread_mutex_lock(&c->lock);

    for (size_t i = 0; i < c->count; ++i) {
        if (c->records[i].key == key) {
            pthread_mutex_unlock(&c->lock);
            return &c->records[i];
        }
    }

    pthread_mutex_unlock(&c->lock);
    return NULL;
}
```
This code will be a good starting point for further optimizations and features. Some of the potential improvements:
1. Use binary search to find record by key, not linear search.
