['```cpp
#include <iostream>
#include <random>
#include <mutex>
#include <map>

// Abstract base class for generator
class RandomGenerator {
public:
    virtual ~RandomGenerator() = default;
    virtual uint32_t generate(uint64_t seed) = 0;
};

// Mersenne Twister Generator
class MT19937 : public RandomGenerator {
public:
    uint32_t generate(uint64_t seed) override {
        std::mt19937 gen(seed);
        return gen();
    }
};

// Linear Congruential Generator
class LCG : public RandomGenerator {
private:
    static const uint64_t m = 2^31 - 1; // Modulus
    static const uint64_t a = 16807;   // Multiplier
    static const uint64_t c = 0;       // Increment
public:
    uint32_t generate(uint64_t seed) override {
        return (a * seed + c) % m;
    }
};

class RandomNumberFramework {
private:
    std::mutex mutex_; 
    std::map<std::string, RandomGenerator*> generators_;
public:
    ~RandomNumberFramework() {
        for (auto &gen : generators_) {
            delete gen.second;
        }
    }

    void add_generator(const std::string& name, RandomGenerator *generator) {
        std::lock_guard<std::mutex> lock(mutex_);
        generators_.insert({name, generator});
    }

    uint32_t generate(const std::string& name, uint64_t seed) {
        auto it = generators_.find(name);
        if (it != generators_.end()) {
            return it->second->generate(seed);
        }
        throw std::runtime_error("Generator not found.");
    }
};
```
In the above code, an abstract base class `RandomGenerator` is used to define a common interface for all generators. Two concrete generator classes are then defined: `MT19937` and `LCG` which inherit from `RandomGenerator` and implement their own versions of the `generate()` function.

The `RandomNumberFramework` class maintains a map of named generators and provides methods to add new generators and generate random numbers using a specific generator. The generation process is thread-safe thanks to a `std::mutex` lock, preventing race conditions when adding or generating numbers concurrently from multiple threads.

Please note that this is an overly simplified implementation and doesn't address the requirements in depth such as external data sources integration, caching mechanism for frequent requests etc. Depending on your needs you might want to design more complex framework taking into consideration these aspects.
