```cpp
#include <vector>
#include <algorithm>
#include <semaphore.h>
#include <mutex>
#include <thread>

std::vector<int> record_vec;
std::mutex mtx; // Mutex for critical section protection
sem_t sem; // Semaphore to handle concurrent access 

void addRecord(int value) {
    sem_wait(&sem); // Wait on the semaphore

    std::lock_guard<std::mutex> lock(mtx); // Critical section start

    record_vec.push_back(value); 
    std::sort(record_vec.begin(), record_vec.end());

    // Critical section end
    sem_post(&sem); // Release the semaphore
}

int main() {
    sem_init(&sem, 0, 1); // Initialize semaphore with initial value of 1
    std::thread t1(addRecord, 5);
    std::thread t2(addRecord, 3);

    t1.join();
    t2.join();

    for (int i : record_vec) {
        printf("%d ", i);
    }

    sem_destroy(&sem); // Destroy the semaphore
    return 0;
}
```
This program first initializes a vector and a binary semaphore. A function `addRecord` is defined to add an integer value to the sorted vector while ensuring thread-safe access via mutex locking. Two threads are created, each inserting a record into the vector concurrently. After all threads finish their tasks, the main function prints out the final content of the sorted vector.

