["Here's a high-level approach in C to solve this problem using pthread library for thread safety, with some simplifications due to lack of context about your complete system:

```c
#include <pthread.h>
#include <stdlib.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* arr;
    size_t capacity;
    size_t count;
} ArrayWrapper;

int createArray(ArrayWrapper *a, size_t initialCapacity) {
    a->arr = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (a->arr == NULL) return -1;  // memory allocation failed

    pthread_mutex_init(&a->lock, NULL);
    a->capacity = initialCapacity;
    a->count = 0;

    return 0;
}

int addEntry(ArrayWrapper *a, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&a->lock);

    if (a->count >= a->capacity) {  // array is full
        pthread_mutex_unlock(&a->lock);
        return -1;
    }

    for(int i=0;i<a->count;i++){     // check if RX_UE_INFORMATION_TAG and RNTI are unique
        if((entry.RX_UE_INFORMATION_TAG == a->arr[i].RX_UE_INFORMATION_TAG) || (entry.RNTI == a->arr[i].RNTI)){
            pthread_mutex_unlock(&a->lock);
            return -1;
        }
    }

    a->arr[a->count] = entry;  // add the entry
    a->count++;

    pthread_mutex_unlock(&a->lock);
    return 0;
}

void resetArray(ArrayWrapper *a){
    pthread_mutex_lock(&a->lock);

    for (int i = 0; i < a->count; i++) {
        a->arr[i].RX_UE_INFORMATION_TAG = -1;
        a->arr[i].RNTI = -1;
    }

    a->count = 0;  // reset the count but keep allocated memory

    pthread_mutex_unlock(&a->lock);
}
```
This code creates an array with initial capacity, and adds entries to it thread safely. Note that this is not the complete solution because it lacks specific details about your problem like the CRCFLAG generation method, batch processing, data source integration etc. This solution assumes you have at least some basic understanding of threads, mutexes, memory management in C, and has made certain simplifications for brevity.
