int fetchFromCache(int msgType) {
    pthread_mutex_lock(&lock); // Ensure thread safety for cache operations.

    time_t currentTime = time(NULL);
    int i, oldestIndex = 0;
    for (i=0; i<cacheSize; i++){ 
        if (cache[i].msgType == msgType) { // If message type found in cache
            cache[i].timestamp = currentTime; // update timestamp as it's recently accessed.
            pthread_mutex_unlock(&lock);
            return cache[i].msgType;
        }

        if(cache[oldestIndex].timestamp > cache[i].timestamp) { 
            oldestIndex = i; // Keep track of the least recently used CacheNode.
        }
    }

    // Replace least recently used item with new msgType
    cache[oldestIndex].msgType = msgType;
    cache[oldestIndex].timestamp = currentTime;

    pthread_mutex_unlock(&lock); 

    return fetchFromExternal(msgType); // If not found in cache, query from external source.
}

