["Here's a basic implementation in C using linked lists with mutex locks for thread safety. The third-party library memory management practices are not considered as they're not specified in the problem statement. 

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Message {
    int messageId;
    time_t timestamp;
    int senderId;
    size_t payloadLength;
    char* status; // sent, received, processing
} Message;

// Node for linked list
typedef struct node {
    Message *message;
    struct node *next;
}Node;

typedef struct LinkedList {
    Node *head;
    Node *tail;
    size_t size;
}LinkedList;

void initMessage(int messageId, int senderId, size_t payloadLength, char* status) {
    Message *message = malloc(sizeof(Message));
    time_t timestamp;

    while (time(&timestamp) == -1){ // Ensure valid timestamp even if API fails.
        continue; 
    }

    message->messageId = messageId;
    message->senderId = senderId;
    message->payloadLength = payloadLength;
    message->status = status;
}

// Add a new node to the end of the list.
void push(LinkedList *list, Message* message) {
    Node *newNode = malloc(sizeof(Node));
    newNode->message = message;
    newNode->next = NULL;

    if (list->head == NULL) { // List is empty.
        list->head = newNode; 
        list->tail = newNode;
    } else { // Append to the tail.
        Node *current = list->head;
        while(current->next != NULL){
            if (message->messageId == current->message->messageId) { // Handle duplicate IDs.
                free(newNode); 
                return;
            }
            current = current->next;
        }

        list->tail->next = newNode;
        list->tail = newNode;
    }

    list->size++;
}

// Retrieve a message by ID.
Message *get(LinkedList *list, int messageId) {
    Node* current = list->head;

    while (current != NULL) {
        if (current->message->messageId == messageId){ 
            return current->message; // Return the first match.
        }

        current = current->next;
    }

    return NULL; // Not found.
}

// Remove a node by ID.
void remove(LinkedList *list, int messageId) {
    Node* previous = NULL;
    Node* current = list->head;

    while (current != NULL) {
        if (current->message->messageId == messageId){ 
            // Update the head or tail if necessary.
            if(previous == NULL) { 
                list->head = current->next;
            } else {
                previous->next = current->next;
            }

            free(current); 
            return;
        }

        previous = current;
        current = current->next;
    }
}
```
The above is a basic implementation and does not handle thread safety. Implementing thread safety will require using mutex locks to prevent data races, which can introduce significant overhead. A more optimal solution would use synchronization mechanisms provided by the operating system or third-party library, such as semaphores or condition variables.
