typedef struct PacketHeader {
    int protocolVersion;
    unsigned long sequenceNumber;
    time_t timestamp;
    size_t payloadLength;
    uint8_t flags;  // Type and Priority flags
} PacketHeader;

typedef struct DynamicArray {
    PacketHeader* packets;
    size_t length;
    size_t capacity;
} DynamicArray;

void initDynamicArray(DynamicArray* a, size_t initialSize) {
    // Initialize dynamic array with given initial size
    a->packets = (PacketHeader*)malloc(initialSize * sizeof(PacketHeader));
    a->length = 0;
    a->capacity = initialSize;
}

void insertDynamicArray(DynamicArray* a, PacketHeader p) {
    // Reallocate memory if necessary
    if (a->length == a->capacity) {
        a->capacity *= 2;
        a->packets = (PacketHeader*)realloc(a->packets, a->capacity * sizeof(PacketHeader));
    }

    // Insert new packet
    a->packets[a->length++] = p;
}

void removeDynamicArray(DynamicArray* a, size_t index) {
    if (index < a->length) {
        // Shift packets to fill the gap
        for (size_t i = index; i < a->length - 1; ++i) {
            a->packets[i] = a->packets[i + 1];
        }

        --a->length;
    }
}

void updateDynamicArray(DynamicArray* a, size_t index, PacketHeader p) {
    if (index < a->length) {
        // Update packet at given index
        a->packets[index] = p;
    }
}

// Other helper functions as required

