#include <mutex>
#include <unordered_map>
#include <vector>
#include <random>

class Record {
public:
    int value;
};

class Collection {
private:
    std::unordered_map<int, Record*> map;  // Use separate chaining for collision handling.
    std::mutex mutex;
    static std::mt19937 gen;  // Random number generator shared across all instances.

public:
    Collection() {}
    ~Collection() {}

    void add(int key) {
        std::lock_guard<std::mutex> lock(mutex);
        if (map.find(key) == map.end()) {  // Avoid duplicate keys.
            Record* record = new Record;
            record->value = gen();  // Assign a random value.
            map[key] = record;
        }
    }

    Record* get(int key) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = map.find(key);
        if (it != map.end()) {
            return it->second;
        } else {
            return nullptr;  // Key not found.
        }
    }
};
```
