```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct metadata {
    int custom_id;
    bool criticality;
    char* data;
} metadata_t;

typedef struct event {
    double num;
    char tag[20];
    char* description;
    struct event* linked_event;
    int timestamp;
    metadata_t* meta;
    pthread_mutex_t lock;
    int refcount;
} event_t;

typedef struct {
    size_t used;
    size_t size;
    char* data;
} mempool_t;

mempool_t pool = {0, 16384, NULL}; // initial size of the pool in bytes
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void* smalloc(size_t sz) {
    pthread_mutex_lock(&pool_lock);
    if (pool.used + sz > pool.size) {
        while (pool.size < pool.used + sz) 
            pool.size *= 2; // double the size until enough space is available

        char* new_data = malloc(pool.size);
        if (new_data == NULL) {
            pthread_mutex_unlock(&pool_lock);
            return NULL; // failed to allocate memory
        }

        memcpy(new_data, pool.data, pool.used);
        free(pool.data);
        pool.data = new_data;
    }

    void* ptr = (char*)pool.data + pool.used;
    pool.used += sz;
    pthread_mutex_unlock(&pool_lock);
    return ptr;
}

void sfree(void* ptr) {
    if ((char*)ptr + sizeof(size_t) == pool.data + pool.used) 
        pool.used -= sizeof(size_t); // free memory at the end of the pool
    else 
        fprintf(stderr, "Invalid pointer to sfree\n");
}

event_t* createEvent(double num, const char* tag, const char* descriptionTemplate[], size_t nTemplates, event_t* linkedEvents[], int timestamp, metadata_t* meta) {
    if (descriptionTemplate == NULL || nTemplates == 0) return NULL; // invalid input data

    srand(time(NULL));
    size_t index = rand() % nTemplates;
    char* description = strdup(descriptionTemplate[index]); // duplicate the template string
    if (description == NULL) return NULL; // failed to allocate memory

    event_t* newEvent = smalloc(sizeof(event_t));
    if (newEvent == NULL) {
        free(description);
        return NULL; // failed to allocate memory for the event struct
    }

    pthread_mutex_init(&newEvent->lock, NULL);
    newEvent->num = num;
    strcpy(newEvent->tag, tag);
    newEvent->description = description;
    newEvent->linked_event = linkedEvents[rand() % (sizeof(linkedEvents) / sizeof(*linkedEvents))]; // select a random event from the list of links
