#include <semaphore.h>

class Semaphore {
private:
    sem_t mutex;
public:
    Semaphore() {
        // initialize binary semaphore 
        // shared between threads 
        sem_init(&mutex, 0, 1); 
    }
    ~Semaphore() {
        sem_destroy(&mutex);
    }
    void wait() {
        // wait until the lock is available and then lock it
        sem_wait(&mutex); 
    }
    void signal() {
        // unlock the mutex
        sem_post(&mutex);
    }
};
```

