    public static IDataReader ExecuteDynamicSqlQuery(string baseCommand, DynamicFilters dynamicFilters, SqlConnection connection) {
        StringBuilder query = new StringBuilder();

        // construct the base command
        query.AppendLine(baseCommand);

        // append filters dynamically
        if (dynamicFilters != null && dynamicFilters.Any()) {
