            // add parameters dynamically and ensure SQL injection prevention
            foreach (var filter in dynamicFilters) {
                cmd.Parameters.AddWithValue("@" + filter.Column, filter.Value);
            }

            return cmd.ExecuteReader();
        }
    }
}

