    size_t len = 0;
    ssize_t read;
    char* line = NULL;
    while ((read = getline(&line, &len, stdin)) != -1) { // Read lines from stdin
        if (i >= 1000) break; 

        strArray[i] = malloc(strlen(line) + 1); // Allocate memory for each string in array
        if (strArray[i] == NULL) exit(-1);

        strcpy(strArray[i], line); // Copy input to allocated memory
        i++;
