typedef struct {
  long* offsets;
  size_t capacity;
  size_t size;
} OffsetArray;

void initOffsetArray(OffsetArray* arr, size_t initialSize) {
  arr->offsets = (long*)malloc(initialSize * sizeof(long));
  arr->capacity = initialSize;
  arr->size = 0;
}

void insertOffset(OffsetArray* arr, long offset) {
  if (arr->size == arr->capacity) {
    // If array is full, resize it by doubling its capacity
    arr->capacity *= 2;
    arr->offsets = realloc(arr->offsets, arr->capacity * sizeof(long));
  }

  arr->offsets[arr->size] = offset;
  arr->size++;
}
