['This task requires a lot of code to be written, and it seems like you're trying to implement multiple features which are not very clear from the text. I will try to address the initial requirement about generating an MD5 hash in C++ using Java, but let me know if this is what you need or if there's more information required for a proper solution.

Below is a simple example of how you could generate an MD5 hash in C++ using JNI and Java. 

This code uses the MessageDigest class from java.security package to get an instance of the MD5 algorithm, then it converts the input string into bytes and updates the digest with those bytes. After that, we complete the digest computation and convert the resulting byte array into a hexadecimal string which represents our MD5 hash:

```cpp
#include <jni.h>
#include <string>

extern "C" {
JNIEXPORT jstring JNICALL
Java_com_example_MainActivity_generateMD5(JNIEnv *env, jobject obj, jstring input) {
    // Get the MessageDigest instance for MD5.
    jclass mdClass = env->FindClass("java/security/MessageDigest");
    jmethodID getInstanceMethod = env->GetStaticMethodID(mdClass, "getInstance", "(Ljava/lang/String;)Ljava/security/MessageDigest;");
    jobject mdObj = env->CallStaticObjectMethod(mdClass, getInstanceMethod, env->NewStringUTF("MD5"));

    // Convert the input string to bytes and update the digest.
    jmethodID updateMethod = env->GetMethodID(mdClass, "update", "([B)V");
    const char *inputStr = env->GetStringUTFChars(input, nullptr);
    size_t len = strlen(inputStr);
    jbyteArray inputBytes = env->NewByteArray(len);
    env->SetByteArrayRegion(inputBytes, 0, len, reinterpret_cast<const jbyte *>(inputStr));
    env->CallVoidMethod(mdObj, updateMethod, inputBytes);

    // Complete the digest computation.
    const char *digestChars = env->GetStringUTFChars(reinterpret_cast<jstring>(env->CallObjectMethod(mdObj, getInstanceMethod, env->NewStringUTF("MD5"))), nullptr);

    // Convert the resulting byte array into a hexadecimal string.
    char digestStr[(strlen(digestChars) * 2) + 1];
    for (int i = 0; i < strlen(digestChars); ++i) {
        sprintf(&digestStr[i*2], "%02x", (unsigned char) digestChars[i]);
    }

    // Release the resources and return the hexadecimal string.
    env->ReleaseStringUTFChars(input, inputStr);
    env->DeleteLocalRef(mdObj);
    env->DeleteLocalRef(inputBytes);

    return env->NewStringUTF(digestStr);
}
}
```

This code should be compiled into a shared library and called from C++ using the JNI functions. This is just a simple example, you would need to handle exceptions and errors properly in a production scenario.
