#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define structure for task
typedef struct {
    int timestamp;
    int priority;
    char* description;
} Task;

// Define hash table node structure
typedef struct Node {
    Task *task;
    struct Node *next;
} Node;

#define HASH_TABLE_SIZE 2069 // Prime number for better distribution
Node* hashTable[HASH_TABLE_SIZE];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Hash function to map priority to index in the hash table array
unsigned int hash(int key) {
    return key % HASH_TABLE_SIZE;
}

void addToHashTable(Task* task) {
    unsigned int index = hash(task->priority);

    pthread_mutex_lock(&lock); // Lock to ensure atomic operation 
    Node *newNode = malloc(sizeof(Node));
    newNode->task = task;
    newNode->next = hashTable[index];
    hashTable[index] = newNode;
    pthread_mutex_unlock(&lock); // Unlock after operation 
}

// Generate random task with description set to common English word
Task* generateRandomTask() {
    static char *descriptions[] = {"apple", "banana", "cherry", "date", "elderberry"};
    int numDescriptions = 5;

    Task *task = malloc(sizeof(Task));
    task->timestamp = rand();
    task->priority = rand() % 10 + 1; // Priority between 1 and 10
    task->description = descriptions[rand() % numDescriptions];

    return task;
}

// Generate tasks, add to hash table in a loop
void generateAndAddTasks(int numTasks) {
    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < numTasks; ++i) {
        Task *task = generateRandomTask();
        addToHashTable(task);
    }
}
