#define TABLE_SIZE 10007 // prime number for better hash distribution
task *hashTable[TABLE_SIZE];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

unsigned long hash(int priority) {
    unsigned long hash = 5381;
    int c;

    while ((c = priority++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % TABLE_SIZE;
}

task* getTask(int priority) {
    unsigned long index = hash(priority);
    pthread_mutex_lock(&lock);
    task* currentTask = hashTable[index];
    while (currentTask != NULL) {
        if (currentTask->priority == priority) {
            pthread_mutex_unlock(&lock);
            return currentTask;
        }
        currentTask = currentTask->next;
    }
    pthread_mutex_unlock(&lock);
    return NULL; // task not found
}

void addTask(task* newTask) {
    unsigned long index = hash(newTask->priority);
    pthread_mutex_lock(&lock);
    if (hashTable[index] == NULL) { 
        hashTable[index] = newTask;
    } else { // handle collision by adding to the list
        task* currentTask = hashTable[index];
        while(currentTask->next != NULL){
            currentTask = currentTask->next;
        }
        currentTask->next = newTask;
    }
    pthread_mutex_unlock(&lock);
}
```
