['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#define MAX_SIZE 1000
#define MAX_STRING 20

typedef struct record {
    int value;
    char string[MAX_STRING];
} Record;

int hash(int key) {
    return key % MAX_SIZE;
}

void allocateAndInitializeArrays(long *offsets, int *keys, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % MAX_SIZE;
        keys[i] = rand() % MAX_SIZE;
    }
}

void initializeRecords(Record *records, int *keys, int numKeys) {
    srand(time(NULL));
    int uniqueValues[MAX_SIZE] = {0};
    for (int i = 0, j = 0; i < numKeys && j < MAX_SIZE;) {
        if (uniqueValues[keys[i]] == 0) {
            records[j].value = keys[i];
            sprintf(records[j].string, "String %d", keys[i]);
            uniqueValues[keys[i]] = 1;
            j++;
        }
        i++;
    }
}

void quicksort(Record *arr, int low, int high) {
    if (low < high) {
        int pivot = arr[high].value;
        int i = (low - 1);

        for (int j = low; j <= high-1; j++) {
            if (arr[j].value < pivot) {
                i++;
                Record temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }
        Record temp = arr[i+1];
        arr[i+1] = arr[high];
        arr[high] = temp;

        int pi = i+1;

        quicksort(arr, low, pi-1);
        quicksort(arr, pi+1, high);
    }
}

void manageRecords(int size) {
    long offsets[MAX_SIZE];
    int keys[MAX_SIZE];

    allocateAndInitializeArrays(offsets, keys, size);

    // Assuming hash function is perfect and uniqueKeys <= MAX_SIZE 
    Record records[MAX_SIZE];
    initializeRecords(records, keys, size);

    quicksort(records, 0, size-1);
}
```
This code initializes two arrays of size `size` with random values. It then allocates memory for an array of records and populates it with unique key values from the `keys` array. Afterwards, the records are sorted using a quicksort algorithm based on their integer value. Please note that handling edge cases and concurrency issues is not covered in this code snippet as it would significantly increase complexity.
