    List* list = (List*)malloc(sizeof(List));
    list->resources = malloc(initialCapacity * sizeof(ResourceUsage*));
    list->capacity = initialCapacity;
    list->size = 0;
    return list;
}

// Function to add resource usage records while checking for potential reallocation due to overflow
void addRecord(List* list, ResourceUsage* record) {
    if (list->size == list->capacity) {
        // Reallocate when size equals capacity
        list->capacity *= 2;
        list->resources = realloc(list->resources, list->capacity * sizeof(ResourceUsage*));
    }
    list->resources[list->size++] = record;
}

// Function to iterate over the list and update specific resource metrics
void updateMetric(List* list, int index, ResourceMetric* newMetrics) {
    if (index < list->size && list->resources[index]->associatedMetrics != NULL) {
        free(list->resources[index]->associatedMetrics);  // Free previous metrics
        list->resources[index]->associatedMetrics = newMetrics;  // Update metrics
    } else {
        exit(-1);  // Error handling could be more elaborate in a real scenario
    }
}

// Function to manage record removal when a resource is decommissioned
void removeRecord(List* list, int index) {
    if (index < list->size) {
        free(list->resources[index]->associatedMetrics);  // Free metrics associated with the record
        free(list->resources[index]);  // Free record itself
        for (int i = index; i < list->size - 1; ++i) {
            list->resources[i] = list->resources[i + 1];  // Shift remaining elements to fill the gap
        }
        --list->size;
    } else {
