```c
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

// Assuming you have a logging mechanism available in your environment 
extern void log_message(const char* message); 

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // ... (your structure definition here)
} NFAPI_CRC_INDICATION_PDU_T;

void* generateArray(size_t n, size_t length) {
    NFAPI_CRC_INDICATION_PDU_T* arr = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize thread-local random number generator 
    static pthread_once_t once = PTHREAD_ONCE_INIT;
    static pthread_key_t key;
    pthread_once(&once, [] { pthread_key_create(&key, free); }); // Free memory when thread is done

    char* (*getRandomString)(size_t) = pthread_getspecific(key);
    if (getRandomString == NULL) {
        srand((unsigned int)pthread_self()); // Initialize local random generator with thread ID for better uniqueness

        getRandomString = [](size_t length) -> char* {
            static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
            char* randomString = NULL;

            if (length) {
                randomString = malloc(length + 1);

                if (randomString) {
                    for (size_t n = 0; n < length; ++n) {
                        size_t key = rand() % (int)(sizeof charset - 1);
                        randomString[n] = charset[key];
                    }

                    randomString[length] = '\0';
                } else {
                    log_message("Failed to allocate memory for random string.");
                }
            }

            return randomString;
        };

        pthread_setspecific(key, getRandomString);
    }

    // Generate array 
    for (size_t i = 0; i < n; ++i) {
        char* randomString = getRandomString(length);

        if (!randomString) {
            log_message("Failed to generate random string. Aborting.");

            // Free previously allocated memory 
            for (size_t j = 0; j < i; ++j) {
                free(arr[j].RX_UE_INFORMATION_TAG);
            }

            free(arr);
            return NULL;
        }

        arr[i].RX_UE_INFORMATION_TAG = randomString;
    }

    log_message("Array generated successfully.");
    return arr;
}
```
This code generates an array of NFAPI_CRC_INDICATION_PDU_T structures, each containing a randomly-generated string in the `RX_UE_INFORMATION_TAG` field. It uses thread-local storage to ensure that multiple threads do not interfere with each other's random number generation. If memory allocation or random string generation fails for any reason, it logs an error message and frees all previously allocated memory before returning NULL.
