        records[i].value = rand() % 10000; // random value within a specified range.
    }

    size_t filenameLen = strlen(filename);
    char* newFilename = malloc((maxDigits + 2 + filenameLen) * sizeof(*newFilename));

    sprintf(newFilename, "%.*s", (int)filenameLen, filename); // copy the original filename.
    for (size_t i = 0; i < maxDigits - 1; ++i) {
        strcat(newFilename, "_");
