#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* buffer;
    size_t length;
} dataItem;

// The collection and its mutex lock
dataItem *collection = NULL;
size_t collectionSize = 0;
size_t maxCollectionSize = 1024; // Adjust this as per requirement
pthread_mutex_t lock;

void initializeDataItem(dataItem* item, const char* string) {
    size_t length = strlen(string);

    if (item->buffer == NULL || item->length < length) {
        // Allocate or reallocate buffer
        free(item->buffer);
        item->buffer = malloc(length + 1);

        if (item->buffer == NULL) {
            perror("Failed to allocate memory for dataItem");
            exit(EXIT_FAILURE);
        }
    }

    // Copy the string and adjust length
    strcpy(item->buffer, string);
    item->length = length;
}

void* addDataItem(const char* string) {
    pthread_mutex_lock(&lock);

    if (collectionSize >= maxCollectionSize) {
        // Collection is full, handle as per requirement
        printf("Collection is full. Cannot add more items.\n");

        pthread_mutex_unlock(&lock);
        return NULL;
    }

    dataItem* item = &collection[collectionSize++];
    initializeDataItem(item, string);

    pthread_mutex_unlock(&lock);

    return item;
}

dataItem* getDataItem(size_t index) {
    pthread_mutex_lock(&lock);

    if (index >= collectionSize) {
        // Index out of bounds, handle as per requirement
        printf("Index is out of bounds.\n");

        pthread_mutex_unlock(&lock);
        return NULL;
    }

    dataItem* item = &collection[index];

    pthread_mutex_unlock(&lock);

    return item;
}
```
Note: This is a simplification and doesn't include any form of concurrency management or resizing strategy. For real-world applications, one would want to have more comprehensive error handling, possibly using thread pools for efficient execution, and using various strategies for memory allocation and resizing based on requirements and constraints. Also, it assumes the user has knowledge in C programming language.
