    int newID;
    do {
        newID = rand();
        for (size_t i = 0; i < connectionStatesSize; ++i) {
            if (connectionStates[i].connectionID == newID) {
                newID = -1;  // signal that the ID isn't unique yet
                break;
            }
        }
    } while(newID == -1);

    return newID;
}

ConnectionState *addConnection() {
    connectionStatesSize++;
    connectionStates = realloc(connectionStates, connectionStatesSize * sizeof(ConnectionState));
    ConnectionState *connection = &connectionStates[connectionStatesSize-1];  // get pointer to newly added connection

    connection->connectionID = getUniqueID();
    connection->lastActivityTimestamp = 0;
    strcpy(connection->currentState, "idle");
    connection->eventList = NULL;
    connection->eventCount = 0;

    return connection;
}

Event *addEventToConnection(ConnectionState *connection, const char *type) {
    Event newEvent;
    strcpy(newEvent.type, type);
    time(&newEvent.timestamp);

    size_t eventCount = ++connection->eventCount;
    connection->eventList = realloc(connection->eventList, eventCount * sizeof(Event));
    connection->eventList[eventCount-1] = newEvent;

    return &connection->eventList[eventCount-1];
}

void updateConnectionState(int connectionID, const char *newState) {
    for (size_t i = 0; i < connectionStatesSize; ++i) {
        if (connectionStates[i].connectionID == connectionID) {
            strcpy(connectionStates[i].currentState, newState);

            time(&connectionStates[i].lastActivityTimestamp);  // update last activity timestamp

            if(strcmp("connected", newState) == 0){
                mostRecentActiveIndex = i;
            }
        }
    }
}

void removeConnection(int connectionID) {
    for (size_t i = 0; i < connectionStatesSize; ++i) {
        if (connectionStates[i].connectionID == connectionID) {
            free(connectionStates[i].eventList);  // free event list associated with the removed connection

            // Shift all connections after the removed one forward to fill in the gap, and reduce size of array
            for (size_t j = i; j < connectionStatesSize - 1; ++j) {
                connectionStates[j] = connectionStates[j+1];
            }

            connectionStatesSize--;
            break;
        }
    }

    // If most recent active index is removed, then update the index to next available one.
    if(mostRecentActiveIndex >= connectionStatesSize) {
        for (size_t i = 0; i < connectionStatesSize; ++i) {
            if(strcmp("connected", connectionStates[i].currentState) == 0){
                mostRecentActiveIndex = i;
