#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
} record;

record* init_records(long batchSize, int rangeMin, int rangeMax) {
    if (rangeMax - rangeMin + 1 < batchSize || batchSize == 0) {
        return NULL;  // Not enough unique numbers in the specified range or zero records.
    }

    record *records = malloc(sizeof(record)*batchSize);
    int *keys = calloc(batchSize, sizeof(int));
    long *offsets = malloc(sizeof(long)*batchSize);
    if (records == NULL || keys == NULL || offsets == NULL) {
        // Handle memory allocation failure.
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    srand((unsigned int) time(NULL));  // Seed the random number generator.

    for (int i = 0; i < batchSize; i++) {
        int value;
        do {
            value = rand() % (rangeMax - rangeMin + 1) + rangeMin;
        } while (keys[value-rangeMin] != 0);

        keys[value-rangeMin] = 1;  // Mark the used number.

        records[i].value = value;
        records[i].offset = &offsets[i];
    }

    free(keys);  // No longer needed, as we've stored offsets in `records`.

    return records;
}
```
