Record *create_records(long size, char *buffer) {
    srand(time(NULL));

    if (size == 0 || INT_MAX < size*3) {
        fprintf(stderr, "Invalid input size\n");
        return NULL;
    }

    long *offsets = calloc(size, sizeof(*offsets));
    if (!offsets) {
        perror("calloc offsets failed");
        return NULL;
    }

    int key_size = (size + 2) / 3; // Integer division with rounding up
    int *keys = calloc(key_size, sizeof(*keys));
    if (!keys) {
        perror("calloc keys failed");
        free(offsets);
        return NULL;
    }

    Record *records = malloc(sizeof(*records)*key_size);
    if (!records) {
        perror("malloc records failed");
        free(keys);
        free(offsets);
        return NULL;
    }

    int unique_counter = 0; // Used to keep track of how many unique values we've created
    while (unique_counter < key_size) {
        int random_value = rand() % INT_MAX; // Generate a random value within the range
        int i;
        for (i = 0; i < unique_counter; ++i) {
            if (keys[i] == random_value) break; // Check for uniqueness
        }
        if (i == unique_counter) keys[unique_counter++] = random_value; // If value is unique, store it
    }

    // Initialize records
    for (int i = 0; i < key_size; ++i) {
        records[i].value = keys[i];
        records[i].offsets = offsets;
    }

    free(keys); // No longer needed after initializing the records

    return records;
}
``` 
