import java.util.concurrent.*;

public class DynamicCache {
    private final ConcurrentHashMap<String, Item> cache;
    private final ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
    private final int maxSize;

    public DynamicCache(int initialCapacity, int maxSize) {
        this.cache = new ConcurrentHashMap<>(initialCapacity);
        this.maxSize = maxSize;
    }

    public void put(String key, Item value) {
        if (key == null || value == null) throw new IllegalArgumentException();

        synchronized (this) {
            while (cache.size() >= maxSize) {
                evictLeastRecentlyUsedItem();
            }
            cache.put(key, value);
        }
    }

    public Item get(String key) {
        return cache.get(key);
    }

    private void evictLeastRecentlyUsedItem() {
        // Implement your own LRU logic here
    }

    public int size() {
        return cache.size();
    }

    public void scheduleExternalUpdate(Runnable task, long delay, TimeUnit unit) {
        scheduler.scheduleWithFixedDelay(task, 0, delay, unit);
    }
}
