import os
import json
import logging
import subprocess
from cryptography.fernet import Fernet

class KickstartError(Exception):
    pass

def read_json_config(filepath):
    try:
        with open(filepath, 'r') as f:
            return json.load(f)
    except Exception as e:
        logging.error("Failed to load JSON file: %s", str(e))
        raise KickstartError('Failed to load JSON file') from e

def validate_config(filepath, params):
    config = read_json_config(filepath)

    for param in params.keys():
        if param not in config:
            logging.error("Invalid key: %s", param)
            raise KickstartError('Invalid key')

def replace_placeholders(filepath, params):
    validate_config(filepath, params)

    for key, value in params.items():
        try:
            command = f"sed -i 's/{key}/{value}/g' {filepath}"
            subprocess.run(['/bin/bash', '-c', command], capture_output=True, check=True)
        except Exception as e:
            logging.error("Sed command failed with error: %s", str(e))
            raise KickstartError('Failed to execute sed command') from e

def encrypt_password(key, password):
    try:
        cipher = Fernet(key)
        return cipher.encrypt(password.encode())
    except Exception as e:
        logging.error("Encryption failed with error: %s", str(e))
        raise KickstartError('Failed to encrypt password') from e

def add_line_with_password(filepath, key, password):
    encrypted_pass = encrypt_password(key, password)

    try:
        with open(filepath, 'a') as f:
            f.write(f"\nencrypted_password={encrypted_pass}")
    except Exception as e:
        logging.error("Failed to add line with encrypted password: %s", str(e))
        raise KickstartError('Failed to add line with encrypted password') from e
