["The following code block is a simplified implementation of a hash table data structure in C that meets the specified requirements. It uses separate chaining for collision resolution to improve cache locality (as elements stored at the same index are close together in memory) and minimizes memory fragmentation. 

In this example, we use fixed increment resizing strategy which is simple but may lead to memory waste when load factor decreases. For adaptive resizing, additional logic could be added to resize the hash table based on load factor automatically. This implementation uses a linked list for chaining and employs prime numbers for better distribution.

Please note that this is a basic demonstration and doesn't include logging mechanisms or error handling, which would typically involve use of an external library or framework. 

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Record {
    int key;
    int value;
    struct Record* next;
} Record;

Record** table;
int size = 1009; // Prime number for less collision and better distribution
int count = 0;
float load_factor = 0.75; 

void initTable() {
    table = (Record**)malloc(sizeof(Record*) * size);
}

unsigned int hashFunction(int key){
    return abs((key % size));
}

void insert(int key, int value) {
    if ((float)(count / size) > load_factor) resize();  // Resize when load factor exceeds threshold

    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->value = value;
    unsigned int index = hashFunction(key);

    if (table[index] == NULL) {
        table[index] = record;  // No collision, insert directly
    } else {
        Record* temp = table[index];
        while (temp->next != NULL && temp->key != key) {  
            if (temp->key == key) break; // Duplicate key found, ignore insertion
            temp = temp->next; 
        }
        if(temp->key != key){
            record->next = table[index]; // Insert at head of list for O(1) insertion
            table[index] = record;
        }
    }
    count++; 
}

int get(int key) {
    unsigned int index = hashFunction(key);
    Record* temp = table[index];
    while (temp != NULL && temp->key != key) temp = temp->next;   // Search in list for key
    return temp == NULL ? -1 : temp->value;  // Return -1 if not found
}

void resize() {
    int oldSize = size;
    Record** oldTable = table;
    size *= 2;
    count = 0;

    initTable();

    for (int i = 0; i < oldSize; i++) {   // Rehash all elements to new table
        Record* temp = oldTable[i];
        while(temp != NULL){ 
            insert(temp->key, temp->value);
            Record* del = temp;
            temp = temp->next;
            free(del);   // Free memory of old table
        }
    }
    free(oldTable);
}
```
Please handle the cases for unsuccessful memory allocations and errors as per your application requirements. This is a basic example and doesn't include such functionality. Use appropriate logging mechanisms or error handling mechanisms in your actual code. For instance, if `malloc` fails to allocate memory, it returns NULL. You should check for this and handle accordingly.
"]

