['Here is a basic implementation in C language using pthread library for thread safety. The function will return 0 if successful, otherwise an error code.

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_NODES 1000 // predefined constant

typedef struct node {
    double value;
    struct node* next;
} Node;

typedef struct {
    pthread_mutex_t lock;
    Node *head, *tail;
} LinkedList;

double computeAverage(Node* head) {
    double sum = 0.0;
    int count = 0;
    for (Node* current = head; current != NULL; current = current->next) {
        sum += current->value;
        count++;
    }

    return count == 0 ? 0 : sum / count;
}

void initLinkedList(LinkedList *list){
    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
}

int fillLinkedList(double limit, int userInput) {
    // calculate the maximum number of nodes we can have
    int maxNodes = (long long)(0.05 * 1024 * 1024 * 1024 / sizeof(Node));
    if(maxNodes > MAX_NODES){
        maxNodes = MAX_NODES;
    }

    // allocate memory for an array of userInput length and check for insufficient memory conditions
    int sizeOfArray = (long long)(0.1 * 1024 * 1024 * 1024 / sizeof(double));
    if(sizeOfArray < userInput){
        return -1; // error: insufficient available memory to allocate data_array
    }

    double* data_array = (double*)malloc(userInput * sizeof(double));
    if(data_array == NULL) {
        return -2; // error: memory allocation failed
    }

    srand((unsigned int) time(NULL));

    LinkedList list;
    initLinkedList(&list);

    double sum = 0.0;
    for (int i = 0; i < userInput; ++i){
        double randomValue = ((double) rand() / RAND_MAX) * limit; // generate a random floating-point value within the specified range

        int j;
        Node* currentNode;
        pthread_mutex_lock(&list.lock); // lock for concurrent write operations
        for (j = 0, currentNode = list.head; 
             j < i && currentNode->value != randomValue; 
             ++j, currentNode = currentNode->next) {}

        if(j == i){ // no duplicate values in the linked list
            Node* newNode = (Node*) malloc(sizeof(Node));
            if(newNode == NULL) {
                return -2; // error: memory allocation failed for a node
            }

            newNode->value = randomValue;
            newNode->next = NULL;

            data_array[i] = randomValue;
            sum += randomValue;

            if(list.head == NULL) { // first element in the list
                list.head = list.tail = newNode;
            } else {
                list.tail->next = newNode;
                list.tail = newNode;
            }
        }else{ // duplicate value found, discard and regenerate
            --i;
        }

        pthread_mutex_unlock(&list.lock); // unlock after the write operation
    }

    printf("The average of all nodes in the linked list is %f.\n", computeAverage(list.head));
    return 0;
}
```
This program will create a thread-safe linked list and fill it with unique random values from the specified range. It also computes the average value of all nodes in the linked list. The function handles insufficient memory conditions, iterates over the linked list, and calculates the average efficiently using a single pass through the data.
']

