```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct PacketHeader {
    int version;
    int seqNum;
    time_t timestamp;
    size_t payloadLen;
    unsigned int ttl;
} PacketHeader;

struct MemoryPool {
    pthread_mutex_t lock;
    PacketHeader* headers;
};

void initMemoryPool(struct MemoryPool *pool, unsigned int num) {
    pool->headers = (PacketHeader*)malloc(sizeof(PacketHeader) * num);
    if (pthread_mutex_init(&pool->lock, NULL) != 0) {
        free(pool->headers);
        // handle initialization error
        exit(1);
    }
}

unsigned int allocateHeaders(struct MemoryPool *pool, unsigned int num) {
    if (pthread_mutex_lock(&pool->lock) != 0) {
        return 0;
    }

    unsigned int allocated = 0;
    for (; allocated < num; ++allocated) {
        PacketHeader *header = &pool->headers[allocated];

        // Initialize each field with default values on memory allocation failure
        if (!header) {
            break;
        } else {
            header->version = 1;
            header->seqNum = rand();
            time(&header->timestamp);
            header->payloadLen = 0;
            header->ttl = 3600; // 1 hour TTL
        }
    }

    if (pthread_mutex_unlock(&pool->lock) != 0) {
        return 0;
    }

    return allocated;
}

void freeMemoryPool(struct MemoryPool *pool, unsigned int num) {
    for (unsigned int i = 0; i < num; ++i) {
        PacketHeader* header = &pool->headers[i];

        // Free memory if it is allocated
        if (header && header->ttl <= 0) {
            free(header);
        }
    }
}
```
This code does not handle TTL-based memory reclamation and logging, which would require additional complexity.

