#include <pthread.h>
#define INIT_SIZE 1024
typedef struct PacketHeader {
    int protocolVersion;
    int sequenceNumber;
    time_t timestamp;
    size_t payloadLength;
} PacketHeader;

typedef struct PacketArray {
    PacketHeader* headers;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock; // for thread-safety
} PacketArray;

PacketArray packetArray;
void initPacketArray() {
    packetArray.headers = malloc(sizeof(PacketHeader) * INIT_SIZE);
    packetArray.count = 0;
    packetArray.capacity = INIT_SIZE;
    pthread_mutex_init(&packetArray.lock, NULL); // initialize mutex
}

void addPacket(int protocolVersion, int sequenceNumber, time_t timestamp, size_t payloadLength) {
    pthread_mutex_lock(&packetArray.lock);  // lock for thread-safety

    if (packetArray.count == packetArray.capacity) {
        // reallocate memory
        packetArray.headers = realloc(packetArray.headers, sizeof(PacketHeader) * packetArray.capacity * 2);

        if (packetArray.headers == NULL) {
            fprintf(stderr, "Failed to allocate memory for PacketHeaders\n");
            exit(-1);
        }

        packetArray.capacity *= 2;
    }

    // add a new packet
    packetArray.headers[packetArray.count].protocolVersion = protocolVersion;
    packetArray.headers[packetArray.count].sequenceNumber = sequenceNumber;
    packetArray.headers[packetArray.count].timestamp = timestamp;
    packetArray.headers[packetArray.count].payloadLength = payloadLength;
    ++packetArray.count;

    pthread_mutex_unlock(&packetArray.lock);  // unlock after operation
}
```
