#include <stdio.h>
#include <stdlib.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct RX_UE_INFORMATION_TAG_T {
    long offsets[10];
    int keys[20];
    float values[30];
    struct element { double value;} *elements;
} container_t;

container_t **allocate_memory(int N, long offsets[], int keys[], float values[], size_t max_capacity) {

    if (N <= 0 || offsets == NULL || keys == NULL || values == NULL) return NULL;

    container_t **containers = calloc(N, sizeof(container_t*));
    if (containers == NULL) return NULL;

    for (int i = 0; i < N; ++i) {
        containers[i] = malloc(sizeof(container_t));

        if (containers[i] == NULL){
            // clean up previously allocated memory
            for (--i; i >= 0; --i){
                free(containers[i]);
            } 
            free(containers);
            return NULL;
        }
        containers[i]->elements = malloc(sizeof(struct element) * max_capacity);

        if (containers[i]->elements == NULL){
             // clean up previously allocated memory
            for (; i >= 0; --i){
                free(containers[i]);
            } 
            free(containers);
            return NULL;
        }

        memcpy(containers[i]->offsets, offsets, sizeof(long) * 10);
        memcpy(containers[i]->keys, keys, sizeof(int) * 20);
        memcpy(containers[i]->values, values, sizeof(float) * 30);
    }

    return containers;
