}

void manageMemory(double** arrDouble, char*** arrChar, item** arrItem, size_t n) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;  // Mutex for thread safety.

    pthread_mutex_lock(&mutex);  // Lock the mutex to protect shared data structures.

    srand(time(NULL));  // Seed random number generator.

    *arrDouble = malloc(n * sizeof(double));
    if (*arrDouble == NULL) {
        perror("Error allocating memory for double array");
        exit(-1);
    }

    *arrChar = malloc(n * sizeof(char*));
    if (*arrChar == NULL) {
        perror("Error allocating memory for char pointer array");
        free(*arrDouble);  // Free previously allocated memory.
        exit(-1);
    }

    *arrItem = malloc(n * sizeof(item));
    if (*arrItem == NULL) {
        perror("Error allocating memory for item array");
        free(*arrChar);  // Free previously allocated memory.
        free(*arrDouble);
        exit(-1);
    }

    const char* sampleString = "SampleString";  // Used to populate the arrays.

    for (size_t i = 0; i < n; ++i) {
        (*arrDouble)[i] = (double)rand() / RAND_MAX;  // Random value between [0.0,1.0]

        populateItem(&((*arrItem)[i]), sampleString);  // Populates a single item struct with random values.
    }

    pthread_mutex_unlock(&mutex);  // Unlock the mutex to allow other threads to access the data structures.
}
