['```C
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

typedef struct {
    int log_level;
    time_t timestamp;
    char source[32];
    char message[1024];
    void* metadata;
} LogEntry;

typedef struct {
    pthread_mutex_t lock;
    LogEntry** entries;
    int size;
    int capacity;
    void (*onChange)(void);  // notify consumers of changes in the log entry data
} LogManager;

LogManager* initialize(int M, void (*onChange)(void)) {
    LogManager* manager = (LogManager*)malloc(sizeof(LogManager));
    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = M;
    manager->size = 0;
    manager->entries = (LogEntry**)calloc(M, sizeof(LogEntry*));
    manager->onChange = onChange;
    return manager;
}

void add_entry(LogManager* manager, LogEntry* entry) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        manager->entries = realloc(manager->entries, manager->capacity * 2 * sizeof(LogEntry*));
        manager->capacity *= 2;
    }

    LogEntry* new_entry = (LogEntry*)malloc(sizeof(LogEntry));
    memcpy(new_entry, entry, sizeof(LogEntry));
    manager->entries[manager->size++] = new_entry;

    pthread_mutex_unlock(&manager->lock);

    if (manager->onChange) {
        manager->onChange();
    }
}

void remove_entry(LogManager* manager, int index) {
    pthread_mutex_lock(&manager->lock);

    if (index >= 0 && index < manager->size) {
        free(manager->entries[index]);

        for (int i = index; i < manager->size - 1; ++i) {
            manager->entries[i] = manager->entries[i + 1];
        }

        --manager->size;
    }

    pthread_mutex_unlock(&manager->lock);

    if (manager->onChange) {
        manager->onChange();
    }
}

void update_entry(LogManager* manager, int index, LogEntry* entry) {
    pthread_mutex_lock(&manager->lock);

    if (index >= 0 && index < manager->size) {
        free(manager->entries[index]);
        manager->entries[index] = (LogEntry*)malloc(sizeof(LogEntry));
        memcpy(manager->entries[index], entry, sizeof(LogEntry));
    }

    pthread_mutex_unlock(&manager->lock);

    if (manager->onChange) {
        manager->onChange();
    }
}

void iterate(LogManager* manager, void (*visit)(int index, LogEntry* entry)) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->size; ++i) {
        visit(i, manager->entries[i]);
    }

    pthread_mutex_unlock(&manager->lock);
}

void cleanup(LogManager* manager) {
    for (int i = 0; i < manager->size; ++i) {
        free(manager->entries[i]);
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager->entries);
}
```
This code provides the functionality you requested, including efficient memory management to handle potential reallocations due to overflow. The function uses a mutex lock for synchronization to ensure thread safety without significant performance overhead. It also allows external components to integrate with your logging module using functions for adding, removing, and modifying log entries, as well as subscribing to change notifications via the `onChange` callback.
']

