    if (p.name == NULL) {
        return;  // handle memory allocation failure
    }

    // add or update the product in our unordered map
    products[id] = p;
}

Product* getProduct(int id) {
    ProductMap::iterator it = products.find(id);

    if (it != products.end()) {
        return &(it->second);  // product found, return pointer to it
    } else {
        return NULL;  // product not found
    }
}

void removeProduct(int id) {
    ProductMap::iterator it = products.find(id);

    if (it != products.end()) {
        free((void*) it->second.name);  // deallocate memory for name
        products.erase(it);  // remove the product from map
    }
}
