```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int value;
} Record;

typedef struct CacheEntry {
    Record *record;
    struct CacheEntry *prev, *next;
} CacheEntry;

static pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;
CacheEntry* head = NULL;
CacheEntry* tail = NULL;
int cacheHits = 0, numOfMisses = 0;

long offset[10000];
int key[10000], uniqueKeysCount = 0;
Record *records[10000] = {NULL}; // Assume keys are within the range 0-9999.
CacheEntry* cache[10000] = {NULL}; // Array of pointers to cache entries.

int hashFunction(int key) {
    return abs(key % uniqueKeysCount); // Use a simple hashing function for simplicity.
}

void addToCache(Record *record, int index) {
    CacheEntry* new_entry = malloc(sizeof(CacheEntry));
    if (new_entry == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }
    // Add the record at the end of the LRU list.
    new_entry->record = record;
    if (head == NULL) {
        head = tail = new_entry;
        new_entry->prev = new_entry->next = NULL;
    } else {
        tail->next = new_entry;
        new_entry->prev = tail;
        new_entry->next = NULL;
        tail = new_entry;
    }
    cache[index] = new_entry; // Update the entry in our cache.
}

void updateCache(int index) {
    CacheEntry* entry = cache[index];
    if (entry != NULL && entry != tail) { 
        // If it's not already at the end of the list, move it to the end.
        if (entry->prev != NULL)
            entry->prev->next = entry->next;
        else
            head = entry->next; // It was at the beginning.
        tail->next = entry;
        entry->prev = tail;
        entry->next = NULL;
        tail = entry;
    } 
}

Record* findInCache(int key) {
    int index = hashFunction(key);
    pthread_mutex_lock(&cacheMutex); // Lock to ensure thread safety.
    if (cache[index] != NULL && cache[index]->record->value == key) {
        cacheHits++;
        updateCache(index); 
        Record* record = cache[index]->record;
        pthread_mutex_unlock(&cacheMutex);
        return record; // Return the cached value.
    } else {
        numOfMisses++;
        pthread_mutex_unlock(&cacheMutex);
        return NULL; // Record not found in cache, so we need to search in records array.
    }
}

Record* findInRecords(int key) {
    int index = hashFunction(key);
    if (records[index] != NULL && records[index]->value == key) 
        return records[index]; // Return the record if found.
    else 
        return NULL; // Record not found.
}
```

To implement this in a larger system you would need to adapt and integrate it into your system's design considerations, thread management and error handling practices. Additionally, the hash function used here is quite simplistic and may result in collisions (two different keys hashing to same value). Consider using a proper hashing algorithm for real-world usage.
