typedef struct {
    PacketHeader *headers;
    size_t capacity;
    size_t count;
} DynamicPacketArray;

DynamicPacketArray* create_packet_array(size_t capacity) {
    DynamicPacketArray *arr = malloc(sizeof(*arr));
    arr->headers = malloc(capacity * sizeof(*arr->headers));
    arr->capacity = capacity;
    arr->count = 0;
    return arr;
}

void resize_packet_array(DynamicPacketArray* arr, size_t new_size) {
    PacketHeader *new_data = realloc(arr->headers, new_size * sizeof(*arr->headers));
    if (new_data == NULL && new_size != 0) return; // out of memory
    arr->headers = new_data;
    arr->capacity = new_size;
}

int add_packet(DynamicPacketArray* arr, PacketHeader header) {
    if (arr->count >= arr->capacity) {
        resize_packet_array(arr, arr->capacity * 2); // double the size when overflowing
    }
    arr->headers[arr->count] = header;
    ++arr->count;
}

void update_header(DynamicPacketArray* arr, int index, PacketHeader new_header) {
    if (index >= arr->count || index < 0) return; // out of bounds error checking
    arr->headers[index] = new_header;
}

void free_packet_array(DynamicPacketArray* arr) {
    free(arr->headers);
    free(arr);
}
