int getRandomInt(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Check if an array contains a value.
bool containsValue(int* arr, int size, int val) {
    for (int i = 0; i < size; i++) {
        if (arr[i] == val) return true;
    }
    return false;
}

// Generate a unique random value within the specified range.
int generateUniqueRandom(int* arr, int size, int min, int max) {
    int val;
    do {
        val = getRandomInt(min, max);
    } while (containsValue(arr, size, val));
    return val;
}

// Sort the records array in ascending order.
void sortRecords() {
    qsort(records, recordCount, sizeof(Record*), compareRecords);
}

int compareRecords(const void* a, const void* b) {
    return ((Record*)a)->value - ((Record*)b)->value;
}

