['```c
#include <stdlib.h>
#include <pthread.h>
#include <assert.h>
#include <stdatomic.h>

#define MAX_ITEMS 1000
#define MAX_PAYLOAD_LEN 1500
#define INDICATIONS_PER_REALLOC 500
#define THREAD_SAFE

typedef struct {
    uint8_t protocolVersion;
    atomic_uint sequenceNumber;
    time_t timestamp;
    size_t payloadLength;
    bool CRCFLAG;
} PacketHeader;

typedef struct {
    PacketHeader* headers;
    size_t count;
    size_t capacity;
#ifdef THREAD_SAFE
    pthread_mutex_t lock;
#endif
} HeaderArray;

static void header_array_init(HeaderArray* arr) {
    assert(arr != NULL);

    arr->headers = malloc(MAX_ITEMS * sizeof(PacketHeader));
    assert(arr->headers != NULL);

    arr->count = 0;
    arr->capacity = MAX_ITEMS;
#ifdef THREAD_SAFE
    pthread_mutex_init(&arr->lock, NULL);
#endif
}

static void header_array_realloc(HeaderArray* arr) {
    assert(arr != NULL);

#ifdef THREAD_SAFE
    pthread_mutex_lock(&arr->lock);
#endif

    if (arr->count == arr->capacity) {
        size_t newCapacity = arr->capacity + INDICATIONS_PER_REALLOC;
        PacketHeader* newHeaders = realloc(arr->headers, newCapacity * sizeof(PacketHeader));

        if (newHeaders != NULL) {
            arr->headers = newHeaders;
            arr->capacity = newCapacity;
        } else {
            // Handle memory allocation failure.
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }

#ifdef THREAD_SAFE
    pthread_mutex_unlock(&arr->lock);
#endif
}

static void header_array_add(HeaderArray* arr, PacketHeader* hdr) {
    assert(arr != NULL && hdr != NULL);

    if (hdr->payloadLength > MAX_PAYLOAD_LEN) {
        // Handle payload length exceeding limit.
        return;
    }

    header_array_realloc(arr);

#ifdef THREAD_SAFE
    pthread_mutex_lock(&arr->lock);
#endif

    arr->headers[arr->count++] = *hdr;

#ifdef THREAD_SAFE
    pthread_mutex_unlock(&arr->lock);
#endif
}

