["Here is a basic implementation for the problem you described in C language using POSIX threads (pthread). Note that this code has been written to be readable rather than efficient, so it may not necessarily be suitable for large applications.

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value; 
} record_t;

typedef struct {
    long* offsets;
    int* keys;
    record_t** records;
    pthread_mutex_t mutex;
    size_t arraySize;
    unsigned maxValue;
    unsigned seed;
} config_t;

void initConfig(config_t *conf, size_t arraySize, unsigned maxValue, unsigned seed) {
    conf->arraySize = arraySize;
    conf->maxValue = maxValue;
    conf->seed = seed ? seed : time(NULL);

    srand(conf->seed);
    conf->offsets = malloc(sizeof(long) * arraySize);
    for (size_t i = 0; i < arraySize; ++i) {
        conf->offsets[i] = rand() % maxValue; 
    }

    conf->keys = malloc(sizeof(int) * arraySize);
    for (size_t i = 0; i < arraySize; ++i) {
        conf->keys[i] = rand() % maxValue;
    }

    conf->records = malloc(sizeof(record_t*) * arraySize);
    for (size_t i = 0; i < arraySize; ++i) {
        record_t* rec = malloc(sizeof(record_t)); 
        rec->value = rand() % maxValue;
        conf->records[i] = rec;
    }

    pthread_mutex_init(&conf->mutex, NULL);
}

void resetConfig(config_t *conf) {
    for (size_t i = 0; i < conf->arraySize; ++i) {
        free(conf->records[i]); 
    }
    free(conf->offsets);
    free(conf->keys);
    free(conf->records);

    pthread_mutex_destroy(&conf->mutex);
}

void* threadWorker(void *arg) { 
    config_t *conf = (config_t*) arg;
    while (1) {
        pthread_mutex_lock(&conf->mutex);

        // Do some work with the data...

        pthread_mutex_unlock(&conf->mutex);
    }

    return NULL; 
}
```
This code initializes a configuration structure that contains an array of long offsets, int keys and record structures. It also has a mutex to ensure safe concurrent access from multiple threads. The data for each structure is initialized randomly with srand() and rand(). The initConfig function takes care of allocating memory for the arrays and initializing their elements.

The resetConfig function frees up all allocated memory when it's called.

Each thread can lock the mutex before accessing the data, ensuring that no two threads access the shared resources simultaneously, thus preventing race conditions. After accessing the data each thread should unlock the mutex.
"]

['Below is a basic example of how you could implement this in C using pthread mutexes and conditional variables for synchronization:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char name[256];
    int age;
    char email[256];
} Profile;

typedef struct HashTableNode {
    Profile profile;
    pthread_mutex_t lock;
    struct HashTableNode* next;
} HashTableNode;

typedef struct HashTable {
    HashTableNode** buckets;
    size_t size;
    size_t capacity;
    double loadFactor;
    int concurrencyLevel;
    pthread_mutex_t globalLock;
    pthread_cond_t spaceAvailable;
} HashTable;

HashTable* createHashTable(size_t capacity, double loadFactor, int concurrencyLevel) {
    if (loadFactor <= 0.0 || loadFactor > 1.0) {
        fprintf(stderr, "Invalid Load Factor\n");
        return NULL;
    }
    HashTable* hashTable = malloc(sizeof(HashTable));
    if (!hashTable) {
        fprintf(stderr, "Memory Allocation Failed\n");
        return NULL;
    }
    hashTable->buckets = calloc(capacity, sizeof(HashTableNode*));
    if (!hashTable->buckets) {
        free(hashTable);
        fprintf(stderr, "Memory Allocation Failed\n");
        return NULL;
    }
    hashTable->size = 0;
    hashTable->capacity = capacity;
    hashTable->loadFactor = loadFactor;
    hashTable->concurrencyLevel = concurrencyLevel;
    pthread_mutex_init(&hashTable->globalLock, NULL);
    pthread_cond_init(&hashTable->spaceAvailable, NULL);
    return hashTable;
}

void destroyHashTable(HashTable* hashTable) {
    for (size_t i = 0; i < hashTable->capacity; ++i) {
        HashTableNode* node = hashTable->buckets[i];
        while (node != NULL) {
            HashTableNode* next = node->next;
            pthread_mutex_destroy(&node->lock);
            free(node);
            node = next;
        }
    }
    free(hashTable->buckets);
    pthread_cond_destroy(&hashTable->spaceAvailable);
    pthread_mutex_destroy(&hashTable->globalLock);
    free(hashTable);
}

size_t hash(char* key, size_t capacity) {
    size_t hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % capacity;
}

void insert(HashTable* hashTable, Profile profile) {
    size_t index = hash(profile.name, hashTable->capacity);
    HashTableNode* node = malloc(sizeof(HashTableNode));
    if (!node) {
        fprintf(stderr, "Memory Allocation Failed\n");
        return;
    }
    pthread_mutex_init(&node->lock, NULL);
    node->profile = profile;
    pthread_mutex_lock(&hashTable->globalLock);
    while (hashTable->size >= hashTable->capacity * hashTable->loadFactor) {
        pthread_cond_wait(&hashTable->spaceAvailable, &hashTable->globalLock);
    }
    ++hashTable->size;
    pthread_mutex_unlock(&hashTable->globalLock);
    node->next = hashTable->buckets[index];
    hashTable->buckets[index] = node;
}
```
This is a basic start and doesn't handle things like thread safety in individual operations, memory exhaustion and error handling. However it should give you a good starting point for creating your own implementation. This code also lacks the reset functionality and hashing function for simplicity purposes. Please note that this C code does not use any concurrency features from C++11 or higher to maintain compatibility with older compilers.
']

