        return systemLoad;
    }

    NetworkOperationStrategy* selectNetworkOperationStrategy() {
        std::lock_guard<std::mutex> lock(mutex_);

        auto systemLoad = getSystemLoad();
        if (systemLoad < 0.3) {  // Example thresholds, adjust as needed
            return strategies_[0].get();   // Indexes should match the order of strategies in vector
        } else if (systemLoad < 0.6) {
            return strategies_[1].get();
        }
        // ... and so on for other thresholds 
    }

    void performOperation() {
        static auto lastRunTime = std::chrono::system_clock::now();
        auto currentTime = std::chrono::system_clock::now();

        if (std::chrono::duration_cast<std::chrono::seconds>(currentTime - lastRunTime).count() >= 300) {
            selectNetworkOperationStrategy()->perform();
            lastRunTime = currentTime;
        }
    }
};
