        perror("Invalid ID generation");
        return logger;
      }
    }

    // Check for existing log buffer to recycle 
    EVENT_RECORD *existingLog = malloc(sizeof(EVENT_RECORD));
    if (!existingLog) {
        perror("Memory allocation failed");
        return logger;
    }

    // Set default directory path for logs if not already set
    char* logDirPath = getDefaultDirectory();
