['Here's a basic implementation in C for your task:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    int value;
    char buffer[256];
    long* key;
    char* metadata;
} record_t;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static size_t MAX_SIZE = 1024 * 1024; // Default maximum size

long* keys;
record_t** records;
size_t currentSize = 0;

void initialize(int seed) {
    srand(seed);

    keys = malloc(MAX_SIZE * sizeof(long));
    if (keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        exit(EXIT_FAILURE);
    }

    records = malloc(MAX_SIZE * sizeof(record_t*));
    if (records == NULL) {
        free(keys);
        fprintf(stderr, "Memory allocation failed for records\n");
        exit(EXIT_FAILURE);
    }

    // Initialize keys with random numbers between 1 and 1000.
    for (size_t i = 0; i < MAX_SIZE; ++i) {
        keys[i] = rand() % 1000 + 1;
    }
}

void addRecord(int value, char* buffer, size_t keyIndex, char* metadata) {
    if (currentSize >= MAX_SIZE) {
        fprintf(stderr, "Memory pool is full\n");
        return;
    }

    record_t* newRecord = malloc(sizeof(record_t));
    if (newRecord == NULL) {
        fprintf(stderr, "Memory allocation failed for a new record\n");
        return;
    }

    pthread_mutex_lock(&lock); // Lock to ensure thread safety.
    strncpy(newRecord->buffer, buffer, sizeof(newRecord->buffer) - 1);
    newRecord->value = value;
    newRecord->key = &keys[keyIndex];
    newRecord->metadata = metadata; // Assume this is dynamically allocated and freed elsewhere.
    records[currentSize++] = newRecord;
    pthread_mutex_unlock(&lock);
}

void cleanup() {
    for (size_t i = 0; i < currentSize; ++i) {
        free(records[i]);
    }
    free(keys);
    free(records);
}
```
This code assumes that `MAX_SIZE` is set to a reasonable value. In a real application, you may need to adjust this dynamically based on your workload or use a more sophisticated memory management system such as jemalloc. 

Note: The `cleanup()` function doesn't handle cleaning up the metadata strings in each record, because it's assumed these are handled elsewhere (for example, they might be pointers into dynamically-allocated memory that needs to be freed somewhere else). If you need to free this memory as well, you would add a nested loop here.
