    if (array == NULL) {
        // log error and return null
        externalLoggingSystem::log("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); 
    for(int i = 0; i < size; i++) {
        int lastFlag = (i > 0)? array[i - 1].RX_UE_INFORMATION_TAG.CRC_INDICATION_REL8_TAG: -1;
        array[i].RX_UE_INFORMATION_TAG.RNTI = tagdata[i % size].RNTI;

