["Here is a basic implementation in C with some assumptions due to lack of specific requirements in problem description. 

```c
#include <stdlib.h>
#define MAX_SUM 10000 // Global upper bound on the total sum of integer values

typedef struct Record {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct DynamicRecordStore {
    size_t capacity;
    size_t size;
    int currentSum;
    Record **records;
} DynamicRecordStore;

DynamicRecordStore* createDynamicRecordStore(size_t initialCapacity) {
    DynamicRecordStore *store = malloc(sizeof(DynamicRecordStore));
    if (store == NULL) return NULL;

    store->capacity = initialCapacity;
    store->size = 0;
    store->currentSum = 0;

    store->records = calloc(initialCapacity, sizeof(Record *));
    if (store->records == NULL) {
        free(store);
        return NULL;
    }

    return store;
}

int insertRecord(DynamicRecordStore* store, Record *record) {
    // Check if the sum will exceed the maximum allowed value.
    int newSum = store->currentSum + record->value;
    if (newSum > MAX_SUM) return 0;

    if (store->size == store->capacity) {
        // If full, resize the array by doubling its capacity.
        size_t newCapacity = store->capacity * 2;
        Record **newRecords = realloc(store->records, sizeof(Record *) * newCapacity);

        if (newRecords == NULL) return -1; // Failed to allocate memory.

        store->records = newRecords;
        store->capacity = newCapacity;
    }

    // Insert the record at the end of the array.
    store->records[store->size] = record;
    store->size++;
    store->currentSum += record->value;

    return 1;
}

Record* getRecord(DynamicRecordStore* store, size_t index) {
    if (index >= store->size) return NULL; // Index out of bounds.

    return store->records[index];
}

int updateRecord(DynamicRecordStore* store, size_t index, Record *record) {
    if (index >= store->size) return 0; // Index out of bounds.

    // Check if the new value will exceed the maximum allowed sum.
    int oldValue = store->records[index]->value;
    int newSum = store->currentSum - oldValue + record->value;
    if (newSum > MAX_SUM) return 0;

    // Update the record.
    free(store->records[index]);
    store->records[index] = record;
    store->currentSum += record->value - oldValue;

    return 1;
}
```
