    product->RNTI = RNTI;
    product->CRCFLAG = rand() % 2 == 0;  // Random Boolean for CRCFLAG

    inventory.products[inventory.size++] = product;  // Add to Inventory

    pthread_mutex_unlock(&inventory.lock);
}

void updateProduct(int productID, char *name, double price, int RNTI, bool CRCFLAG) {
    pthread_mutex_lock(&inventory.lock);

    for (int i = 0; i < inventory.size; ++i) {
        if (inventory.products[i]->productID == productID) {  // If Product found in Inventory
            strncpy(inventory.products[i]->name, name, 50);
            inventory.products[i]->price = price;
            inventory.products[i]->RNTI = RNTI;
            inventory.products[i]->CRCFLAG = CRCFLAG;
        }
    }

    pthread_mutex_unlock(&inventory.lock);
}

void removeProduct(int productID) {
    pthread_mutex_lock(&inventory.lock);

    for (int i = 0; i < inventory.size; ++i) {
        if (inventory.products[i]->productID == productID) {  // If Product found in Inventory
            free(inventory.products[i]);
            inventory.products[i] = inventory.products[--inventory.size];
        }
    }

    pthread_mutex_unlock(&inventory.lock);
}
