```cpp
#include <vector>
#include <mutex>
#include <atomic>
#include <shared_mutex>
#include <string>
#include <memory>
#include "database.h"  // external database library

class DataRecord {
public:
    uint64_t userId;
    double transactionAmount;
    time_t timestamp;
    bool statusFlag;
    std::shared_ptr<void> additionalData;

    DataRecord(uint64_t id, double amount, time_t ts, bool flag) : 
        userId(id), transactionAmount(amount), timestamp(ts), statusFlag(flag) {}
};

class DataRecordManager {
private:
    std::vector<std::shared_ptr<DataRecord>> records;
    std::atomic<bool> inMemoryStorage = true;  // default is true for in-memory storage.
    Database* db;
    std::mutex mtx;
    std::shared_timed_mutex read_mtx;

public:
    DataRecordManager(int N, bool useInMemory=true) : records(N), inMemoryStorage(useInMemory) {
        if (!inMemoryStorage) db = new Database();  // initialize external database.
    }

    ~DataRecordManager() {
        std::lock_guard<std::mutex> guard(mtx);
        delete db;
    }

    void addRecord(uint64_t id, double amount, time_t ts, bool flag) {
        if (inMemoryStorage) {
            std::unique_lock<std::shared_timed_mutex> writeLock(read_mtx);
            for (size_t i = 0; i < records.size(); ++i) {
                // Add new record if the slot is empty.
                if (!records[i]) {
                    records[i] = std::make_shared<DataRecord>(id, amount, ts, flag);
                    break;
                }
            }
        } else {
            db->addRecord(id, amount, ts, flag);  // Add record to database.
        }
    }

    void updateRecord(size_t index, uint64_t id, double amount, time_t ts, bool flag) {
        if (index >= records.size()) return;  // out of bounds check.

        if (inMemoryStorage) {
            std::unique_lock<std::shared_timed_mutex> writeLock(read_mtx);
            auto record = records[index];
            if (record) {
                // Perform update operation on the record.
                record->userId = id;
                record->transactionAmount = amount;
                record->timestamp = ts;
                record->statusFlag = flag;
            } else {
                records[index] = std::make_shared<DataRecord>(id, amount, ts, flag);  // Create new record.
            }
        } else {
            db->updateRecord(index, id, amount, ts, flag);  // Update record in database.
        }
    }
};
```
