void allocateAndInitializeArrays(GHashTable* hash_table, long* offsets, int* keys) {
    srand(time(NULL));

    // Generate unique keys
    while (g_hash_table_size(hash_table) < ARRAY_SIZE) {
        int key = rand() % MAX_KEY_VALUE;

        if (!g_hash_table_contains(hash_table, &key)) {
            g_hash_table_insert(hash_table, &key, NULL);
        }
    }

    // Initialize offsets and keys arrays
    int i = 0;
    for (GList* l = g_hash_table_get_keys(hash_table); l != NULL; l = l->next) {
        offsets[i] = l->data;
        keys[i++] = *((int*)l->data);
    }
}

// Distributed hash table for managing unique keys
