Record* records;
long* offsets;
int* keys;

void init() {
    // Initialize hash table
    distributed_hash_table = g_hash_table_new(g_direct_hash, g_direct_equal);

    allocateAndInitializeArrays(distributed_hash_table, offsets, keys);

    // Allocate records array
    records = (Record*) malloc(sizeof(Record) * ARRAY_SIZE);
}

// Thread function to populate records with random values
void* threadFunction(void* arg) {
    int index = *((int*)arg);

    while (1) {
        // Generate random value
        int value = rand() % MAX_VALUE;

        // Lock the record and insert if not occupied, unlock
        pthread_mutex_lock(&records[index].lock);
        if (!records[index].occupied) {
            records[index].value = value;
            records[index].occupied = TRUE;

            // Broadcast to other threads that record is ready
            pthread_cond_broadcast(&records[index].ready);
        }
        pthread_mutex_unlock(&records[index].lock);
    }

    return NULL;
}
