#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char *name;
    double value;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DynamicArray {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray *a, size_t initialSize) {
    a->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->lock, NULL);
}

void insertDynamicArray(DynamicArray *a, NFAPI_CRC_INDICATION_PDU_T element) {
    if (a->used == a->size) {
        a->size *= 2;
        a->array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(a->array, a->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    pthread_mutex_lock(&a->lock);
    a->array[a->used++] = element;
    pthread_mutex_unlock(&a->lock);
}

void freeDynamicArray(DynamicArray *a) {
    free(a->array);
    a->array = NULL;
    a->used = a->size = 0;
    pthread_mutex_destroy(&a->lock);
}
```
In this code, we use `DynamicArray` to manage our dynamic collection. We start by initializing the array with a certain size and then grow it as needed using `realloc` when the capacity is reached. 

