typedef struct KV_ITEM_T {
    char* key;
    size_t valueSize;
    atomic_size_t refCount;
    time_t expireAt;
    void *value;  // dynamically allocated buffer for the actual value
} KV_ITEM_T;

typedef struct cacheManager {
    pthread_mutex_t lock;
    KV_ITEM_T** items;
    size_t maxSize;
    atomic_size_t currentSize;
    time_t itemLifespan;  // in seconds
} CacheManager;

CacheManager* initCache(size_t initialSize, time_t lifespan) {
    CacheManager* manager = malloc(sizeof(CacheManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);

    manager->items = calloc(initialSize, sizeof(KV_ITEM_T*));
    if (!manager->items) {
        free(manager);
        return NULL;
    }

    manager->maxSize = initialSize;
    atomic_init(&manager->currentSize, 0);
    manager->itemLifespan = lifespan;

    // Initialize each entry in the cache to be null.
    for (size_t i = 0; i < manager->maxSize; ++i) {
        manager->items[i] = NULL;
    }

    return manager;
}

void* get(CacheManager* manager, const char* key) {
    pthread_mutex_lock(&manager->lock);

    time_t now = time(NULL);
    for (size_t i = 0; i < manager->maxSize; ++i) {
        KV_ITEM_T* item = manager->items[i];

        if (!item || now >= atomic_load(&item->expireAt)) continue;  // Skip expired items.

        if (strcmp(item->key, key) == 0) {
            atomic_fetch_add(&item->refCount, 1);

            void* value = item->value;

            pthread_mutex_unlock(&manager->lock);
            return value;
        }
    }

    // Item not found or expired.
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// More functions for add, update and remove would follow similar patterns.
