#include <stdlib.h>
#include <pthread.h>
#define TABLE_SIZE 10007

typedef struct record {
    int key;
    long offset;
    struct record *next;
} Record;

Record* table[TABLE_SIZE];
int count = 0; // Number of records
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insert(int key, long offset) {
    pthread_mutex_lock(&lock);
    Record *newRecord = malloc(sizeof(Record));
    newRecord->key = key;
    newRecord->offset = offset;

    int index = hash(key);
    if (table[index] == NULL) {
        table[index] = newRecord;
    } else {
        Record *current = table[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newRecord;
    }
    ++count;
    pthread_mutex_unlock(&lock);
}

Record* lookup(int key) {
    int index = hash(key);
    Record *current = table[index];
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    return current;
}
```
