#include <dirent.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>

typedef struct {
    time_t min_timestamp;
    time_t max_timestamp;
} TimeRange;

void processDirectory(const char* directory, TimeRange range) {
    DIR* dir = opendir(directory);
    if (dir == NULL) {
        fprintf(stderr, "Could not open directory: %s\n", directory);
        return;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char path[PATH_MAX];
        snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);

        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;  // Skip '.' and '..'
        }

        struct stat st;
        if (stat(path, &st) < 0) {
            fprintf(stderr, "Could not get file status: %s\n", path);
            continue;
        }

        // Filter by timestamp.
        time_t last_modified = st.st_mtime;
        if (last_modified < range.min_timestamp || last_modified > range.max_timestamp) {
            continue;  // Skip files outside the specified range.
        }

        // Extract metadata from filename and update summary report.
        char* extension = strrchr(entry->d_name, '.');
        if (extension != NULL && strcmp(extension, ".log") == 0) {
            // Assuming the base name is in the format "<keyword>-<timestamp>".
            char* hyphen = strchr(entry->d_name, '-');
            if (hyphen != NULL) {
                size_t keyword_length = hyphen - entry->d_name;
                char keyword[keyword_length + 1];
                strncpy(keyword, entry->d_name, keyword_length);
                keyword[keyword_length] = '\0';
                // TODO: Update summary report using the extracted metadata.
            }
        }
    }

    closedir(dir);
}
```
This code provides a basic starting point for your task and can be extended as needed according to the requirements. It does not handle race conditions or multithreading, though. For such functionality you may want to look into using inotify on Linux and FSEvents on macOS, which can notify your application when changes occur within a directory.
