```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    double d1;
    double d2;
} MAC_PDU;

typedef struct {
    char* id;
    int PHY_TIMESTAMP;
} PHY_PDU;

typedef struct {
    MAC_PDU mac;
    PHY_PDU phy;
} NR_PDU_T;

NR_PDU_T * initializePDUSet(int num, const char* str, int timestamp) {
    NR_PDU_T *arr = (NR_PDU_T*) malloc(num * sizeof(NR_PDU_T));
    if (!arr) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    char* strDup = strdup(str);
    char* token = strtok(strDup, ",");
    for (int i = 0; i < num; i++) {
        if (!token) {
            fprintf(stderr, "Not enough elements in string\n");
            free(arr);
            arr = NULL;
            break;
        } else {
            arr[i].mac.d1 = atof(token);

            token = strtok(NULL, ",");
            if (!token) {
                fprintf(stderr, "Not enough elements in string\n");
                free(arr);
                arr = NULL;
                break;
            } else {
                arr[i].mac.d2 = atof(token);

                token = strtok(NULL, ","); // Get the next id or null if no more tokens
            }
        }

        arr[i].phy.id = (char*) malloc(sizeof(char) * 10); // Assuming max size is 10 for simplicity
        if (!arr[i].phy.id) {
            fprintf(stderr, "Memory allocation failed\n");
            free(arr);
            arr = NULL;
            break;
        } else {
            strncpy(arr[i].phy.id, token ? token : "", 10); // If no more tokens, use empty string for id
            arr[i].phy.PHY_TIMESTAMP = timestamp + i; // Timestamp increments by 1 for each subsequent structure
        }
    }

    free(strDup);
    return arr;
}

double computeAverage(NR_PDU_T *arr, int num) {
    double sum = 0.0;
    for (int i = 0; i < num; i++) {
        sum += arr[i].mac.d1 + arr[i].mac.d2;
    }

    return sum / (num * 2); // Average of both MAC_PDU doubles
}
```
You can use this code like so:

