#include <mutex>
#include <vector>
#include <string>
#include <ctime>

struct PacketHeader {
  int protocolVersion;
  int sequenceNumber;
  time_t timestamp;
  size_t payloadLength;
  std::string sourceIP, destIP;
};

class DynamicArrayManager {
 private:
  std::vector<PacketHeader> headers_;
  std::mutex mtx_;

 public:
  void Init(size_t M) {
    std::lock_guard<std::mutex> lock(mtx_);
    headers_.reserve(M);
  }

  int AppendHeader(const PacketHeader& header) {
    if (header.sequenceNumber <= 0 || header.payloadLength == 0 || 
        header.sourceIP.empty() || header.destIP.empty()) return -1;

    std::lock_guard<std::mutex> lock(mtx_);
    headers_.push_back(header);

    if (headers_.size() == headers_.capacity()) {
      size_t newCap = static_cast<size_t>(1.5 * headers_.capacity());
      std::vector<PacketHeader> newHeaders;
      newHeaders.reserve(newCap);
      newHeaders.assign(headers_.begin(), headers_.end());

      // Swap the old and the new vector to minimize memory footprint
      headers_ = std::move(newHeaders);
    }

    return 0;
  }

  int UpdateHeaderAtIndex(int idx, const PacketHeader& header) {
    if (idx < 0 || static_cast<size_t>(idx) >= headers_.size()) return -1;
    std::lock_guard<std::mutex> lock(mtx_);

    headers_[idx] = header;
    return 0;
  }

  int RemoveHeaderAtIndex(int idx) {
    if (idx < 0 || static_cast<size_t>(idx) >= headers_.size()) return -1;
    std::lock_guard<std::mutex> lock(mtx_);

    headers_.erase(headers_.begin() + idx);
    return 0;
  }

  // Implement iterator-based access methods for forward and backward directions.
};
```

