    if (count >= MAX_ENTRIES) {
        Node *temp = head;
        for (int i = 0; i < MAX_ENTRIES - 1; i++) {
            temp = temp->next;
        }

        free(temp->next);
        temp->next = NULL;
    } else {
        count++;
    }

    head = newNode;
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* get(int RNTI) {
    pthread_mutex_lock(&lock);

    Node *temp = head;
    while (temp != NULL) {
        if (temp->data->RNTI == RNTI) {
            NFAPI_CRC_INDICATION_PDU_T* dataCopy = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(dataCopy, temp->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

            pthread_mutex_unlock(&lock);
            return dataCopy;
        }

        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}
```
This is a simple implementation of a linked list with dynamic resizing, error handling for duplicate `RNTI` assignments and thread safety. It uses a mutex to ensure that only one thread can access the list at a time, thus preventing data races. The insert function checks if the maximum size has been reached before adding a new node. If it has, it removes the last node from the list.

The get function searches through the linked list for a `NFAPI_CRC_INDICATION_PDU_T` with the given `RNTI` and returns a copy of the data if found. This ensures that even when multiple threads are accessing the same `RNTI`, they will each receive their own copy of the data without causing data races.
