#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Data structure to hold int value and char* string
typedef struct {
    int value;
    char* str;
} data_t;

// Node in the list, with pointer to next node
typedef struct node_t {
    data_t* data;
    struct node_t* next;
} node_t;

// Add a new node at the end of the list
node_t* add_node(node_t** head, int value, const char* str) {
    node_t* newNode = malloc(sizeof(node_t));
    assert(newNode != NULL); // Ensure memory allocation was successful

    newNode->data = malloc(sizeof(data_t));
    assert(newNode->data != NULL); // Ensure memory allocation was successful

    newNode->data->value = value;
    newNode->data->str = strdup(str);
    newNode->next = NULL;

    if (*head == NULL) {
        *head = newNode;
    } else {
        node_t* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    return newNode;
}

// Update existing node's data
void update_node(node_t* node, int value, const char* str) {
    assert(node != NULL); // Check that the node exists before updating its data
    free(node->data->str); // Free old string to prevent memory leak

    node->data->value = value;
    node->data->str = strdup(str);
}

// Safely free all allocated memory when the list is destroyed
void destroy_list(node_t** head) {
    while (*head != NULL) {
        node_t* nextNode = (*head)->next;
        free((*head)->data->str); // Free string before data
        free((*head)->data); 
        free(*head); 
        *head = nextNode;
    }
}
```
