['Here's an example implementation using C99 standard library's `<threads.h>` for thread safety and error handling, and a custom logging system that supports configurable levels of detail.

```c
#include <stdlib.h>
#include <string.h>
#include <threads.h>
#include <stdatomic.h>

typedef struct NFAPI_CRC_INDICATION_PDU {
    int RX_UE_INFORMATION_TAG;
    unsigned RNTI;
    char* CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    mtx_t lock;
    int maxSize;
    float growthFactor;
    int loggingLevel;
    atomic_int currentSize;
    NFAPI_CRC_INDICATION_PDU_T* array;
} Manager;

Manager manager = { .maxSize = 100, .growthFactor = 2.0f }; // default settings

void logMessage(const char* message, int level) {
    if (level <= manager.loggingLevel) {
        printf("%s\n", message);
    }
}

int createArray(int N) {
    mtx_lock(&manager.lock);
    if (N < 1 || N > manager.maxSize) {
        logMessage("Invalid array size, must be between 0 and max size.", 2);
        return -1;
    }
    if(manager.array == NULL){
      mtx_unlock(&manager.lock);
      return -1; // Array not allocated yet
    }
    manager.currentSize = N;
    logMessage("Array created/resized successfully.", 0);
    mtx_unlock(&manager.lock);
    return 0;
}

int allocate(NFAPI_CRC_INDICATION_PDU_T* array) {
    mtx_lock(&manager.lock);
    manager.array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)*manager.maxSize);
    if(manager.array == NULL){
      logMessage("Failed to allocate memory.", 1);
      mtx_unlock(&manager.lock);
      return -1;
    } else {
        memcpy(manager.array, array, sizeof(NFAPI_CRC_INDICATION_PDU_T)*N);
    }
    logMessage("Memory allocated successfully.", 0);
    mtx_unlock(&manager.lock);
    return 0;
}

int deallocate() {
    mtx_lock(&manager.lock);
    free(manager.array);
    manager.array = NULL;
    logMessage("Memory deallocated successfully.", 0);
    mtx_unlock(&manager.lock);
    return 0;
}
```
This is a basic outline of the code, please adjust it according to your needs. In a real-world scenario, additional features like memory monitoring and configuration options would be implemented separately in an encapsulated manner. You might want to consider using a library such as glib or boost for C++ for these purposes if you're comfortable with them.
']

