typedef struct event_t {
    char *name;
    time_t timestamp;
} Event;

Event **events = NULL;
size_t numEvents = 0, arraySize = 0;

void addEvent(const char *name) {
    if (numEvents == arraySize) {
        arraySize = arraySize ? arraySize*2 : 1; // Start with 1 or double current size
        events = realloc(events, sizeof(*events)*arraySize); // Resize array
        if (!events) exit(EXIT_FAILURE); // Check memory allocation success
    }

    Event *event = malloc(sizeof(*event)); // Allocate memory for new event
    if (!event) exit(EXIT_FAILURE);

    event->name = strdup(name); // Copy event name
    if (!event->name) exit(EXIT_FAILURE);

    time(&event->timestamp); // Set current timestamp for new event

    events[numEvents++] = event; // Add to list of events
}

int main() {
    addEvent("First event");
    addEvent("Second event");

    for (size_t i = 0; i < numEvents; ++i) {
        printf("%s @ %ld\n", events[i]->name, (long)events[i]->timestamp);
        free(events[i]->name); // Free name memory
        free(events[i]); // Free event structure memory
    }

    free(events); // Finally free the array itself
}
```
