```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Node {
    int value;
    char* str_data;
    struct Node *next, *prev;
} Node;

Node* create_node(int val, const char* str) {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;

    node->value = val;
    node->str_data = malloc((strlen(str) + 1) * sizeof(char));  // allocate memory for str_data
    if(!node->str_data) {
        free(node);
        return NULL;
    }
    strcpy(node->str_data, str);
    node->next = NULL;
    node->prev = NULL;
    return node;
}

int insert_beginning(Node** head, int val, const char* str) { 
    Node* new_node = create_node(val, str);
    if(!new_node) return -1;

    if(*head != NULL) {
        (*head)->prev = new_node;
        new_node->next = *head;
    }

    *head = new_node;  // update head of list to point to the new node
    return 0;
}

int insert_end(Node** head, int val, const char* str) {
    Node* new_node = create_node(val, str);
    if(!new_node) return -1;

    if(*head == NULL) {
        *head = new_node;  // if list is empty, update head to point to the new node
    } else {
        Node* temp = *head;
        while(temp->next != NULL) temp = temp->next;  // traverse till end of list
        temp->next = new_node;
        new_node->prev = temp;
    }

    return 0;
}

// and so on... for delete operations as well.
```
This is a simple implementation where each node stores an integer value and a dynamically allocated string data. Insertion at beginning or end of list is handled in `insert_beginning` and `insert_end` functions respectively. The actual implementations will be quite complex considering all the constraints listed above. Also, consider that this code does not handle errors such as lack of memory which should ideally be checked by each function using these.
