int insert(Item* item, unsigned int pos) {
    if (pos > count || count >= 100) return -1; // If list is full or position is invalid
    ++count;
    Item* new_item = malloc(sizeof(Item));
    if(!new_item) return -2;  // Allocation failure

    new_item->value = item->value;
    new_item->str_value = strdup(item->str_value);  // Duplicate string data
    if (!new_item->str_value) return -2; // Memory allocation failure

    new_item->index = pos;  // Set index to the position in list
    ++count;  // Increment count of nodes in list

    Item* curr = head, *prev = NULL;
    for(int i=0; i<pos && curr; ++i) { prev = curr; curr = curr->next; } // Find insert position

    new_item->next = curr;  // Set next of new node to current node at pos
    if(curr) curr->prev = new_item;  // If not end, set prev of current to new item
    if(!head || !pos) head = new_item; // If inserting at head or empty list, update head
    else prev->next = new_item;  // Otherwise, set next of previous node to new node

    return 0;
}

void traverseForward() {
    Item* curr = head;
