```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    float f_num;
    int* array;
} Value;

// A simple chained hashing implementation 
typedef struct Node {
    char* key;
    Value value;
    struct Node* next;
} HashNode;

HashNode** hashTable;
int tableSize = 10007; // Prime number to reduce collisions
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

unsigned long hash(const char* str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return hash % tableSize;
}

HashNode* createNode(const char* key, Value value) {
    HashNode* node = malloc(sizeof(HashNode));
    if (node == NULL) {
        perror("Failed to allocate memory for a new hash node");
        exit(EXIT_FAILURE);
    }

    node->key = strdup(key);
    if (node->key == NULL) {
        perror("Failed to duplicate the key string");
        free(node);
        exit(EXIT_FAILURE);
    }

    node->value = value;
    node->next = NULL;

    return node;
}

void insertNode(const char* key, Value value) {
    unsigned long index = hash(key);

    pthread_mutex_lock(&mutex);
    HashNode* node = createNode(key, value);
    node->next = hashTable[index];
    hashTable[index] = node;
    pthread_mutex_unlock(&mutex);
}

// Similar functions for delete and update. 
// You need to check key existence before deletion or updating.
```

