typedef struct PacketHeader {
    int version;
    _Atomic(int) seq_num;
    long timestamp;
    _Atomic(int) payload_len;
} PacketHeader;

typedef struct QueueNode {
    PacketHeader* packet;
    struct QueueNode* next;
} QueueNode;

pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
QueueNode* priority_queue[5] = {NULL}; // Assuming 5 levels of priorities

void initPacketHeaders(int M) {
    PacketHeader* array = malloc(sizeof(PacketHeader) * M);

    for (int i = 0; i < M; i++) {
        array[i].version = 1; // Set appropriate version number here
        atomic_init(&array[i].seq_num, 0);
        array[i].timestamp = time(NULL);
        atomic_init(&array[i].payload_len, 0);
    }

    // Initialization of other fields...
}

void updateHeader(_Atomic(int)* header, int newValue) {
    _Atomic(int) temp;

    do {
        temp = atomic_load(header);
    } while(!atomic_compare_exchange_weak(header, &temp, newValue));
}

void enqueuePacket(PacketHeader* packet, int priority) {
    QueueNode* node = malloc(sizeof(QueueNode));
    node->packet = packet;

    pthread_mutex_lock(&queue_lock);
    if (priority_queue[priority] == NULL) {
        priority_queue[priority] = node;
    } else {
        QueueNode* temp = priority_queue[priority];

        while(temp->next != NULL) {
            temp = temp->next;
        }

        temp->next = node;
    }

    pthread_mutex_unlock(&queue_lock);
}

// The rest of the code will be a lot more complex and involve network programming, 
// callbacks, memory management, error handling etc. 
