["Here is an example of how you could write this stored procedure in SQL (PostgreSQL syntax):

```SQL
CREATE OR REPLACE FUNCTION get_employee_info(supervisor_id INT, department_id INT, query_user_id INT) 
RETURNS TABLE(
    name VARCHAR(255), 
    city VARCHAR(255), 
    address VARCHAR(255), 
    department_name VARCHAR(255)
) AS $$
DECLARE
    api_response JSON;
BEGIN
    -- Check if supervisor_id and department_id exist
    PERFORM 1 FROM employee WHERE id = supervisor_id AND department = department_id;
    IF NOT FOUND THEN 
        RAISE EXCEPTION 'Supervisor or Department does not exist';
    END IF;

    -- Try to fetch from cache first
    SELECT * INTO name, city, address, department_name FROM employee_cache WHERE id = supervisor_id AND department = department_id;
    IF NOT FOUND THEN 
        -- If not in cache, call the external API and insert into cache
        BEGIN
            api_response := external_api_call(supervisor_id);

            INSERT INTO employee_cache (id, name, city, address, department) 
            VALUES (supervisor_id, api_response->>'name', api_response->>'city', api_response->>'address', department_id);
        EXCEPTION WHEN OTHERS THEN
            -- Handle error and retry API call if necessary
            RAISE WARNING 'API call failed: %', SQLERRM;

            -- Retry after a delay...
            PERFORM pg_sleep(1);

            api_response := external_api_call(supervisor_id);

            INSERT INTO employee_cache (id, name, city, address, department) 
            VALUES (supervisor_id, api_response->>'name', api_response->>'city', api_response->>'address', department_id);
        END;
    END IF;

    -- Log the query execution
    INSERT INTO log_table (query_user_id, timestamp) VALUES (query_user_id, NOW());

    RETURN QUERY SELECT name, city, address, department.name 
                FROM employee, department WHERE id = supervisor_id AND department = department_id;
END; $$ LANGUAGE plpgsql;
```
Please note that this is a basic demonstration and doesn't handle all edge cases or optimizations that might be necessary in a production environment. It also assumes that there are tables `employee`, `department`, `employee_cache`, `log_table`, and an external API function `external_api_call(supervisor_id INT) RETURNS JSON` is defined elsewhere. 

