    $this->db = $db;
    $this->queue = $queue;
    $this->identityServiceUrl = $identityServiceUrl;
  }

  public function updateUserProfile($userId, $newEmail) {
    // Validate email format
    if (!filter_var($newEmail, FILTER_VALIDATE_EMAIL)) {
      throw new Exception('Invalid email format');
    }

    // Check for duplicate emails
    $query = "SELECT COUNT(*) FROM users WHERE email = ?";
    $params = [$newEmail];
    $stmt = $this->db->prepare($query);
    $stmt->execute($params);
    if ($stmt->fetchColumn() > 0) {
      throw new Exception('Duplicate email');
    }

    // Update the user's email
    $query = "UPDATE users SET email = ? WHERE id = ?";
    $this->db->beginTransaction();
    $stmt = $this->db->prepare($query);
    $stmt->execute([$newEmail, $userId]);

    // Notify the identity service
    $message = ['type' => 'email_updated', 'data' => ['id' => $userId, 'email' => $newEmail]];
    $this->queue->publish(json_encode($message));

    $this->db->commit();
  }

  // Additional methods for handling network failures, asynchronous operations and low latency data access
}
```
