            char *filenameCopy = strdup(entry->d_name);
            filenameCopy[strlen(filenameCopy) - 4] = '\0'; // Remove the .mp3 extension from title and artist.

            metadataArray[fileCount].title = filenameCopy; // Use file name as default title.
            metadataArray[fileCount].artist = "Unknown"; // Default artist is Unknown for instance.

            fileCount++;
        }
    }

    /* Code to concatenate the mp3 files based on the sampleRates, bitrates and qualitySettings arrays.  */

    closedir(dir);
    mpg123_delete(mh);
    return 0;
}
