['Here are your tasks translated into code blocks. 

1. **C code for allocating, initializing and freeing memory:**
```c
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    char* log_message;
} record;

record *initialize_records(int num_records, int min_key, int max_key, const char **templates, size_t template_size) 
{
    srand(time(NULL));

    // Allocate memory for the array of records
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) return NULL;

    // Initialize each record in the array
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = (long)&records[i];

        int random_index = rand() % template_size;
        size_t message_length = strlen(templates[random_index]);
        records[i].log_message = (char*)malloc(message_length + 1);
        if (!records[i].log_message) {
            // Memory allocation failed, free previous allocations and return NULL
            for (int j = 0; j < i; ++j) {
                free(records[j].log_message);
            }
            free(records);
            return NULL;
        }

        strcpy(records[i].log_message, templates[random_index]);
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
    }

    // Free the memory when done with it to avoid leaks
    free(records);
}
