['Below is a basic implementation of your requirements using C language:

```c
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
    char *buffer;
} Record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize(long ***offsets, int **keys, Record **records, int n, int m, int k, int l) {
    if (n < 0 || m < 0 || k < 0 || l < 0) {
        printf("Invalid input parameters detected. Using default values.\n");
        return;
    }

    srand(time(NULL));

    // Allocate memory for offsets
    *offsets = (long **)malloc(n * sizeof(long *));
    if (*offsets == NULL) {
        printf("Failed to allocate memory for offsets.\n");
        return;
    }

    for (int i = 0; i < n; i++) {
        (*offsets)[i] = (long *)malloc(m * sizeof(long));
        if ((*offsets)[i] == NULL) {
            printf("Failed to allocate memory for offset[%d].\n", i);
            return;
        }

        // Initialize with random values between -1000 and 1000
        for (int j = 0; j < m; j++) {
            (*offsets)[i][j] = rand() % 2001 - 1000;
        }
    }

    // Allocate memory for keys
    *keys = (int *)malloc(k * sizeof(int));
    if (*keys == NULL) {
        printf("Failed to allocate memory for keys.\n");
        return;
    }

    // Initialize with sequential values starting from 1
    int currentKey = 1;
    for (int i = 0; i < k; i++) {
        (*keys)[i] = currentKey++;

        if ((*keys)[i] < 0) {
            printf("Ran out of unique keys.\n");
            return;
        }
    }

    // Allocate memory for records
    *records = (Record *)malloc(l * sizeof(Record));
    if (*records == NULL) {
        printf("Failed to allocate memory for records.\n");
        return;
    }

    // Initialize with corresponding key and offset values
    for (int i = 0; i < l; i++) {
        (*records)[i].key = (*keys)[i % k];
        (*records)[i].offset = (*offsets)[i % n][0];  // Assuming m=1 here

        // Allocate memory for buffer
        (*records)[i].buffer = (char *)malloc(m * sizeof(char));
        if ((*records)[i].buffer == NULL) {
            printf("Failed to allocate memory for record[%d] buffer.\n", i);
            return;
        }
    }
}

void reset(long ***offsets, int **keys, Record **records, int n, int m, int k, int l) {
    pthread_mutex_lock(&mutex);

    // Reset each offset array back to its initial state
    for (int i = 0; i < n; i++) {
        free((*offsets)[i]);
    }
