// A dynamic array of packet headers with a read-write lock for thread safety
typedef struct {
    pthread_rwlock_t lock;
    size_t capacity;
    size_t size;
    PacketHeader *headers;
} HeaderArray;

void init_header_array(HeaderArray *arr, size_t initial_capacity) {
    arr->capacity = initial_capacity;
    arr->size = 0;
    arr->headers = malloc(initial_capacity * sizeof(PacketHeader));
    pthread_rwlock_init(&arr->lock, NULL);
}

// Add a header to the array, resizing if necessary
void add_header(HeaderArray *arr, PacketHeader header) {
    // Acquire write lock before modifying the array
    pthread_rwlock_wrlock(&arr->lock);

    if (arr->size == arr->capacity) {
        // Resize array
        size_t new_capacity = arr->capacity * 2;
        PacketHeader *new_headers = realloc(arr->headers, new_capacity * sizeof(PacketHeader));

        if (new_headers == NULL) {
            // Handle allocation failure...
        }

        arr->headers = new_headers;
        arr->capacity = new_capacity;
    }

    arr->headers[arr->size++] = header;

    pthread_rwlock_unlock(&arr->lock);
}
```

This is a simple implementation of the dynamic array with thread safety in mind. It uses a read-write lock to ensure that only one thread can write at a time, but multiple threads can read simultaneously. The `add_header` function resizes the array if necessary using `realloc` when adding an entry.

