```c
#include <pthread.h>
#include <time.h>
#include <stdlib.h>

typedef struct {
    int version;
    int sequence_number;
    time_t timestamp;
    size_t payload_length;
} PacketHeader;

typedef struct {
    PacketHeader* headers;
    size_t count;
    pthread_mutex_t mutex;  // for thread safety
} HeaderArray;

void array_init(HeaderArray *array, size_t initial_size) {
    array->headers = malloc(initial_size * sizeof(PacketHeader));
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);  // initialize mutex
}

void array_add(HeaderArray *array, PacketHeader header) {
    if (header.sequence_number <= 0 || header.payload_length < 0) return;  // skip invalid entries

    pthread_mutex_lock(&array->mutex);  // acquire lock before modifying data

    array->count++;

    if (array->count > initial_size) {  // check for reallocation
        size_t new_size = initial_size * 2;
        array->headers = realloc(array->headers, new_size * sizeof(PacketHeader));
    }

    array->headers[array->count - 1] = header;

    pthread_mutex_unlock(&array->mutex);  // release lock after modifying data
}

void iterate_forward(HeaderArray *array, void (*callback)(PacketHeader*)) {
    for (size_t i = 0; i < array->count; ++i) {
        callback(&array->headers[i]);
    }
}

void iterate_backward(HeaderArray *array, void (*callback)(PacketHeader*)) {
    for (size_t i = array->count; i > 0; --i) {
        callback(&array->headers[i - 1]);
    }
}

void update_header(HeaderArray *array, int index, PacketHeader new_header) {
    if (index < 0 || index >= array->count) return; // check for out of bounds access

    pthread_mutex_lock(&array->mutex);  // acquire lock before modifying data

    array->headers[index] = new_header;

    pthread_mutex_unlock(&array->mutex);  // release lock after modifying data
}

void array_free(HeaderArray *array) {
    pthread_mutex_lock(&array->mutex);  // acquire lock before freeing memory

    free(array->headers);
    array->count = 0;

    pthread_mutex_unlock(&array->mutex);  // release lock after freeing memory
}
```

This code assumes you are handling synchronous logging, and it does not include a logging function or an external service integration. Please adapt this to your own needs and infrastructure. Also note that error checking/handling has been skipped for brevity. It is very important to handle errors properly in production-grade code.
"]

