['Here is a basic implementation in C using zlib for GZIP compression.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

#define CHUNK 4096

typedef struct {
    char* buffer;
    size_t bufferSize;
} CompressedBuffer;

CompressedBuffer decompressFile(FILE *source, int format) {
    int ret;
    z_stream strm;
    unsigned char in[CHUNK];
    unsigned char out[CHUNK];

    CompressedBuffer result = {NULL, 0};

    /* allocate inflate state */
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;
    ret = inflateInit2(&strm, format);

    if (ret != Z_OK) {
        printf("Error initializing decompression: %d\n", ret);
        return result;
    }

    do {
        strm.avail_in = fread(in, 1, CHUNK, source);

        if (ferror(source)) {
            inflateEnd(&strm);
            printf("Error reading input file.\n");
            return result;
        }

        /* decompress data */
        strm.next_in = in;
        do {
            strm.avail_out = CHUNK;
            strm.next_out = out;

            ret = inflate(&strm, Z_NO_FLUSH);
            if (ret != Z_OK && ret != Z_STREAM_END) {
                printf("Error decompressing data: %d\n", ret);
                return result;
            }

            /* update the output buffer */
            size_t have = CHUNK - strm.avail_out;
            char* newBuffer = realloc(result.buffer, result.bufferSize + have);

            if (newBuffer == NULL) {
                printf("Error allocating memory.\n");
                return result;
            }

            result.buffer = newBuffer;
            memcpy(result.buffer + result.bufferSize, out, have);
            result.bufferSize += have;
        } while (strm.avail_out == 0);
    } while (!feof(source));

    inflateEnd(&strm);

    return result;
}
```
This example doesn't include all the requested features, but it can serve as a starting point for building a more comprehensive function. The code includes error handling and memory management strategies to optimize performance and resource utilization. However, for large scale applications you might want to consider using a library like `libarchive` which supports many different file formats and compression methods.
']

