Also keep in mind that you would need external libraries for configuring and logging. It might also be beneficial to have a design review with someone experienced in these matters or using established industry practices. This code is meant to provide a starting point and may require further work before it meets all the specified requirements.

```C
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int version;
    long sequenceNumber;
    time_t timestamp;
    size_t payloadLength;
} PacketHeader;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // For thread safety
static PacketHeader *headerArray = NULL;
static int M = 0;
static long lastSequenceNumber = 0;  // For sequence number checking
static time_t lastTimestamp = 0;  // For timestamp checking

int managePackets(int protocolVersion, size_t payloadLength) {
    if (payloadLength <= 0 || protocolVersion < 1) return -1;

    pthread_mutex_lock(&lock);

    // Handle the case when headerArray is full
    if (M > 0 && M == sizeof(headerArray)/sizeof(PacketHeader)) {
        pthread_mutex_unlock(&lock);
        return -1;  // The array is full, no more entries can be added.
    }

    PacketHeader header = { .version = protocolVersion,
                           .payloadLength = payloadLength };

    time_t currentTime = time(NULL);
    if (currentTime < lastTimestamp) {  // If timestamp is decreasing
        pthread_mutex_unlock(&lock);
        return -1;  // Handle error, maybe using logging library here
    } else {
        header.timestamp = currentTime;
        lastTimestamp = currentTime;
    }

    if (M > 0) {
        ++lastSequenceNumber;
    } else {
        lastSequenceNumber = 1;  // Start sequence numbers from one
    }
    header.sequenceNumber = lastSequenceNumber;

    // Add a new entry in the array
    PacketHeader *tmp = realloc(headerArray, (M+1) * sizeof(PacketHeader));
    if (!tmp) {
        pthread_mutex_unlock(&lock);
        return -1;  // Reallocation failed. Handle error here.
    } else {
        headerArray = tmp;
    }

    headerArray[M++] = header;
    pthread_mutex_unlock(&lock);

    return M-1;  // Return index of the newly added packet in array
}
```

This implementation is a starting point. It doesn't handle memory deallocation, logging configuration and reading from config system, or timestamp/sequence validation frequency adjustments. Also it's not thread safe for every possible scenario (race conditions, deadlocks etc.), you would need to add more checks based on the exact usage scenarios of this function.
