int compare(const void *a, const void *b) {
    DNSRecord *recordA = (DNSRecord *)a;
    DNSRecord *recordB = (DNSRecord *)b;
    return (recordA->id - recordB->id);
}

void resolveAndManageDNSRecords(char* hostname) {
    if (!hostname || strlen(hostname) == 0) {
        printf("Error: Invalid hostname.\n");
        return;
    }

    struct addrinfo hints, *result, *rp;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = 0;
    hints.ai_protocol = 0;

    int s = getaddrinfo(hostname, NULL, &hints, &result);
    if (s != 0) {
        printf("Error: Failed to resolve DNS.\n");
        return;
    }

    pthread_mutex_lock(&records.lock);

    for (rp = result; rp != NULL; rp = rp->ai_next) {
        char ip[INET6_ADDRSTRLEN];

        if (inet_ntop(rp->ai_family, &((struct sockaddr_in*)rp->ai_addr)->sin_addr, ip, sizeof(ip)) == NULL) {
            printf("Error: Failed to convert IP address.\n");
            continue;
        }

        DNSRecord* record = malloc(sizeof(DNSRecord));
        if (!record) {
            printf("Error: Failed to allocate memory for DNS record.\n");
            return;
        }

        record->ip = strdup(ip);
        // unique id derived from hostname
        record->id = hash_function(hostname);

        if (records.count == records.size) {
            int newSize = records.size ? records.size * 2 : 4;
            DNSRecord** newRecords = realloc(records.records, newSize * sizeof(DNSRecord*));
            if (!newRecords) {
                printf("Error: Failed to allocate memory for DNS records array.\n");
                free(record->ip);
                free(record);
                return;
            }

            records.records = newRecords;
            records.size = newSize;
        }

        records.records[records.count++] = record;
    }

    qsort(records.records, records.count, sizeof(DNSRecord*), compare);
    pthread_mutex_unlock(&records.lock);
}
```

This example uses `getaddrinfo` for DNS resolution and `qsort` to sort the DNS records based on their unique identifiers. It's assumed that there is a function `hash_function` that generates a unique identifier from a hostname, this function is not included in the example. The code also includes error handling and logging where necessary, but these are omitted for brevity.
