typedef struct DataPipelineManager DPM;

DPM* initDataPipelineManager(size_t offset_capacity, size_t key_capacity) {
    DPM *manager = malloc(sizeof(DPM));
    if (manager == NULL) return NULL;

    manager->offsets = calloc(offset_capacity, sizeof(long));
    manager->keys = calloc(key_capacity, sizeof(int));
    manager->tracking_array = calloc(key_capacity, sizeof(int));
    manager->records = calloc(key_capacity, sizeof(Record*)); // allocate space for pointers only

