        freeDataPipelineManager(manager);
        return NULL;
    }

    manager->offset_capacity = offset_capacity;
    manager->key_capacity = key_capacity;
    manager->record_capacity = 0; // will allocate when needed

    return manager;
}

void freeDataPipelineManager(DPM *manager) {
    if (manager == NULL) return;

    for (size_t i = 0; i < manager->key_capacity; ++i) {
        free(manager->records[i]); // free each record separately
    }

    free(manager->offsets);
    free(manager->keys);
    free(manager->tracking_array);
    free(manager->records);
