    if (manager->record_capacity >= manager->key_capacity) {
        size_t newCapacity = 2 * manager->key_capacity; // double the capacity when needed

        int* newKeys = realloc(manager->keys, newCapacity * sizeof(int));
        Record** newRecords = realloc(manager->records, newCapacity * sizeof(Record*));
        int* newTrackingArray = realloc(manager->tracking_array, newCapacity * sizeof(int));

        if (newKeys == NULL || newRecords == NULL || newTrackingArray == NULL) return -1; // handle error: allocation failure

        manager->keys = newKeys;
        manager->records = newRecords;
        manager->tracking_array = newTrackingArray;
        manager->key_capacity = newCapacity;
    }

    for (size_t i = 0; i < manager->key_capacity; ++i) {
