DynamicArray createArray(size_t capacity) {
    DynamicArray array = {PTHREAD_MUTEX_INITIALIZER, NULL, 0, 0};
    if (capacity > 0) {
        array.headers = malloc(sizeof(PacketHeader)*capacity);
        if (!array.headers) {
            exit(-1); // Out of memory...
        }
        array.capacity = capacity;
    }
    return array;
}

void freeArray(DynamicArray* array) {
    pthread_mutex_destroy(&array->lock);
    free(array->headers);
}

void addHeaderToArray(DynamicArray* array, PacketHeader header) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        if (newCapacity < 10) { // Minimum capacity
            newCapacity = 10;
        }
        PacketHeader* temp = realloc(array->headers, sizeof(PacketHeader)*newCapacity);
        if (!temp) {
            pthread_mutex_unlock(&array->lock);
            exit(-1); // Out of memory...
        }

        array->capacity = newCapacity;
        array->headers = temp;
    }

    array->headers[array->count++] = header;
    pthread_mutex_unlock(&array->lock);
}
