} SensorData;

SensorData** sensor_data;
int max_capacity = 100; // initial capacity of the array
int current_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Helper function to find an existing SensorData structure by identifier, or NULL if it doesn't exist.
SensorData* find(char *identifier) {
    for (int i = 0; i < current_size; ++i) {
        if (!strcmp(sensor_data[i]->identifier, identifier))
            return sensor_data[i];
    }
    return NULL;
}

// Helper function to dynamically resize the array.
void resize() {
    max_capacity *= 2; // double the capacity each time we need to resize
    SensorData** new_array = realloc(sensor_data, sizeof(SensorData*) * max_capacity);

    if (new_array == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    sensor_data = new_array;
}

// Function to add a new reading for a device.
void addReading(char *identifier, float temperature, float humidity, float pressure) {
    pthread_mutex_lock(&mutex); // lock the mutex before modifying data structures

    SensorData* existing = find(identifier);

    if (existing != NULL) {
        if (existing->count >= max_capacity) {
            printf("Maximum capacity reached for device: %s\n", identifier);
        } else {
            int i = existing->count++; // increment the count before adding new readings

            existing->temperature[i] = temperature;
            existing->humidity[i] = humidity;
            existing->pressure[i] = pressure;
        }
    } else {
        if (current_size >= max_capacity)
            resize(); // double the capacity of the array when we reach it

        SensorData* new_data = malloc(sizeof(SensorData));
        new_data->count = 1;
        strcpy(new_data->identifier, identifier);

        new_data->temperature = calloc(max_capacity, sizeof(float)); // allocate memory for temperature readings
        new_data->humidity = calloc(max_capacity, sizeof(float)); // allocate memory for humidity readings
        new_data->pressure = calloc(max_capacity, sizeof(float)); // allocate memory for pressure readings

        new_data->temperature[0] = temperature;
        new_data->humidity[0] = humidity;
        new_data->pressure[0] = pressure;

        sensor_data[current_size++] = new_data; // add the new SensorData to our array
    }

    pthread_mutex_unlock(&mutex); // unlock the mutex after we're done modifying data structures
}

// Function to get the average humidity and pressure for a device.
void getAverage(char *identifier, float* avg_humidity, float* avg_pressure) {
    pthread_mutex_lock(&mutex); // lock the mutex before reading data structures

    SensorData* existing = find(identifier);

    if (existing != NULL && existing->count > 0) {
        float total_humidity = 0;
        float total_pressure = 0;

        for (int i = 0; i < existing->count; ++i) {
            total_humidity += existing->humidity[i];
            total_pressure += existing->pressure[i];
        }

        *avg_humidity = total_humidity / existing->count;
        *avg_pressure = total_pressure / existing->count;
    } else {
        printf("No data available for device: %s\n", identifier);
    }

    pthread_mutex_unlock(&mutex); // unlock the mutex after we're done reading data structures
}

// Function to safely deallocate all allocated memory.
void cleanup() {
    pthread_mutex_lock(&mutex); // lock the mutex before modifying data structures

    for (int i = 0; i < current_size; ++i) {
        free(sensor_data[i]->temperature);
        free(sensor_data[i]->humidity);
        free(sensor_data[i]->pressure);

        free(sensor_data[i]); // free each SensorData structure
    }

    free(sensor_data); // finally, free the array itself

    pthread_mutex_unlock(&mutex); // unlock the mutex after we're done modifying data structures
}
