typedef struct {
    int value;
    int* key;
    long* offset;
} Record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int generateRandomUniqueKey(long *keys, int numKeysGenerated, long max) {
    long newKey;
    do {
        newKey = rand() % max + 1;  // Assuming keys are within [1,max]
    } while (bsearch(&newKey, keys, numKeysGenerated, sizeof(long), cmpfunc));

    return newKey;
}

int allocate_memory(Record **records, long **offsets, int** keys, 
                    size_t records_len, size_t offsets_len, size_t keys_len) {

    pthread_mutex_lock(&lock);

    srand((unsigned int) time(NULL));  
    *records = malloc(sizeof(Record) * records_len);
    if (*records == NULL) goto error;

    *offsets = malloc(sizeof(long) * offsets_len);
    if (*offsets == NULL) goto error;

    *keys = malloc(sizeof(int) * keys_len);
    if (*keys == NULL) goto error;

    for (size_t i = 0; i < records_len; ++i) {
        (*records)[i].value = rand();  // Assuming int values
        (*records)[i].key   = &(*keys)[rand() % keys_len];  // Randomly assigned key
        (*records)[i].offset= &(*offsets)[rand() % offsets_len];  // Randomly assigned offset
    }

    for (size_t i = 0; i < offsets_len; ++i) {
        (*offsets)[i] = rand();  // Assuming long offsets
    }

    for (size_t i = 0; i < keys_len; ++i) {
        if(i == 0) (*keys)[i] = generateRandomUniqueKey(*keys, i+1, LONG_MAX);
        else (*keys)[i] = generateRandomUniqueKey(*keys, i+1, LONG_MAX);
    }

    pthread_mutex_unlock(&lock);
    return 0;  

error:
