['Here is an implementation using Jansson library in C:

```C
#include <jansson.h>

// Predefined eviction policies 
const char* policies[] = {"LRU", "FIFOF", "LFU"};

bool validate_json(char* filename) {
    json_t *root, *size_field, *expiration_field, *policy_field;
    json_error_t error;

    root = json_load_file(filename, 0, &error);

    if(!root) {
        fprintf(stderr, "Error loading file: %s\n", error.text);
        return false;
    }

    // Checking for necessary fields
    size_field = json_object_get(root, "cache_size");
    expiration_field = json_object_get(root, "expiration_time");

    if(!json_is_integer(size_field) || !json_is_integer(expiration_field)) {
        fprintf(stderr, "Invalid or missing field: cache size or expiration time\n");
        json_decref(root);
        return false;
    }

    // Checking if cache size is within limits
    int64_t size = json_integer_value(size_field);
    struct rlimit limit;
    getrlimit(RLIMIT_DATA, &limit);  // Can be changed to other limits depending on use case

    if (size > limit.rlim_max) {
        fprintf(stderr, "Cache size exceeds system resource limits\n");
        json_decref(root);
        return false;
    }

    // Checking if expiration time is non-positive
    int64_t expiration = json_integer_value(expiration_field);
    if (expiration <= 0) {
        fprintf(stderr, "Expiration time must be a positive integer\n");
        json_decref(root);
        return false;
    }

    // Checking optional eviction policy field
    policy_field = json_object_get(root, "eviction_policy");

    if (policy_field && json_is_string(policy_field)) {
        const char* policy = json_string_value(policy_field);
        bool valid_policy = false;

        for (int i = 0; i < 3; ++i) { // assuming there are only 3 predefined policies
            if (strcmp(policy, policies[i]) == 0) {
                valid_policy = true;
                break;
            }
        }

        if (!valid_policy) {
            fprintf(stderr, "Invalid eviction policy\n");
            json_decref(root);
            return false;
        }
    }

    json_decref(root);
    return true;
}
```

