#include <unistd.h>

typedef struct {
    double d;
    char* s;
    size_t len;
} Record;

// Global Variables
Record **records;
long *offsets;
int *keys;
double *numbers;
char **strings;
size_t recordCount, offsetCount, keyCount, numberCount, stringCount;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

// Memory Management Functions
void allocateMemory() {
    records = malloc(1024 * sizeof(Record*)); // Allocating 1024 Record pointers.
    offsets = malloc(sizeof(long) * recordCount);
    keys = malloc(sizeof(int) * keyCount);
    numbers = malloc(sizeof(double) * numberCount);
    strings = malloc(sizeof(char*) * stringCount);
}

void freeMemory() {
    pthread_mutex_lock(&lock); // Locking the mutex for safe memory free.

    for (int i = 0; i < recordCount; ++i) {
        free(records[i]->s);
        free(records[i]);
    }

    free(strings);
    free(numbers);
    free(keys);
    free(offsets);
    free(records);

    pthread_mutex_unlock(&lock); // Unlocking the mutex.
}

// Data Handling Functions
void processData(Record *record, long offset, int key, double number, char* string) {
    pthread_mutex_lock(&lock); // Lock to ensure exclusive access.

    records[recordCount++] = record;
    offsets[offsetCount++] = offset;
    keys[keyCount++] = key;
    numbers[numberCount++] = number;
    strings[stringCount++] = string;

    pthread_mutex_unlock(&lock); // Unlock to allow other threads.
}

// Error Handling Functions
void handleError(char *errMsg) {
    fprintf(stderr, "%s\n", errMsg);
    exit(EXIT_FAILURE);
}

int main() {
