#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int value;
    unsigned char status;
    double timestamp;
} record_t;

typedef struct {
    size_t max_offsets;
    long *offsets;

    size_t max_keys;
    int *keys;

    size_t max_tracking;
    int *tracking;

    size_t max_records;
    record_t **records;

    pthread_mutex_t lock;
} context_t;

context_t* create_context(size_t max_offsets, size_t max_keys, size_t max_tracking, size_t max_records) {
    context_t *ctx = malloc(sizeof(context_t));

    if (ctx == NULL) return NULL;

    ctx->offsets = calloc(max_offsets, sizeof(long));
    ctx->keys = calloc(max_keys, sizeof(int));
    ctx->tracking = calloc(max_tracking, sizeof(int));
    ctx->records = calloc(max_records, sizeof(record_t*));

    if (ctx->offsets == NULL || ctx->keys == NULL || ctx->tracking == NULL || ctx->records == NULL) {
        destroy_context(ctx);
        return NULL;
    }

    ctx->max_offsets = max_offsets;
    ctx->max_keys = max_keys;
    ctx->max_tracking = max_tracking;
    ctx->max_records = max_records;

    pthread_mutex_init(&ctx->lock, NULL);

    return ctx;
}

void destroy_context(context_t *ctx) {
    if (ctx == NULL) return;

    for (size_t i = 0; i < ctx->max_records; ++i) {
        free(ctx->records[i]);
    }

    pthread_mutex_destroy(&ctx->lock);
    free(ctx->offsets);
    free(ctx->keys);
    free(ctx->tracking);
    free(ctx->records);
}

void add_record(context_t *ctx, int key, record_t *record) {
    pthread_mutex_lock(&ctx->lock);

    for (size_t i = 0; i < ctx->max_keys; ++i) {
        if (key == ctx->keys[i]) {
            free(ctx->records[i]);
            ctx->records[i] = record;
            ++ctx->tracking[i];
            pthread_mutex_unlock(&ctx->lock);
            return;
        }
    }

    for (size_t i = 0; i < ctx->max_keys; ++i) {
        if (ctx->keys[i] == 0) {
            ctx->keys[i] = key;
            ctx->records[i] = record;
            ++ctx->tracking[i];
            pthread_mutex_unlock(&ctx->lock);
            return;
        }
    }

    free(record);
    pthread_mutex_unlock(&ctx->lock);
}
```
This is a simple example, and it has several important drawbacks, such as lack of bounds checking on input arrays. In an actual implementation, you should consider using data structures from the C++ Standard Template Library (STL) that provide automatic memory management and other utilities to help manage resources in complex scenarios.
