#include <stdlib.h>
#include <pthread.h>

// Define the data structures
typedef struct MAC_HEADER { /* ... */ } MAC_HEADER;
typedef enum MAC_PDU_TYPE { /* ... */ } MAC_PDU_TYPE;

typedef struct MAC_PDU {
    MAC_HEADER header;
    MAC_PDU_TYPE type;
    uint32_t sequenceNumber;
    uint8_t* payload;
} MAC_PDU;

// Define the list structure and a mutex to manage concurrent access
typedef struct MAC_PDU_List {
    pthread_mutex_t lock;
    MAC_PDU** list; // array of pointers for flexibility and easier reallocation
    size_t size; 
    size_t capacity; 
} MAC_PDU_List;

// Function to initialize the list
void mac_pdu_list_init(MAC_PDU_List* lst) {
    pthread_mutex_init(&lst->lock, NULL);
    lst->size = 0;
    lst->capacity = 10000;  // start with a reasonable initial capacity
    lst->list = malloc(sizeof(MAC_PDU*) * lst->capacity);
}

// Function to add an element in the list, thread-safe
void mac_pdu_list_add(MAC_PDU_List* lst, MAC_PDU* pdu) {
    pthread_mutex_lock(&lst->lock);

    // If size reaches capacity, reallocate with a larger block of memory
    if (lst->size == lst->capacity) {
        lst->capacity *= 2;  // exponential growth for amortized O(1) insertions
        MAC_PDU** newList = realloc(lst->list, sizeof(MAC_PDU*) * lst->capacity);

        if (newList == NULL) {
            // handle error: memory allocation failed
        } else {
            lst->list = newList;
        }
    }

    // Add the PDU to the list
    lst->list[lst->size] = pdu; 
    lst->size++;

    pthread_mutex_unlock(&lst->lock);
}

// Function to iterate over the elements in the list, thread-safe
void mac_pdu_list_iterate(MAC_PDU_List* lst, void (*func)(MAC_PDU*, size_t)) {
    pthread_mutex_lock(&lst->lock);

    for (size_t i = 0; i < lst->size; ++i) {
        func(lst->list[i], i);
    }

    pthread_mutex_unlock(&lst->lock);
}
```
