// Mersenne Twister Random Number Generator wrapped in a class
class RNG {
private:
    std::mt19937 generator;
    static std::mutex rngMutex; // for thread-safety of the random number generation
public:
    RNG() : generator(std::chrono::system_clock::now().time_since_epoch().count()) {}
    ~RNG() = default;

    int getRandomValueInRange(int min, int max) {
        std::lock_guard<std::mutex> lock(rngMutex); // thread-safe access to the generator
        std::uniform_int_distribution<> distribution(min, max);
        return distribution(generator);
    }
};

// Ascending Order Sorting Algorithm for Records
void sortRecordsAscending(std::vector<Record>& records) {
    std::sort(records.begin(), records.end(), [](const Record &a, const Record &b){
        return a.value < b.value;
    });
}

