} NFAPI_CRC_INDICATION_PDU_T;

int* generateUniqueRandomNumbers(int size, int min, int max) {
    if (max - min + 1 < size) {
        // It's impossible to generate unique numbers in this range. 
        return NULL;
    }

    int* array = malloc(size * sizeof(int));
    if (!array) {
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        array[i] = min + rand() % (max - min + 1);

        // Ensure uniqueness by checking with previously generated numbers. 
        for (int j = 0; j < i; ++j) {
            if (array[j] == array[i]) {
                --i;
                break;
            }
        }
    }

    return array;
}

NFAPI_CRC_INDICATION_PDU_T** createList(int size, int minRnti, int maxRnti) {
    srand((unsigned int)time(NULL));

    NFAPI_CRC_INDICATION_PDU_T** list = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) {
        return NULL;
    }

    int* uniqueRnti = generateUniqueRandomNumbers(size, minRnti, maxRnti);
    if (!uniqueRnti) {
        free(list);
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list[i]) {
            // Free all previously allocated memory and return NULL. 
            for (int j = 0; j < i; ++j) {
                free(list[j]);
            }
            free(uniqueRnti);
            free(list);
            return NULL;
        }

        list[i]->RX_UE_INFORMATION_TAG = uniqueRnti[i];
    }

    free(uniqueRnti);
    return list;
}

void destroyList(NFAPI_CRC_INDICATION_PDU_T** list, int size) {
    for (int i = 0; i < size; ++i) {
        free(list[i]);
    }

    free(list);
}
