    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE *logFile;  // Define and initialize this in your main function.

void logError(const char *msg) {
    fprintf(logFile, "ERROR: %s\n", msg);
}

NFAPI_CRC_INDICATION_PDU_T *createAndPopulateList(int N) {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *tail = NULL;

    for (int i = 0; i < N; ++i) {
        // Dynamically allocate memory.
        NFAPI_CRC_INDICATION_PDU_T *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (newNode == NULL) {  // Check for out of memory condition.
            logError("Out of memory.");
            break;
        }

        // Populate the node with random data.
        newNode->rx_ue_info_tag.RNTI = rand();
        newNode->crc_indication_rel8_tag.CRCFLAG = rand() % 2;

        pthread_mutex_lock(&lock); // Thread-safe append operations to the list.

        if (head == NULL) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }

        pthread_mutex_unlock(&lock);
    }

    return head;
}

void clearList(NFAPI_CRC_INDICATION_PDU_T *head) {
    while (head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = head->next;

        pthread_mutex_lock(&lock);  // Ensure thread safety.

        free(head);  // Clear the memory.
        head = temp;

        pthread_mutex_unlock(&lock);
