            printf("Memory allocation failed\n");
            exit(1);
        }
        projects[i]->startDate = time(NULL);
        projects[i]->status = TODO;
        projects[i]->updates= malloc(sizeof(struct ProgressUpdate*));
        if(!projects[i]->updates) {
            printf("Memory allocation failed\n");
            exit(1);
        }
        projects[i]->numUpdates = 0;
    }
    return projects;
}

