        fgets(projects[i]->name, 256, stdin);
        if(strlen(projects[i]->name) > 254){
            printf("Name length exceeded. Max limit is 256 characters.\n");
            exit(1);
        }
    }
}

//Function to add progress updates
void addProgressUpdate(Project* project, char* update){
    struct ProgressUpdate* new_update = malloc(sizeof(struct ProgressUpdate));
    if(!new_update) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    new_update->timestamp = time(NULL);
    new_update->update=malloc((strlen(update)+1)*sizeof(char));
    if(!new_update->update) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    strcpy(new_update->update, update);

    project->updates[project->numUpdates++] = new_update;
    //Reallocate memory for updates array when it is full
    if((project->numUpdates % 10)==0){
        project->updates=realloc(project->updates, (project->numUpdates+10)*sizeof(struct ProgressUpdate*));
