#include <stdlib.h>
#include <pthread.h>
#include <errno.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Your structure definition here...
} NFAPI_CRC_INDICATION_PDU;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU *data;
    struct Node *next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node *head = NULL;
int maxSize = 0; // Maximum size of the list. Set according to your needs.
FILE* logFile = NULL; // File for logging errors and performance metrics.

void insert(NFAPI_CRC_INDICATION_PDU *data) {
    Node *newNode = (Node*) malloc(sizeof(Node));
    if(!newNode) {
        fprintf(logFile, "Memory allocation failed: %s\n", strerror(errno));
        return;
    }

    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&lock); // Acquire the lock before modifying the list.

    if(!head) {
        head = newNode;
    } else {
        Node *current = head;
        while(current->next) {
            current = current->next;
        }

        // Check for maximum size limit before inserting.
        if (maxSize > 0 && listLength() >= maxSize) {
            fprintf(logFile, "Maximum size reached\n");
            free(newNode);
            pthread_mutex_unlock(&lock);
            return;
        }

        current->next = newNode;
    }

    pthread_mutex_unlock(&lock); // Release the lock after modifying the list.
}

int listLength() {
    int length = 0;
    Node *current;

    for(current = head; current != NULL; current = current->next) {
        length++;
    }

    return length;
}
```

This example code includes a linked list approach where new elements are appended to the end of the list. It's thread-safe with proper locking mechanism applied before modifying the linked list and releasing the lock after modification. It also checks for out-of-memory conditions by verifying if malloc succeeded or not, and logs any errors directly into a specified file.
