```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

// Structure definition for ConnectionState node
typedef struct ConnectionState {
    int sessionId;
    time_t lastActiveTime;
    char* connectionState;
    char* remoteIpAddress;
    char* localIpAddress;
    int portNumber;
    struct ConnectionState* next;
} ConnectionState;

// Structure definition for the linked list
typedef struct LinkedList {
    pthread_mutex_t mutex; // To ensure thread safety
    ConnectionState* head;
    ConnectionState* tail;
} LinkedList;

LinkedList* createList() {
    LinkedList* list = malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;

    if (pthread_mutex_init(&list->mutex, NULL) != 0) {
        perror("Failed to initialize mutex");
        return NULL;
    }

    return list;
}

void insertNode(LinkedList* list, ConnectionState* node) {
    pthread_mutex_lock(&list->mutex); // Lock the mutex before accessing the list

    if (node == NULL || node->sessionId <= 0 || 
        strcmp(node->remoteIpAddress, "") == 0 || 
        strcmp(node->localIpAddress, "") == 0) {
        perror("Invalid Node");
        return;
    }

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }

    pthread_mutex_unlock(&list->mutex); // Unlock the mutex after modifying the list
}

void updateState(LinkedList* list, int sessionId, char* newState) {
    pthread_mutex_lock(&list->mutex); 

    ConnectionState* currentNode = list->head;
    while (currentNode != NULL) {
        if (currentNode->sessionId == sessionId) {
            free(currentNode->connectionState); // Free previous state before allocating new one
            currentNode->connectionState = malloc((strlen(newState) + 1) * sizeof(char)); 
            strcpy(currentNode->connectionState, newState);
        }

        currentNode = currentNode->next;
    }

    pthread_mutex_unlock(&list->mutex); 
}
```
This is a very basic structure that includes initializing the linked list and inserting nodes. It also shows how to update node state while ensuring thread safety with a mutex lock. 

