    private Dictionary<string, string> cache = new Dictionary<string, string>();

    public async Task UpdateHtmlContent(string url, string selector, string content) {
        try {
            var response = await client.GetAsync(url);
            var htmlString = await response.Content.ReadAsStringAsync();

            if (cache.ContainsKey(htmlString))  // Check cache
                htmlString = cache[htmlString];
            else {
                var doc = new HtmlDocument();
                doc.LoadHtml(htmlString);

                var element = doc.DocumentNode.SelectSingleNode(selector);
                if (element != null)
                    element.InnerHtml = content;  // Update HTML content

                htmlString = doc.DocumentNode.OuterHtml;
                cache[url] = htmlString;  // Add to cache
            }
        } catch (HttpRequestException ex) {
            Console.WriteLine($"Error: {ex.Message}");
            throw new Exception("Network error, using cached content instead", ex);
        }
    }
}
```
