typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

#define MAX_STRUCTURES 1024 // system-defined max value
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T *allocateStructures(int N) {
    if (N <= 0 || N > MAX_STRUCTURES) {
        return NULL; // invalid input, return immediately
    }

    pthread_mutex_lock(&lock); 
    NFAPI_CRC_INDICATION_PDU_T *array = calloc(N, sizeof(*array));
    if (array == NULL) {
        pthread_mutex_unlock(&lock);
        return NULL; // memory allocation failed
    }

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = i; // initialize each structure as needed
        array[i].RNTI = i * 10;

        CRC_INDICATION_REL8_TAG *tag = malloc(sizeof(*tag));
        if (tag == NULL) {
            for (int j = 0; j < i; j++) { // clean up previously allocated structures
                free(((NFAPI_CRC_INDICATION_PDU_T*)array[j]).CRC_INDICATION_REL8_TAG);
            }

            pthread_mutex_unlock(&lock);
            free(array); // clean up array allocation
            return NULL; // memory allocation failed for tag, return immediately
        }

        tag->CRCFLAG = rand() % 2; // set randomly
        array[i].CRC_INDICATION_REL8_TAG = tag;
    }

    pthread_mutex_unlock(&lock);
    return array;
}

void deallocateStructures(NFAPI_CRC_INDICATION_PDU_T *array, int N) {
    if (array == NULL || N <= 0 || N > MAX_STRUCTURES) {
        return; // invalid input, return immediately
    }

    pthread_mutex_lock(&lock); 
    for (int i = 0; i < N; i++) {
        free(array[i].CRC_INDICATION_REL8_TAG);
    }

    free(array); // deallocate array after all structures have been deallocated
    pthread_mutex_unlock(&lock);
}
