   MD5((unsigned char*)&imageInfo, sizeof(imageInfo), md5);  // compute the hash of the image info

   TIFFClose(tif);

   ImageInfo* result = malloc(sizeof(ImageInfo));
   *result = imageInfo;

   pthread_exit((void*)result);  // return the pointer to dynamically allocated memory
}

int main() {
   const int num_files = 10;  // number of files you want to process
   char* filenames[num_files];  // array of file names. Initialize it beforehand

   pthread_t threads[num_files];
   for (int i = 0; i < num_files; ++i) {
