       if(ret != 0) {
           printf("Failed to create thread %d\n", i);
           return 1;
       }
   }

   // join the threads after they've all been created and retrieve the results
   ImageInfo* imageInfos[num_files];
   for (int i = 0; i < num_files; ++i) {
       void* result = NULL;
       pthread_join(threads[i], &result);

       if(!result) {
