['Below is a basic implementation of what you're asking for. Please note that this example doesn't include all features mentioned like custom logging, flexible random number generator or periodically compressing memory pool but it gives an idea on how to manage dynamic collection of records in memory efficiently.
```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
} Record;

Record* initialize_records(int size, int range) {
    srand(time(NULL));  // seed the random number generator

    Record *records = malloc(sizeof(Record) * size);
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }

    int prevKey = 0; // for checking the uniqueness of key values
    for (int i=0; i<size; i++) {
        records[i].key = rand() % range + 1;  // generating a random number within given range

        // ensuring no two consecutive keys are identical
        while(records[i].key == prevKey){
            records[i].key = rand() % range + 1;
        }
        prevKey = records[i].key;

        records[i].offset = 0L; // initialize offset to 0
    }

    return records;
}

void print_records(Record* records, int size) {
    for (int i=0; i<size; i++) {
        printf("key: %d, offset: %ld\n", records[i].key, records[i].offset);
    }
}

int main() {
    const int SIZE = 10;
    const int RANGE = 20;  // random number range will be between 1 and RANGE inclusive

    Record* records = initialize_records(SIZE, RANGE);

    print_records(records, SIZE);

    free(records);

    return 0;
}
```
This code initializes an array of struct `Record`. Each record's `key` is set to a random number within the given range and is guaranteed to be unique from its predecessor. The memory pool is allocated once with sufficient space for all records, thus minimizing reallocations over time. If allocation fails, the program will terminate gracefully with an error message.
']

