typedef struct {
    int protocol_version;
    int sequence_number;
    long timestamp;
    size_t payload_length;
    unsigned flags;
} PacketHeader;

// Define a global structure to hold packet headers and related data.
struct packet_data {
    PacketHeader *packets;
    size_t count;
    int most_recent;
};

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the array and populate it with M entries.
struct packet_data *initialize(size_t M) {
    struct packet_data *data = malloc(sizeof(struct packet_data));
    if (data == NULL) return NULL;

    data->packets = calloc(M, sizeof(PacketHeader));
    if (data->packets == NULL) {
        free(data);
        return NULL;
    }
    data->count = 0;
    data->most_recent = -1;

    return data;
}

// Function to add a packet to the array.
int add_packet(struct packet_data *data, PacketHeader header) {
    pthread_mutex_lock(&lock);

    if (data->count == M) {
        // Handle case where the array is full
        return -1;  // or resize the array
    }

    for(int i = 0; i < data->count; ++i){
        if(data->packets[i].sequence_number == header.sequence_number && data->packets[i].payload_length != header.payload_length) {
            // Handle case where the sequence number is duplicate and payload lengths differ
            pthread_mutex_unlock(&lock);
            return -1;
        } else if(data->packets[i].sequence_number == header.sequence_number && data->packets[i].payload_length == header.payload_length){
            // Update the most recent packet index and unlock before returning
            data->most_recent = i;
            pthread_mutex_unlock(&lock);
            return 0;
        }
    }

    data->packets[data->count++] = header; // add the new packet

    // Update the most recent packet index and unlock before returning
    data->most_recent = data->count - 1;
    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to get the most recent valid packet.
PacketHeader *get_packet(struct packet_data *data) {
    if (data->most_recent == -1) {
        // No packets in the array or no valid packets found
        return NULL;
    }

    pthread_mutex_lock(&lock);
    PacketHeader *header = &(data->packets[data->most_recent]);
    pthread_mutex_unlock(&lock);

    return header;
}
```
The above code shows how you can initialize a dynamic array of packet headers, add packets to the array, and get the most recent valid packet. Error handling and additional functionalities are not included in this example. You would need to implement these based on your specific requirements. Also, the error checking is minimalistic for demonstration purposes, but should be enhanced for production code.
