private readonly ConcurrentDictionary<string, (DateTimeOffset Expiry, CustomDataStructure Data)> _cache = 
    new ConcurrentDictionary<string, (DateTimeOffset Expiry, CustomDataStructure Data)>();

public async Task<CustomDataStructure> GetFromCacheOrFileAsync(string path, TimeSpan maxAge)
{
    if (_cache.TryGetValue(path, out var cached))
    {
        if (cached.Expiry > DateTimeOffset.UtcNow)
            return cached.Data; // Cache hit

        _cache.TryRemove(path, out _); // Remove expired cache entry
    }

    // Cache miss: load from file and deserialize it
