typedef struct client {
    char *name;
    int sockfd;
    int status;
    time_t last_seen[];  // dynamically allocated array of timestamps
} Client;

// Dynamically allocate memory for a new client structure
Client* create_client(const char* name, size_t num_timestamps) {
    Client *new_client = malloc(sizeof(Client));
    if (new_client == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    new_client->name = strdup(name);  // Dynamically allocated name buffer
    if (new_client->name == NULL) {
        free(new_client);
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    new_client->last_seen = malloc(num_timestamps * sizeof(time_t));  // Allocating memory for timestamps array
    if (new_client->last_seen == NULL) {
        free(new_client->name);
        free(new_client);
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    new_client->status = 0;  // Set default status as disconnected
    return new_client;
}

// Add a timestamp for last seen activity
void update_last_seen(Client *client, time_t timestamp) {
    if (client == NULL || client->last_seen == NULL) {
        perror("Invalid client");
        exit(EXIT_FAILURE);
    }

    // Assuming we are storing the latest seen timestamps in last_seen array
    // and shifting older timestamps out to make room for new timestamp. 
    memmove(&client->last_seen[1], &client->last_seen[0], sizeof(time_t) * (sizeof(client->last_seen)/sizeof(time_t) - 1));
    client->last_seen[0] = timestamp;
}

// Frees all memory allocated for a given client.
void destroy_client(Client* client) {
    if (client == NULL) {
        return;
    }

    free(client->name);  // Free dynamically allocated name buffer
    free(client->last_seen); // Free dynamically allocated timestamp array
    free(client);  // Free client structure
}
```
