#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int data;
    char *str;
    struct Node *next;
} Node;

Node* create_node(int data, const char *str) {
    Node *new_node = malloc(sizeof(Node));

    new_node->data = data;
    new_node->str = malloc(strlen(str) + 1);
    strcpy(new_node->str, str);
    new_node->next = NULL;

    return new_node;
}

void insert_at_end(Node **head, int data, const char *str) {
    Node *current = *head;

    if (*head == NULL) {
        *head = create_node(data, str);
        return;
    }

    while (current->next != NULL) {
        current = current->next;
    }

    current->next = create_node(data, str);
}
```
