typedef struct NetworkServiceConfiguration {
    char* IPAddress;
    int portNumber;
    char* protocolType;
    char* serviceName;
    struct NetworkServiceConfiguration* next;
} NetworkServiceConfiguration;

NetworkServiceConfiguration *head = NULL;  // head of the list
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;   // mutex for thread safety

// Function to add a new configuration
void addConfig(char* IPAddress, int portNumber, char* protocolType, char* serviceName) {
    pthread_mutex_lock(&lock);  // locking the mutex

    NetworkServiceConfiguration *newNode = (NetworkServiceConfiguration*)malloc(sizeof(NetworkServiceConfiguration));
    newNode->IPAddress = strdup(IPAddress);
    newNode->portNumber = portNumber;
    newNode->protocolType = strdup(protocolType);
    newNode->serviceName = strdup(serviceName);
    newNode->next = head;  // adding at the beginning for O(1) add

    head = newNode;  // update the head of list

    pthread_mutex_unlock(&lock);  // unlocking the mutex
}

// Function to update a configuration based on IP address or port number
void updateConfig(char* IPAddress, int portNumber, char* protocolType) {
    pthread_mutex_lock(&lock);   // locking the mutex

    NetworkServiceConfiguration *temp = head;
    while (temp != NULL) {
        if ((strcmp(temp->IPAddress, IPAddress) == 0) || (temp->portNumber == portNumber)) {
            free(temp->protocolType);  // free old memory before updating

            temp->protocolType = strdup(protocolType);  // update protocol type
        }

        temp = temp->next;  
    }

    pthread_mutex_unlock(&lock);   // unlocking the mutex
}

// Function to retrieve a configuration based on IP address or port number
NetworkServiceConfiguration* getConfig(char* IPAddress, int portNumber) {
    pthread_mutex_lock(&lock);  // locking the mutex

    NetworkServiceConfiguration *temp = head;
    while (temp != NULL) {
        if ((strcmp(temp->IPAddress, IPAddress) == 0) || (temp->portNumber == portNumber)) {
            pthread_mutex_unlock(&lock);  // unlocking the mutex before returning node

            return temp;   // returning matched node
        }

        temp = temp->next; 
    }

    pthread_mutex_unlock(&lock);  // unlocking the mutex

    return NULL;  // if no match found, return NULL
}
```
