['The following C code provides a basic implementation of the required functionality. Please note that writing an entire communication framework would be beyond the scope of this task and require additional resources and expertise in many areas such as protocol design, thread synchronization, data serialization, and so on. 

```C
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct PacketHeader {
    uint8_t version;
    uint32_t sequenceNumber;
    time_t timestamp;
    size_t payloadLength;
} PacketHeader;

typedef struct DynamicArray {
    PacketHeader *array;
    size_t length;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* arrayInit(size_t initialCapacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->array = malloc(initialCapacity * sizeof(PacketHeader));
    if (!array->array) {
        free(array);
        return NULL;
    }

    array->length = 0;
    array->capacity = initialCapacity;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

int arrayAppend(DynamicArray *array, PacketHeader element) {
    pthread_mutex_lock(&array->lock);

    if (array->length >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        PacketHeader *newArray = realloc(array->array, newCapacity * sizeof(PacketHeader));

        // If reallocation failed.
        if (!newArray) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }

        array->capacity = newCapacity;
        array->array = newArray;
    }

    // Copy element data.
    array->array[array->length++] = element;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

PacketHeader* arrayGet(DynamicArray *array, size_t index) {
    pthread_mutex_lock(&array->lock);

    // If out of bounds.
    if (index >= array->length) {
        pthread_mutex_unlock(&array->lock);
        return NULL;
    }

    PacketHeader *element = &array->array[index];

    pthread_mutex_unlock(&array->lock);
    return element;
}
``` 

This is a basic implementation and may need to be adjusted according to the specific requirements of your project. For example, you would likely want to add error handling, more sophisticated memory management (e.g., deallocating unused memory after reducing capacity), better concurrency control (locks for each individual element rather than a global one), and other optimizations that are specific to your use case.
']

