void addEntry(long RNTI, RX_UE_INFORMATION_TAG* rx_ue_information_tag, L1_RRC_TAG* l1_rrc_tag) {
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) return; // Handle memory allocation failure

    NFAPI_L1_RX_INDICATION_PDU* newData = malloc(sizeof(NFAPI_L1_RX_INDICATION_PDU));
    if (newData == NULL) {
        free(newNode); // Handle memory allocation failure
        return;
    }

    newData->RNTI = RNTI;
    newData->timestamp = time(NULL); // Get current timestamp
    newData->rx_ue_information_tag = rx_ue_information_tag;
    newData->l1_rrc_tag = l1_rrc_tag;

    newNode->data = newData;
    newNode->next = head;
    head = newNode;
}

NFAPI_L1_RX_INDICATION_PDU* getEntryByRNTI(long RNTI) {
    Node* current = head;
    while (current != NULL) {
        if (current->data->RNTI == RNTI) return current->data;
        current = current->next;
    }

    // Not found
    return NULL; 
}

void updateEntryTimestamp(long RNTI, time_t newTimestamp) {
    Node* current = head;
    while (current != NULL) {
        if (current->data->RNTI == RNTI) {
            current->data->timestamp = newTimestamp;
            return;
        }
        current = current->next;
    }
}
```
This module uses a linked list to store the entries. The `addEntry` function adds a new entry at the head of the list, making it efficient for frequent addition but less efficient for random access or updates since RNTI lookup requires scanning through the entire list.

