public class DatabaseConnectionManager {
    private final AtomicInteger connectionCounter = new AtomicInteger(0);
    private final Map<String, Connection> connectionPool = new ConcurrentHashMap<>();

    private Configuration configuration;
    private MonitoringService monitoringService;
    private ScheduledExecutorService healthCheckerScheduler;

    public DatabaseConnectionManager(Configuration config, MonitoringService ms) {
        this.configuration = config;
        this.monitoringService = ms;

        // Initialize pool based on configuration
        for (int i = 0; i < configuration.getMaxConnections(); ++i) {
            Connection conn = createConnection();
            connectionPool.put(conn.getId(), conn);
        }

        // Start health check scheduler
        this.healthCheckerScheduler = Executors.newSingleThreadScheduledExecutor();
        this.healthCheckerScheduler.scheduleAtFixedRate(this::checkConnections, 0, configuration.getHealthCheckInterval(), TimeUnit.SECONDS);
    }

    public Connection getConnection() {
        // Dynamically scale pool size based on load and health checks
        if (connectionCounter.incrementAndGet() > configuration.getMaxConnections()) {
            scalePool();
        }

        for (Map.Entry<String, Connection> entry : connectionPool.entrySet()) {
            if (isConnectionHealthy(entry.getValue())) {
                return entry.getValue();
            }
        }

        // No healthy connections available, create new one and scale pool
        Connection conn = createConnection();
        connectionPool.put(conn.getId(), conn);
        scalePool();
    }

    private void checkConnections() {
        for (Map.Entry<String, Connection> entry : connectionPool.entrySet()) {
            if (!isConnectionHealthy(entry.getValue())) {
                // Replace unhealthy connections with fresh ones
                Connection conn = createConnection();
                connectionPool.put(conn.getId(), conn);

                monitoringService.logUnhealthyConnection(entry.getValue());
