#include <stdlib.h>
#include <time.h>
#define KEY_SET_SIZE 100
#define MAX_RANDOM_VALUE 1000

typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

int* generateRandomUniqueKeys(int size, int maxValue) {
    if (size > maxValue + 1) {
        return NULL;
    }

    srand(time(NULL));
    int* keys = calloc(maxValue + 1, sizeof(int));
    for (int i = 0; i < size; i++) {
        int keyIndex;
        do {
            keyIndex = rand() % maxValue;
        } while (keys[keyIndex] != 0);

        keys[keyIndex] = 1;
    }

    return keys;
}

Record* initializeRecords(long offsetSize, int keySize) {
    if (offsetSize <= 0 || keySize <= 0) {
        return NULL;
    }

    srand(time(NULL));
    Record* records = malloc(sizeof(Record) * offsetSize);
    if (records == NULL) {
        return NULL;
    }

    int* keys = generateRandomUniqueKeys(keySize, KEY_SET_SIZE);
    if (keys == NULL) {
        free(records);
        return NULL;
    }

    for (long i = 0; i < offsetSize; i++) {
        records[i].offset = rand() % MAX_RANDOM_VALUE;
        int j = 0;
        do {
            if(keys[j] == 1) {
                keys[j] = 2;  // mark as used
                records[i].key = j;
                break;
            }
            j++;
        } while (j < KEY_SET_SIZE);

        records[i].value = rand() % MAX_RANDOM_VALUE;
    }

    free(keys);
    return records;
}
