['The task described involves several complex components like managing dynamic memory for an unknown number of records, implementing a collision handling mechanism, efficient memory management, performance optimization and logging system design. Here is a skeleton code in C which can fulfill these requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct Record {
    int offset;
    int key;
    void* recordStructure;  // placeholder for a record structure
    size_t identifier;  // temporary data structure, generated from a hash function applied to the key
} Record;

typedef struct DataManager {
    Record* records;
    int numRecords;
    int bufferSize;
    int stepSize;
    int interval;
    int minValue;
    int maxValue;
} DataManager;

// Function to generate hash
size_t generateHash(const char *key) {
    size_t hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash;
}

// Function to reallocate memory
void resizeBuffer(DataManager* dataManager, int newSize) {
    if (newSize < dataManager->numRecords)
        return;

    Record* newRecords = realloc(dataManager->records, newSize * sizeof(Record));
    if (!newRecords) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
    }

    dataManager->bufferSize = newSize;
    dataManager->records = newRecords;
}

// Function to initialize record
void initializeRecord(DataManager* dataManager, int index) {
    Record* record = &dataManager->records[index];
    record->offset = index * dataManager->stepSize;
    record->key = index * dataManager->interval;

    // Generate a random number within the user-defined range for the value
    srand(time(NULL));
    size_t value = rand() % (dataManager->maxValue - dataManager->minValue + 1) + dataManager->minValue;

    char key[20];  // assuming keys are no longer than 20 characters
    sprintf(key, "%d", record->key);

    size_t identifier = generateHash(key);
    while (identifierExists(dataManager, identifier)) {
        resizeBuffer(dataManager, dataManager->bufferSize * 2); // handle collision by resizing the buffer
        identifier = generateHash(key);
    }

    record->identifier = identifier;
}

// Function to check if a hash already exists in records
int identifierExists(DataManager* dataManager, size_t identifier) {
    for (int i = 0; i < dataManager->numRecords; i++) {
        if (dataManager->records[i].identifier == identifier)
            return 1;
    }

    return 0;
}

// Function to initialize the records
DataManager* initDataManager(int numRecords, int stepSize, int interval, int minValue, int maxValue) {
    DataManager* dataManager = malloc(sizeof(DataManager));
    if (!dataManager) {
        fprintf(stderr, "Failed to allocate memory for the data manager\n");
        exit(EXIT_FAILURE);
    }

    int initialBufferSize = 10; // initial buffer size can be adjusted based on performance/memory considerations
    Record* records = malloc(initialBufferSize * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for the records\n");
        exit(EXIT_FAILURE);
    }

    dataManager->bufferSize = initialBufferSize;
    dataManager->numRecords = 0;
    dataManager->records = records;
    dataManager->stepSize = stepSize;
    dataManager->interval = interval;
    dataManager->minValue = minValue;
    dataManager->maxValue = maxValue;

    for (int i = 0; i < numRecords; i++) {
        if (i >= dataManager->bufferSize)  // handle overflow condition by resizing the buffer
            resizeBuffer(dataManager, dataManager->bufferSize * 2);

        initializeRecord(dataManager, i);
        dataManager->numRecords++;
    }

    return dataManager;
}
```

