typedef struct Node{
   struct Node *next;
   NFAPI_CRC_INDICATION_PDU_T pdu;
}Node;

Node *head = NULL;

int addEntry(NFAPI_CRC_INDICATION_PDU_T newPdu){
    if (newPdu.RNTI <= 0) {
        printf("Invalid RNTI\n");
        return -1;
    }

    Node *cur = head;
    while(cur != NULL){
        if(cur->pdu.RNTI == newPdu.RNTI){
            printf("Duplicate RNTI found, ignoring\n");
            return -1;
        }
        cur = cur->next;
    }

    Node *newNode = (Node*)malloc(sizeof(Node));
    newNode->pdu = newPdu;
    newNode->next = head;
    head = newNode;
    return 0;
}

void traverseList(){
   struct Node *ptr = head;
   while(ptr != NULL){
      printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n", ptr->pdu.RXTU_UE_INFORMATION_TAG, ptr->pdu.RNTI, ptr->pdu.CRC_INDICATION_REL8_TAG);
      ptr = ptr->next;
   }
}

