    for(int i = 0; i < 10; i++){
        newPdu.RX_UE_INFORMATION_TAG = rand();
        newPdu.RNTI = rand();
        newPdu.CRC_INDICATION_REL8_TAG = rand();

        addEntry(newPdu);
    }

    traverseList();

    return 0;
}
