int processFile(const char *filename, Record **records, size_t *count, char ***keys) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) return 1; // Error opening file

    *count = 0;
    Record *tempRecords = malloc(sizeof(Record));
    char **tempKeys = calloc(256, sizeof(char*));
    srand((unsigned int)time(NULL));

    char line[1001];
    while (fgets(line, sizeof(line), file)) {
        if (*count >= 1000) break; // Constraint to 1000 lines

        tempRecords = realloc(tempRecords, (*count + 1) * sizeof(Record));
        Record *record = &tempRecords[*count];
        ++(*count);

        record->line = strdup(line); // Duplicate line for storage
        record->rand_int = rand() % 1000 + 1; // Random integer within range

        char key[2] = { '\0', '\0' };
        int i = 0;
        while (isspace(line[i])) ++i; // Skip leading whitespaces

        if (!isalnum(line[i]) && line[i] != '\0') continue; // Invalid character at start of line
        key[0] = line[i]; // Extract first non-whitespace char as key

        int index = (unsigned char)key[0]; // Convert to unsigned for proper indexing
        if (tempKeys[index] == NULL) { // Check and add unique keys
            tempKeys[index] = strdup(key);
        }
    }

    fclose(file);
    *records = tempRecords;

    // Compact 'keys' to avoid null pointers
    size_t compactIndex = 0;
    for (size_t i = 0; i < 256; ++i) {
        if (tempKeys[i] != NULL) {
            tempKeys[compactIndex++] = tempKeys[i];
        } else {
            free(tempKeys[i]); // Free unused memory
        }
    }

    *keys = malloc(compactIndex * sizeof(char*));
    memcpy(*keys, tempKeys, compactIndex * sizeof(char*));
    free(tempKeys);

    return 0; // Success
}
