#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Assume we have a struct like this
typedef struct record {
    int key;
} record_t;

// Assume we have these functions for handling memory and synchronization primitives
extern void* app_alloc(size_t);
extern void app_free(void*);
extern void app_lock(pthread_mutex_t*);
extern void app_unlock(pthread_mutex_t*);

// Hash table node
typedef struct hashnode {
    record_t *record;
    struct hashnode *next;
} hashnode_t;

// Hash table
typedef struct hashtable {
    int size;
    pthread_mutex_t lock;  // Need to synchronize access if using multithreaded environment
    hashnode_t **nodes;
} hashtable_t;

hashtable_t* create_hash_table(int size) {
    hashtable_t *table = (hashtable_t*)app_alloc(sizeof(hashtable_t));
    if (!table) return NULL;

    table->size = size;
    pthread_mutex_init(&table->lock, NULL);
    table->nodes = (hashnode_t**)app_alloc(size * sizeof(hashnode_t*));
    if (!table->nodes) {
        app_free(table);
        return NULL;
    }

    for (int i = 0; i < size; ++i) table->nodes[i] = NULL;
    return table;
}

unsigned int hash(hashtable_t *table, int key) {
    // Simple hash function: modulo with table size
    return key % table->size;
}

record_t* search_hash_table(hashtable_t *table, int key) {
    unsigned int index = hash(table, key);

    pthread_mutex_lock(&table->lock);
    hashnode_t *node = table->nodes[index];
    while (node) {
        if (node->record && node->record->key == key) {
            pthread_mutex_unlock(&table->lock);
            return node->record;
        }

        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;  // Record not found in hash table
}

void insert_hash_table(hashtable_t *table, record_t *record) {
    unsigned int index = hash(table, record->key);

    pthread_mutex_lock(&table->lock);
    hashnode_t *node = (hashnode_t*)app_alloc(sizeof(hashnode_t));
    if (!node) {  // Allocation failed, return to prevent memory leak
        pthread_mutex_unlock(&table->lock);
        return;
    }

    node->record = record;
    node->next = table->nodes[index];
    table->nodes[index] = node;
    pthread_mutex_unlock(&table->lock);
}
```
Please note that this code is a simplified version and doesn't cover the full specification of your task. Error handling, logging services integration, reading configuration file etc are also not implemented. Also, I assumed few things such as the existence of `app_alloc`, `app_free`, `app_lock`, `app_unlock` functions which handle memory and synchronization primitives in a given application framework.
