typedef struct PacketHeader {
    uint32_t version;
    uint32_t seqNumber;
    time_t timestamp;
    size_t payloadLen;
} PacketHeader;

typedef struct PacketArray {
    PacketHeader* headers;
    atomic_uint lastAckSeqNum;
    pthread_mutex_t lock;
    int capacity;
    int size;
} PacketArray;

void PacketArrayInit(PacketArray* arr, int initialCapacity) {
    assert(initialCapacity > 0);

    arr->capacity = initialCapacity;
    arr->size = 0;
    arr->headers = (PacketHeader*) malloc(arr->capacity * sizeof(PacketHeader));
    atomic_store(&arr->lastAckSeqNum, 0);
    pthread_mutex_init(&arr->lock, NULL);
}

void PacketArrayFree(PacketArray* arr) {
    free(arr->headers);
    pthread_mutex_destroy(&arr->lock);
}

// You'd need to implement the network communication library in a separate module
extern void sendPacket(PacketHeader* header, int retryLimit); 

void PacketArrayPushBack(PacketArray* arr, PacketHeader newHeader) {
    assert(newHeader.seqNumber > atomic_load(&arr->lastAckSeqNum));

    pthread_mutex_lock(&arr->lock);

    if (arr->size == arr->capacity) {
        // Expand the array
        arr->capacity *= 2; 
        arr->headers = realloc(arr->headers, arr->capacity * sizeof(PacketHeader));
    }

    arr->headers[arr->size++] = newHeader;

    pthread_mutex_unlock(&arr->lock);
}

void PacketArrayUpdate(PacketArray* arr, uint32_t seqNumber, PacketHeader newHeader) {
    assert(seqNumber < arr->size && seqNumber >= atomic_load(&arr->lastAckSeqNum)); 

    pthread_mutex_lock(&arr->lock);

    arr->headers[seqNumber] = newHeader;

    pthread_mutex_unlock(&arr->lock);
}

void PacketArraySendPackets(PacketArray* arr, int retryLimit) {
    for (int i = 0; i < arr->size; ++i) {
        sendPacket(&arr->headers[i], retryLimit); 
    }
}
