```C
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct UserSessionState {
    int userId;
    time_t startTime;
    time_t lastActiveTime;
    enum SessionStatus { ACTIVE, INACTIVE } status;
} UserSessionState;

// Using a simple linked list for demonstration purposes.
// A more efficient structure like a hash table or B-tree could be used in practice.
typedef struct Node {
    UserSessionState *data;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addNewSession(int userId) {
    pthread_mutex_lock(&lock);

    // Create a new session.
    UserSessionState *newSession = malloc(sizeof(UserSessionState));
    if (newSession == NULL) {
        fprintf(stderr, "Failed to allocate memory.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    newSession->userId = userId;
    time(&newSession->startTime);
    newSession->lastActiveTime = newSession->startTime;
    newSession->status = ACTIVE;

    // Add it to the list.
    Node *newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Failed to allocate memory.\n");
        free(newSession);
        pthread_mutex_unlock(&lock);
        return;
    }

    newNode->data = newSession;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

UserSessionState *getSession(int userId) {
    pthread_mutex_lock(&lock);

    Node *current = head;
    while (current != NULL) {
        if (current->data->userId == userId) {
            UserSessionState *sessionCopy = malloc(sizeof(UserSessionState));
            *sessionCopy = *current->data;

            pthread_mutex_unlock(&lock);
            return sessionCopy;
        }

        current = current->next;
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}
```

This code is not complete by any means. It only provides a starting point, and the handling of session inactivity would have to be added for it to function in a real-world setting. The use of mutexes ensures thread safety, but as mentioned before, a more robust solution might require more complex designs that allow for concurrent access without data corruption or inconsistencies.
