void add(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if(newNode == NULL){
        printf("Memory allocation failed.\n"); 
        // You can log the error here using your logging framework
        return;
    }

    pthread_mutex_lock(&lock);

    newNode->data = data;
    newNode->next = head;
    head = newNode;
    count++;

    if(count > MAX_SIZE){ // If the list exceeds a certain size, resize it
        Node* current = head;
        for(int i = 0 ; i < (MAX_SIZE / 2) - 1 && current != NULL; ++i){ // Reduce to half of original size
            current = current->next;
        }

        if(current != NULL){
            Node* temp = current->next;
            current->next = NULL;

            while(temp != NULL){ // Free the memory of truncated nodes
                Node* nextNode = temp->next;
                free(temp);
                temp = nextNode;
            } 
        }
    }

    pthread_mutex_unlock(&lock);
}

