['```c
#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t capacity;
    size_t count;
    FILE *logFile;
    pthread_mutex_t lock;
} DataStructureManager;

DataStructureManager* initialize(size_t maxOffset, size_t maxKey, int valueRange, size_t initialCapacity, const char *logFileName) {
    DataStructureManager *manager = malloc(sizeof(DataStructureManager));

    if (manager == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    manager->offsets = calloc(maxOffset, sizeof(long));
    manager->keys = calloc(maxKey, sizeof(int));
    manager->records = malloc(initialCapacity * sizeof(record*));

    if (manager->offsets == NULL || manager->keys == NULL || manager->records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    manager->capacity = initialCapacity;
    manager->count = 0;

    if (logFileName != NULL) {
        manager->logFile = fopen(logFileName, "w");

        if (manager->logFile == NULL) {
            fprintf(stderr, "Log file creation failed\n");
            exit(EXIT_FAILURE);
        }
    } else {
        manager->logFile = NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void addRecord(DataStructureManager *manager, int value) {
    record* newRecord = malloc(sizeof(record));

    if (newRecord == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    newRecord->value = value;

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        record** newRecords = realloc(manager->records, newCapacity * sizeof(record*));

        if (newRecords == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        manager->capacity = newCapacity;
        manager->records = newRecords;
    }

    manager->records[manager->count++] = newRecord;

    pthread_mutex_unlock(&manager->lock);
}

int lookup(DataStructureManager *manager, int key) {
    if (key < 0 || key >= manager->count) {
        return -1;
    }

    record* accessedRecord = NULL;

    pthread_mutex_lock(&manager->lock);

    accessedRecord = manager->records[key];

    if (accessedRecord != NULL && manager->logFile != NULL) {
        fprintf(manager->logFile, "Accessed record with value %d\n", accessedRecord->value);
    }

    pthread_mutex_unlock(&manager->lock);

    return accessedRecord == NULL ? -1 : accessedRecord->value;
}
```
In this code, the DataStructureManager struct is used to maintain all necessary information and concurrency control. Initially, memory is allocated for the arrays of offsets, keys, and records, with initial capacities defined by user input. If any allocation fails, an error message will be printed out and the program terminates gracefully.

The addRecord function safely adds a new record to the array while maintaining concurrency control using mutex locks. If the current capacity is reached, memory for the records array is doubled using realloc to ensure that no memory allocation failures occur in the future due to insufficient space.

Finally, the lookup function safely retrieves the value of a record with a specified key and logs access events to the provided log file. The function returns -1 if the key is out of range or if the accessed record is NULL.
']

