#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int* array;
    int size;
} Record;

int generate_unique_random(int range, int* used, int count) {
    int num;
    do {
        num = rand() % range;
    } while (used[num]);
    used[num] = 1;
    return num;
}

Record** allocate_records(int records, int arraysize, int range) {
    srand(time(NULL));

    Record **collection = malloc(records * sizeof(Record*));
    if (collection == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    int used[range] = {0}; // to maintain uniqueness of random numbers 

    for (int i = 0; i < records; ++i) {
        Record* record = malloc(sizeof(Record));
        if (record == NULL) {
            printf("Memory allocation failed.\n");
            return NULL; // Handle failure here.
        }

        int *array = malloc(arraysize * sizeof(int));
        if (array == NULL) {
            printf("Memory allocation failed.\n");
            return NULL; // Handle failure here.
        }

        for (int j = 0; j < arraysize; ++j) {
            array[j] = generate_unique_random(range, used, count);
        }

        record->array = array;
        record->size = arraysize;
        collection[i] = record;
    }

    printf("Memory allocation completed successfully.\n");
    return collection;
}

void deallocate_records(Record** collection, int records) {
    for (int i = 0; i < records; ++i) {
        free(collection[i]->array);
        free(collection[i]);
    }

    free(collection);
}
```
