    manager->keys = calloc(MAX_SIZE, sizeof(int));
    manager->records = NULL;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);
}

void addKey(ArrayManager *manager, int key) {
    if (manager->size < MAX_SIZE && !containsKey(manager, key)) {
        manager->keys[manager->size] = key;
        manager->records = realloc(manager->records, sizeof(Record) * ++manager->size);
    } else if (containsKey(manager, key)) {
        printf("Duplicate key detected: %d\n", key);
    } else {
        printf("Maximum capacity reached.\n");
    }
}

int containsKey(ArrayManager *manager, int key) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->keys[i] == key) return 1;
    }
    return 0;
}

void populateRecords(ArrayManager *manager, int minVal, int maxVal) {
