        } while (isValueInRecords(manager, val));
        manager->records[i].value = val;
    }
}

int isValueInRecords(ArrayManager *manager, int value) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i].value == value) return 1;
    }
    return 0;
}

void sortRecords(ArrayManager *manager) {
    qsort(manager->records, manager->size, sizeof(Record), compare);
}

int compare(const void* a, const void* b) {
    Record* recordA = (Record*)a;
    Record* recordB = (Record*)b;
    return recordA->value - recordB->value;
}

void destroy(ArrayManager *manager) {
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    pthread_mutex_destroy(&manager->mutex);
}
```
