typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_SIZE 10
#define GROWTH_FACTOR 2

typedef struct {
    size_t size;
    size_t limit;
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* array;
} DynamicArray;

int initDynamicArray(DynamicArray* da, int n) {
    assert(da != NULL);

    if (n <= 0) return -EINVAL;

    da->array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * INITIAL_SIZE);
    if (da->array == NULL) {
        perror("malloc failed");
        return -ENOMEM;
    }

    da->limit = n;
    da->size = 0;
    pthread_mutex_init(&da->lock, NULL);

    return 0;
}

void destroyDynamicArray(DynamicArray* da) {
    assert(da != NULL);

    free(da->array);
    pthread_mutex_destroy(&da->lock);
}

int resizeDynamicArray(DynamicArray* da, int n) {
    assert(da != NULL);

    if (n <= 0 || n <= da->size) return -EINVAL;

    NFAPI_CRC_INDICATION_PDU_T* newArray = realloc(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (newArray == NULL) {
        perror("realloc failed");
        return -ENOMEM;
    }

    da->limit = n;
    da->array = newArray;

    return 0;
}

int appendToDynamicArray(DynamicArray* da, NFAPI_CRC_INDICATION_PDU_T item) {
    assert(da != NULL);

    pthread_mutex_lock(&da->lock);

    if (da->size == da->limit) {
        int ret = resizeDynamicArray(da, GROWTH_FACTOR * da->limit);
        if (ret < 0) {
            pthread_mutex_unlock(&da->lock);
            return ret;
        }
    }

    da->array[da->size++] = item;

    pthread_mutex_unlock(&da->lock);

    return 0;
}

size_t getArraySize(DynamicArray* da) {
    assert(da != NULL);

    size_t size = 0;
    pthread_mutex_lock(&da->lock);
    size = da->size;
    pthread_mutex_unlock(&da->lock);

    return size;
}
```
This code provides a dynamic array that grows in accordance with the `GROWTH_FACTOR` whenever it reaches its current limit. It protects access to the array from concurrent modifications using a mutex. The error handling is quite simple and only returns an integer status code for detailed error reporting, but a more robust error handling strategy would be needed for a production environment.
