#define MEMORY_LIMIT (64 * 1024)

// Logging constants and variables.
#define LOG_BUFFER_SIZE 1024
char logBuffer[LOG_BUFFER_SIZE][256];
int logStart = 0;
int logEnd = 0;
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

// Concurrency control and memory management variables.
pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* pduList[MAX_LIST_SIZE];
int allocatedMemory = 0;

// Function to handle logging.
void logEvent(char* event) {
    pthread_mutex_lock(&logMutex);

    strncpy(logBuffer[logEnd], event, 256);
    logEnd = (logEnd + 1) % LOG_BUFFER_SIZE;

    // Overwrite oldest entry if buffer is full.
    if (logStart == logEnd) {
        logStart = (logStart + 1) % LOG_BUFFER_SIZE;
    }

    pthread_mutex_unlock(&logMutex);
}

// Function to handle memory allocation and tag generation.
NFAPI_CRC_INDICATION_PDU_T* allocateMemoryAndGenerateTag(int rnti) {
    // Ensure sufficient memory is available before allocating more.
    if (allocatedMemory + sizeof(NFAPI_CRC_INDICATION_PDU_T) > MEMORY_LIMIT) {
        logEvent("Insufficient memory to allocate new PDU.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        logEvent("Failed to allocate memory for new PDU.");
        return NULL;
    }

    // Randomly set CRCFLAG.
    pdu->RNTI = rnti;
    pdu->CRCFLAG = rand() % 2;

    allocatedMemory += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    return pdu;
}

// Thread safe function to add a PDU to the list.
void addPDUTagSafely(int rnti) {
    pthread_mutex_lock(&listMutex);

    // Check for duplicate RNTI before adding new PDU.
    for (int i = 0; i < MAX_LIST_SIZE; ++i) {
        if (pduList[i] != NULL && pduList[i]->RNTI == rnti) {
            logEvent("Attempted to add duplicate RNTI.");
            pthread_mutex_unlock(&listMutex);
            return;
        }
    }

    // Find an empty slot in the list and allocate memory for a new PDU.
    for (int i = 0; i < MAX_LIST_SIZE; ++i) {
        if (pduList[i] == NULL) {
            pduList[i] = allocateMemoryAndGenerateTag(rnti);
            break;
        }
    }

    pthread_mutex_unlock(&listMutex);
}
```
