#include <string.h>

typedef struct {
    char* name;
    // Add other properties here...
} NetworkInterfaceConfig;

typedef struct Node {
    NetworkInterfaceConfig config;
    int active;
    pthread_mutex_t lock;
    struct Node* next;
} Node;

Node* head = NULL;  // global list of configurations
pthread_mutex_t listLock = PTHREAD_MUTEX_INITIALIZER;

void addConfig(NetworkInterfaceConfig config) {
    Node* node = malloc(sizeof(Node));
    if (node == NULL) return;  // handle error

    node->config = config;
    node->active = 0;
    pthread_mutex_init(&node->lock, NULL);

    pthread_mutex_lock(&listLock);
    node->next = head;
    head = node;
    pthread_mutex_unlock(&listLock);
}

void removeConfig(Node* node) {
    if (node == NULL || node == head) return;  // handle error

    Node* prev = head;
    while (prev->next != node) {
        if (prev->next == NULL) return;  // not found, handle error
        prev = prev->next;
    }

    pthread_mutex_lock(&listLock);
    prev->next = node->next;
    pthread_mutex_unlock(&listLock);

    pthread_mutex_destroy(&node->lock);
    free(node);
}

void updateConfig(Node* node, NetworkInterfaceConfig newConfig) {
    if (node == NULL) return;  // handle error

    pthread_mutex_lock(&listLock);
    node->config = newConfig;
    pthread_mutex_unlock(&listLock);
}

void getStats(int* activeCount, int* inactiveCount) {
    *activeCount = 0;
    *inactiveCount = 0;

    Node* curr = head;
    while (curr != NULL) {
        if (curr->active) (*activeCount)++;
        else (*inactiveCount)++;

        curr = curr->next;
    }
}

// Function to interact with external service and update configs
void updateFromExternalService() {
