    pthread_mutex_lock(&listLock);
    Node* node = findNodeByName(newConfig.name);  // Assuming a function to find nodes by name
    if (node == NULL) {
        addConfig(newConfig);  // Add new config
    } else {
        updateConfig(node, newConfig);  // Update existing config
    }
    pthread_mutex_unlock(&listLock);
}
```
