typedef struct {
    int LOGICAL_CHANNEL_ID;
    int TRANSPORT_FORMAT;
    int LOGICAL_CHANNEL_STATUS;
} NFMMAP_LOGICAL_CHANNEL_PDU_T;

#define MAX_SIZE 1024 // Configurable maximum size limit
#define GROWTH_FACTOR 2.0f // Growth factor for dynamic resizing

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static atomic_int current_size = 0;
static NFMMAP_LOGICAL_CHANNEL_PDU_T *array = NULL;

void manage_array(int n) {
    if (n <= 0) {
        return;
    }

    pthread_mutex_lock(&mutex); // Lock mutex for thread-safety

    if ((current_size + n) > MAX_SIZE) {
        int new_size = current_size * GROWTH_FACTOR;
        NFMMAP_LOGICAL_CHANNEL_PDU_T *new_array = (NFMMAP_LOGICAL_CHANNEL_PDU_T *)realloc(array, new_size * sizeof(NFMMAP_LOGICAL_CHANNEL_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&mutex); // Unlock mutex if allocation failed
            return;
        }

        array = new_array; // Update global array pointer
    }

    for (int i = 0; i < n; ++i) {
        atomic_fetch_add(&current_size, 1);
        int index = current_size - 1;

        // Initialize each structure as needed
        array[index].LOGICAL_CHANNEL_ID = 0;
        array[index].TRANSPORT_FORMAT = 0;
        array[index].LOGICAL_CHANNEL_STATUS = 0;
    }

    pthread_mutex_unlock(&mutex); // Unlock mutex after modifying the global state
}
