    char* value; // Can be made more complex if needed
} CacheEntry;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

void distributeCacheEntries(int cacheSize, CacheEntry** entries) {
    pthread_mutex_lock(&lock); // Lock to avoid race conditions

    for (int i = 0; i < cacheSize; i++) {
        CacheEntry* entry = entries[i];

        if (!entry) continue; 

        time(&(entry->timestamp)); // Update timestamp
        (entry->version)++; // Increment version number

