public class WebPageElementUpdater : IWebPageElementUpdater
{
    private readonly ConcurrentDictionary<string, SemaphoreSlim> _sectionLocks = new ConcurrentDictionary<string, SemaphoreSlim>();

    public async Task<HttpResponseMessage> UpdatePageElementAsync(string pageSectionId, string elementId, string htmlContent)
    {
        if (pageSectionId == null || elementId == null || htmlContent == null)
            throw new ArgumentNullException("One or more arguments are null");

        var lockKey = GetLockKey(pageSectionId, elementId);

        // Acquire a semaphoreSlim for the section. 
        if (!_sectionLocks.TryGetValue(lockKey, out SemaphoreSlim semaphore))
        {
            semaphore = _sectionLocks.GetOrAdd(lockKey, new SemaphoreSlim(1, 1));
        }

        await semaphore.WaitAsync();

        try
        {
            // Sanitize inputs before using them in a third-party API call.
            pageSectionId = SanitizeInput(pageSectionId);
            elementId = SanitizeInput(elementId);
            htmlContent = SanitizeInput(htmlContent);

            var requestUrl = $"http://api.example.com/sections/{pageSectionId}/elements/{elementId}";

            using (var client = new HttpClient())
            {
                client.DefaultRequestHeaders.Add("User-Agent", Request.UserAgent.ToString());

                var content = new StringContent(JsonConvert.SerializeObject(new { htmlContent }), Encoding.UTF8, "application/json");

                using (var response = await HttpClientExtensions.PatchAsync(client, requestUrl, content))
                {
                    // Log the operation for debugging and monitoring purposes.
                    var stopwatch = Stopwatch.StartNew();

                    try
                    {
                        if (!response.IsSuccessStatusCode)
                            throw new Exception("Update failed");

                        // Return a response indicating that the page should be refreshed.
                        return Request.CreateResponse(HttpStatusCode.Accepted, "Page refresh required");
                    }
                    finally
                    {
                        stopwatch.Stop();

                        var logMessage = $"Element with ID '{elementId}' in section '{pageSectionId}' updated successfully in {stopwatch.ElapsedMilliseconds} ms";
                        Log.Information(logMessage);
                    }
                }
            }
        }
        finally
        {
            // Release the semaphoreSlim for other threads to access this section.
            semaphore.Release();
        }
    }

    private static string GetLockKey(string pageSectionId, string elementId)
    {
        return $"{pageSectionId}:{elementId}";
    }

