typedef struct NFAPI_CRC_INDICATION_PDU {
    int RNTI;
    void* RX_UE_INFORMATION_TAG; // replace with actual type
    unsigned CRC_INDICATION_REL8_TAG; 
} NFAPI_CRC_INDICATION_PDU_T;

struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* left;
    struct Node* right;
    int height;
};

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
struct Node* root = NULL;
unsigned totalCRC = 0;

int height(struct Node *N) {
    if (N == NULL) return 0;
    return N->height;
}

int max(int a, int b) {
    return (a > b)? a : b;
}

struct Node* newNode(NFAPI_CRC_INDICATION_PDU_T data) {
    struct Node* node = (struct Node*) malloc(sizeof(struct Node));
    if (!node) exit(-1); // handle memory error

    node->data  = data;
    node->left   = NULL;
    node->right  = NULL;
    node->height = 1; 
    return(node);
}

struct Node *rightRotate(struct Node *y) {
    struct Node *x = y->left;
    struct Node *T2 = x->right;

    x->right = y;
    y->left = T2;

    y->height = max(height(y->left), height(y->right))+1;
    x->height = max(height(x->left), height(x->right))+1;

    return x;
}

struct Node *leftRotate(struct Node *x) {
    struct Node *y = x->right;
    struct Node *T2 = y->left;

    y->left = x;
    x->right = T2;

    x->height = max(height(x->left), height(x->right))+1;
    y->height = max(height(y->left), height(y->right))+1;

    return y;
}

int getBalance(struct Node *N) {
    if (N == NULL) return 0;
    return height(N->left) - height(N->right);
}

struct Node* insert(struct Node* node, NFAPI_CRC_INDICATION_PDU_T data) {
    if (node == NULL)
        return(newNode(data));

    if (data.RNTI < node->data.RNTI)
        node->left  = insert(node->left, data);
    else if (data.RNTI > node->data.RNTI)
        node->right = insert(node->right, data);
    else 
        return node; // no duplicates

    node->height = 1 + max(height(node->left), height(node->right));

    int balance = getBalance(node);
    if (balance > 1 && data.RNTI < node->left->data.RNTI)
        return rightRotate(node);

    if (balance < -1 && data.RNTI > node->right->data.RNTI)
        return leftRotate(node);

    if (balance > 1 && data.RNTI > node->left->data.RNTI) {
        node->left =  leftRotate(node->left);
        return rightRotate(node);
    }

    if (balance < -1 && data.RNTI < node->right->data.RNTI) {
        node->right = rightRotate(node->right);
        return leftRotate(node);
    }

    return node;
}

struct Node* minValueNode(struct Node* node) {
    struct Node* current = node;
    while (current->left != NULL)
        current = current->left;
    return current;
}

struct Node* deleteNode(struct Node* root, int RNTI) {
    if (root == NULL)
        return root;

    if ( RNTI < root->data.RNTI )
        root->left = deleteNode(root->left, RNTI);

    else if( RNTI > root->data.RNTI )
        root->right = deleteNode(root->right, RNTI);

    else {
        if( (root->left == NULL) || (root->right == NULL) ) {
            struct Node *temp = root->left ? root->left : root->right;

            if(temp == NULL) {
                temp = root;
                root = NULL;
            } else
                *root = *temp; 
            free(temp);
        } else {
            struct Node* temp = minValueNode(root->right);
            root->data.RNTI = temp->data.RNTI;
            root->right = deleteNode(root->right, temp->data.RNTI);
        }
    }

    if (root == NULL)
      return root;

    root->height = 1 + max(height(root->left), height(root->right));

    int balance = getBalance(root);

    if (balance > 1 && getBalance(root->left) >= 0)
        return rightRotate(root);

    if (balance > 1 && getBalance(root->left) < 0) {
        root->left =  leftRotate(root->left);
        return rightRotate(root);
    }

    if (balance < -1 && getBalance(root->right) <= 0)
        return leftRotate(root);

    if (balance < -1 && getBalance(root->right) > 0) {
        root->right = rightRotate(root->right);
        return leftRotate(root);
    }

    return root;
}

NFAPI_CRC_INDICATION_PDU_T* search(struct Node* root, int RNTI) {
