["Below is a sample implementation in C language that uses pthreads for thread safety, atomic operations for efficient concurrency-safe access, and memory pools for efficient memory management. Note that actual coding might require additional complexity due to specific requirements of your system or project. This code doesn't include the data reception and transmission operation part as it would be a very complex task that could involve implementing network protocols, buffer handling, etc. which are beyond the scope of this platform.

```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    atomic_uint session_id;
    atomic_int connection_timeout;
    char* buffer;
    pthread_mutex_t lock;
    char* user_agent;
} Session;

Session* create_session(size_t initial_buffer_size) {
    Session* session = malloc(sizeof(Session));
    atomic_init(&session->session_id, 0);
    atomic_init(&session->connection_timeout, -1); // Default value
    pthread_mutex_init(&session->lock, NULL);

    session->buffer = malloc(initial_buffer_size);
    session->user_agent = malloc(256); // Max length of user agent string
    return session;
}

void resize_buffer(Session* session, size_t new_size) {
    pthread_mutex_lock(&session->lock);
    session->buffer = realloc(session->buffer, new_size);
    pthread_mutex_unlock(&session->lock);
}

void update_data(Session* session, char* data, size_t data_length) {
    pthread_mutex_lock(&session->lock);
    // Copy or process the data here in a non-blocking way
    memcpy(session->buffer, data, data_length);
    pthread_mutex_unlock(&session->lock);
}

void destroy_session(Session* session) {
    free(session->user_agent);
    free(session->buffer);
    pthread_mutex_destroy(&session->lock);
    free(session);
}
```
This implementation assumes that the size of user agent string is small enough to be handled in a reasonable time by `malloc`, which may not hold true for all use cases. Also it's assumed that session id will only be set once and can be updated as necessary. For larger projects, consider using an existing memory pool library or rolling your own solution to manage the memory more efficiently.

