#include <forward_list>
#include <string>
#include <random>
#include <mutex>
#include <vector>

struct Record {
    int value;
    long index;
};

void processAndModifyList(std::forward_list<std::string>& list, const std::string& firstString, 
                          const std::string& secondString, unsigned int lowerLimit = 0,
                          unsigned int upperLimit = UINT32_MAX) {
    // Mutex for thread safety when inserting to the forward_list
    static std::mutex mtx;

    // Vector of Records instead of dynamic allocation and resizing 
    std::vector<Record> records(upperLimit - lowerLimit);

    // Create a random number generator that produces non-deterministic random numbers
    std::random_device rd; 
    std::mt19937 gen(rd());

    // Populate the record array with random integers within a specified range
    for (unsigned int i = 0; i < upperLimit - lowerLimit; ++i) {
        records[i].value = std::uniform_int_distribution<unsigned int>{lowerLimit, upperLimit}(gen);
        records[i].index = i + lowerLimit;
    }

    // Find the first occurrence of firstString in the list
    auto it = std::find(list.begin(), list.end(), firstString);

    if (it != list.end()) {
        // If found, insert secondString immediately after the found element
        mtx.lock();  // Lock mutex before modifying forward_list to ensure thread safety
        list.insert_after(it, secondString);
        mtx.unlock();  // Unlock mutex after modification of forward_list
    } else {
        // If not found, append secondString to the end of the list
        mtx.lock();  // Lock mutex before modifying forward_list to ensure thread safety
        list.insert_after(list.before_begin(), secondString);
        mtx.unlock();  // Unlock mutex after modification of forward_list
    }
}
