// Define global data structure and its mutex for thread safety
CRC_LIST_ITEM *list = NULL;
size_t list_count = 0;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new item to the list, ensuring only unique entries are added
void add_crc(NFAPI_CRC_INDICATION_PDU_T *rx_ue_information, uint16_t rnti) {
    pthread_mutex_lock(&list_lock); // Lock mutex to ensure thread safety

    // Check if the item already exists in the list
    for (size_t i = 0; i < list_count; ++i) {
        if (list[i].rnti == rnti && !memcmp(list[i].rx_ue_information, rx_ue_information, sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
            pthread_mutex_unlock(&list_lock); // Unlock mutex before returning
            return;
        }
    }

    // If the item does not exist in the list, add it and update the count
    if ((realloc(list, sizeof(CRC_LIST_ITEM) * (list_count + 1))) == NULL) {
        perror("Memory allocation error");
        pthread_mutex_unlock(&list_lock); // Unlock mutex before returning in case of failure
        return;
    }

    list[list_count].rx_ue_information = rx_ue_information;
    list[list_count].rnti = rnti;
    list[list_count].crcflag = /* calculate crc flag here */;
    ++list_count;

