['Here is a rough implementation of the problem. This code uses linked list to store project details for simplicity. The function `add_project` allocates memory for a new project and adds it to the linked list. Project names are limited to 256 characters, and if the user input exceeds this limit or there's a memory allocation failure, an error message is logged using an external logging system.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef enum { NOT_STARTED, IN_PROGRESS, COMPLETED } status;

typedef struct record {
    int val;
} record;

typedef struct project {
    char* name;
    time_t start_date;
    status task_status;
    long offset;
    int key;
    size_t records_count;
    record* records;
} project;

project* projects = NULL;
size_t projects_count = 0;
extern void log_error(const char *msg);

int add_project(char* name, long offset) {
    if (projects_count >= 100) {
        log_error("Cannot create project. Maximum limit reached.");
        return -1;
    }

    size_t len = strlen(name);
    if (len > 256) {
        char msg[256];
        sprintf(msg, "Project name too long: '%s'", name);
        log_error(msg);
        return -1;
    }

    project* new_project = malloc(sizeof(project));
    if (new_project == NULL) {
        log_error("Failed to allocate memory for new project.");
        return -1;
    }

    // Initialize project details
    new_project->name = malloc(len + 1);
    if (new_project->name == NULL) {
        free(new_project);
        log_error("Failed to allocate memory for project name.");
        return -1;
    }

    strcpy(new_project->name, name);
    new_project->start_date = time(NULL);
    new_project->task_status = NOT_STARTED;
    new_project->offset = offset;
    new_project->key = rand();  // Assign a random key to each project.

    // Initialize records with random values within a certain range.
    const int MAX_RECORDS = 100;
    new_project->records_count = MAX_RECORDS;
    new_project->records = malloc(MAX_RECORDS * sizeof(record));
    if (new_project->records == NULL) {
        free(new_project->name);
        free(new_project);
        log_error("Failed to allocate memory for records.");
        return -1;
    }

    const int RANGE = 1000;  // Random value range.
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        new_project->records[i].val = rand() % RANGE;
    }

    // Add the project to the linked list.
    new_project->next = projects;
    projects = new_project;
    ++projects_count;
    return 0;
}
```
Please note that this code needs a logging function `log_error` defined externally for it to work properly. Also, this is a simplistic solution and may need adjustments based on specific project requirements like concurrency handling, error checking, etc. It also doesn't handle memory deallocation in case of failure while adding new projects or records which should be handled carefully in production code.
']

