// Function to free all allocated memory.
void clearAllocatedMemory() {
    std::lock_guard<std::mutex> lock(mtx);
    for (auto ptr : allocatedMemory) {
        delete[] ptr;
    }
    allocatedMemory.clear();
}

// Function to allocate and initialize memory for Record array.
Record* allocAndInitialize(size_t size, int lowerBound, int upperBound, int maxThreshold) {
    std::lock_guard<std::mutex> lock(mtx);

    auto arr = new Record[size];  // Allocate memory for array.
    allocatedMemory.push_back(arr);  // Track this allocation.

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(lowerBound, upperBound);

    for (size_t i = 0; i < size; ++i) {
        int value = dis(gen);
        if (value > maxThreshold) {  // Ensure values do not exceed threshold.
            value = maxThreshold;
        }
        arr[i] = {value, globalIndex++};  // Initialize Record with value and unique index.
    }

    return arr;
}

