List* createList() {
    List *list = malloc(sizeof(*list));
    if (list == NULL) return NULL;

    list->capacity = 10000;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->data = malloc(list->capacity * sizeof(*list->data));

    return list;
