typedef struct {
    // Add fields as required
} LTE_RRC_CTRLD_RECONFIGURATION_REQUEST;

// Define a Node for the linked list
typedef struct Node {
    LTE_RRC_CTRLD_RECONFIGURATION_REQUEST *request;
    struct Node *next;
} Node;

Node* head = NULL;  // Start of Linked List, initialized to null
pthread_mutex_t lock;  // Mutex for concurrent access
int memory = 0;  // Track total allocated memory
int limit = 5242880;  // Max memory allowed (500KB)

void insert(LTE_RRC_CTRLD_RECONFIGURATION_REQUEST *request) {
    pthread_mutex_lock(&lock);  // Lock for concurrent access

    Node *node = head;
    int size = sizeof(*request);

    if (memory + size > limit || node == NULL) {
        memory = 0;
        head = NULL;
    } else {
        while(node->next != NULL && memcmp(node, request, size)) {
            node = node->next;
        }

        if (memcmp(node, request, size) == 0) {  // Duplicate found
            pthread_mutex_unlock(&lock);
            return;
        } else {
            memory += size;

            Node *newNode = malloc(sizeof(Node));
            newNode->request = request;
            newNode->next = NULL;

            node->next = newNode;  // Add to end of list
        }
    }

    pthread_mutex_unlock(&lock);  // Unlock after modification
}
```

This is a basic linked list implementation where each node points to an `LTE_RRC_CTRLD_RECONFIGURATION_REQUEST` struct. When inserting, the function checks if there's enough space for the new request and that it doesn't already exist in the list (to avoid duplicates). If not, the linked list is cleared and re-initialized.

