pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
unsigned int seed = 0; // Custom seed for testing purposes

void* allocateAndInitialize(size_t N, size_t *count) {
    if (N == 0 || !seed) return NULL; 

    pthread_mutex_lock(&lock); // Acquire lock to ensure thread safety
    srand(seed ? seed : time(NULL)); // Use custom seed or current time as seed for randomness

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T)); 
    if (!list) {
        pthread_mutex_unlock(&lock); // Unlock in case of failure to prevent deadlocks
        return NULL;
    }

    int lastCRCFLAG = -1; // Track the last CRCFLAG for avoiding consecutive duplicates
    for (size_t i = 0; i < N; i++) {
        do { 
            list[i].CRCFLAG = rand(); 
        } while (list[i].CRCFLAG == lastCRCFLAG); // Keep generating until a different value is generated

        lastCRCFLAG = list[i].CRCFLAG; // Update the last CRCFLAG
        (*count)++; // Increment the successfully allocated structure count
    }

    pthread_mutex_unlock(&lock); 
    return list;
}
