typedef struct MemorySegment {
    long** offsets;  // an array of n offset arrays, each containing m long integers
    int** keys;      // an array of k key arrays, each containing m int integers
    Record* records; // an array of l record structures
} MemorySegment;

MemorySegment* allocate_memory(int n, int m, int k, int l) {
    srand(time(NULL));  // initialize random seed for rand() function

    MemorySegment* segment = (MemorySegment*)malloc(sizeof(MemorySegment));
    segment->offsets = (long**)calloc(n, sizeof(long*));
    segment->keys = (int**)calloc(k, sizeof(int*));
    segment->records = (Record*)calloc(l, sizeof(Record));

    for(int i = 0; i < n; ++i) {
        segment->offsets[i] = (long*)calloc(m, sizeof(long));
        for(int j = 0; j < m; ++j) {
            // initialize with random values between -1000 and 1000
            segment->offsets[i][j] = rand() % 2001 - 1000;  
        }
    }

    for(int i = 0; i < k; ++i) {
        segment->keys[i] = (int*)calloc(m, sizeof(int));
        for(int j = 0; j < m; ++j) {
            // initialize with unique sequential int values starting from 1
            segment->keys[i][j] = i * m + j + 1;  
        }
    }

    for(int i = 0; i < l; ++i) {
        segment->records[i].buffer = (char*)calloc(m, sizeof(char));
    }

