    // Initialize MSDU lengths and timestamps randomly
    srand(time(NULL));
    for (int i = 0; i < num_msdus; i++) {
        pdu->msdu[i].length = rand() % 65536; // Random length between 0 and 65535
        pdu->header.length += pdu->msdu[i].length;
    }

    return pdu;
}

int compare_timestamps(const void* a, const void* b) {
    MAC_SERVICE_DATA_UNIT* msduA = (MAC_SERVICE_DATA_UNIT*)a;
    MAC_SERVICE_DATA_UNIT* msduB = (MAC_SERVICE_DATA_UNIT*)b;

    return (int)(msduA->timestamp - msduB->timestamp);
}

void sort_and_calculate(MAC_PDU_T* pdu, int num_msdus) {
