// Sample template strings for log messages
const char* templates[] = {
    "Template1",
    "Template2",
    "Template3",
    // Add more as necessary
};

typedef struct {
    long offset;
    int key;
    char* message;
} record;

record* allocate_records(int count, int* successCount) {
    srand(time(NULL)); 

    // Allocate array of records
    record* arr = (record*)malloc(count * sizeof(record));
    if (!arr) return NULL;

    char* lastMessage = NULL;

    for (int i = 0; i < count; ++i) {
        int index = rand() % (sizeof(templates)/sizeof(char*));
        while (lastMessage && strcmp(lastMessage, templates[index]) == 0) {
            // Ensure no two consecutive log messages are identical
            index = rand() % (sizeof(templates)/sizeof(char*));
        }

        lastMessage = templates[index];

        arr[i].offset = i;
        arr[i].key = rand(); // Random key

        // Dynamically allocate message
        size_t len = strlen(lastMessage);
        arr[i].message = (char*)malloc((len + 1) * sizeof(char));
        if (!arr[i].message) {
            for(int j = 0; j < i; ++j) {
                free(arr[j].message); // Free any allocated messages so far
            }
            free(arr);
            return NULL;
        }

        strcpy(arr[i].message, lastMessage); // Copy message into record
    }

    *successCount = count;
    return arr;
}
