#include <stdlib.h>
#include <time.h>
#include "external_storage_system.h" // Assuming this is a hypothetical external library

typedef struct NetworkParameter {
    // add parameters here
} NetworkParameter;

typedef struct Event {
    char* id;
    time_t timestamp;
    NetworkParameter params;
    struct Event *next;
} Event;

Event* events = NULL;

int insert(char* id, time_t timestamp, NetworkParameter params) {
    // Create new event and set its fields
    Event* newEvent = (Event*) malloc(sizeof(Event));
    if (!newEvent) return -1;

    newEvent->id = id;
    newEvent->timestamp = timestamp;
    newEvent->params = params;
    newEvent->next = NULL;

    // Insert at head of list, then sort by timestamp later (not efficient)
    if (!events) {
        events = newEvent;
    } else {
        newEvent->next = events;
        events = newEvent;
    }

    // Write to external storage system
    int result = write_to_storage(newEvent); 
    return result < 0 ? -1 : 0;
}

int update(char* id, NetworkParameter params) {
    Event* current = events;

    while (current) {
        if (!strcmp(current->id, id)) {
            current->params = params; // replace parameters

            int result = write_to_storage(current); 
            return result < 0 ? -1 : 0;
        }

        current = current->next;
    }

    return -1;
}

Event* findInRange(time_t start, time_t end) {
    Event* current = events;
    Event* result = NULL;

    while (current) {
        if (current->timestamp >= start && current->timestamp <= end) {
            // Insert at head of list, then sort by timestamp later (not efficient)
            if (!result) {
                result = current;
            } else {
                current->next = result;
                result = current;
            }
        }

        current = current->next;
    }

    return result;
}
```
