['Here is a simple example of how you might implement this in C language. This code uses a binary search tree (BST) to store the `RNTI` values, which greatly improves the performance of validating these from an external data source. It also uses a linked list to keep track of successful allocations for efficient memory deallocation. 

The function `is_valid_rnti(int rnti)` is just a placeholder for how you might integrate with your external data source to validate `RNTI` values, replace this with the actual call to your data source if possible. Also note that this code assumes that your external data source can return `false` or `true` based on whether the given `rnti` is valid or not.

```C
#include <stdlib.h>
#include <time.h>

typedef struct RX_UE_INFORMATION_TAG {
    int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    struct Node *next;
} Node;

extern bool is_valid_rnti(int rnti); // external function to validate RNTI

void addNode(Node** head, NFAPI_CRC_INDICATION_PDU_T* new_pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));

    if(new_node == NULL) {
        printf("Memory allocation failed!\n");
        exit(0);
    }

    new_node->pdu  = new_pdu;
    new_node->next = *head;
    *head         = new_node;
}

int populate_array(NFAPI_CRC_INDICATION_PDU_T** array, int N, bool random_flag) {
    srand(time(0));

    Node* head = NULL;  // linked list to track successful allocations
    int total = 0;      // count of successful allocations

    for(int i = 0; i < N; ++i){
        if(!is_valid_rnti(array[i]->rxUeInformationTag.RNTI)) continue;  // validate RNTI

        array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if(array[i] == NULL) {
            printf("Memory allocation failed!\n");
            continue;
        }

        array[i]->rxUeInformationTag.RNTI = i + 1000;  // Set RNTI to valid value

        if(random_flag){
            array[i]->crcIndicationRel8Tag.CRCFLAG = rand() % 2;  // Randomly set CRCFLAG
        } else {
            array[i]->crcIndicationRel8Tag.CRCFLAG = 0;  // Set CRCFLAG to zero for testing purposes
        }

        addNode(&head, array[i]);  // Track successful allocation

        total++;   // Increment successful count
    }

    return total;
}
```
Please make sure to replace the `is_valid_rnti(int rnti)` function with your actual external data source call for validating `RNTI`. Also, please note that this code does not handle memory deallocation properly when it comes to error cases. It's always a good practice to free up the dynamically allocated memory you no longer need.
