#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct Event {
    int id;
    time_t timestamp;
    // Add other parameters as required
    int processed;
} Event;

typedef struct EventCollection {
    Event **events;
    size_t size;
    pthread_mutex_t lock;
} EventCollection;

Event *new_event(int id) {
    Event *e = malloc(sizeof(*e));
    e->id = id;
    time(&e->timestamp);
    e->processed = 0;
    return e;
}

void init_collection(EventCollection *c, size_t initialSize) {
    c->events = malloc(sizeof(*c->events)*initialSize);
    c->size = initialSize;
    pthread_mutex_init(&c->lock, NULL);
}

void add_event(EventCollection *c, Event *e) {
    pthread_mutex_lock(&c->lock);

    // Check if event already exists in collection
    for (size_t i = 0; i < c->size; ++i) {
        if (c->events[i] != NULL && c->events[i]->id == e->id) {
            pthread_mutex_unlock(&c->lock);
            return;
        }
    }

    // Resize array if necessary
    for (size_t i = 0; i < c->size; ++i) {
        if (c->events[i] == NULL) {
            c->events[i] = e;
            pthread_mutex_unlock(&c->lock);
            return;
        }
    }

    // Resize array
    size_t newSize = 2 * c->size;
    Event **newEvents = malloc(sizeof(*newEvents) * newSize);
    for (size_t i = 0; i < c->size; ++i) {
        newEvents[i] = c->events[i];
    }

    free(c->events);
    c->events = newEvents;
    c->events[c->size++] = e;

    pthread_mutex_unlock(&c->lock);
}

// Similarly, implement update_event and mark_processed functions
```

