node_t *head = NULL;
size_t count = 0;

/* Implement custom memory pool to avoid fragmentation */
#define POOLSIZE 1024*1024 // or whatever size you deem appropriate
static char memory[POOLSIZE];
static int availableMemory = POOLSIZE;
static void *memoryPointer = memory;

void* allocate(size_t n) {
    pthread_mutex_lock(&lock);
    if (availableMemory < n) {
        // handle out of memory condition here, e.g., return NULL or abort
    }

    void *allocated = memoryPointer;
    memoryPointer += n;
    availableMemory -= n;

    pthread_mutex_unlock(&lock);
    return allocated;
}

node_t* createNode(record_t data) {
    node_t* newNode = allocate(sizeof(node_t));
    if (newNode == NULL) 
        return NULL; // handle out of memory condition here

    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void insert(record_t record) {
    node_t* node = createNode(record);
    if (node == NULL) 
        return; // handle out of memory condition here

    pthread_mutex_lock(&lock);
    node->next = head;
    head = node;
    count++;
    pthread_mutex_unlock(&lock);
}

void delete(int key) {
    pthread_mutex_lock(&lock);
    node_t **ptr = &head;

    while (*ptr != NULL) {
        if ((*ptr)->data.key == key) {
            node_t *temp = *ptr;
            *ptr = temp->next;
            count--;

            // return allocated memory to the pool here if necessary
            free(temp); 
            break;
        }

        ptr = &(*ptr)->next;
    }

    pthread_mutex_unlock(&lock);
}

/* Implement a mechanism to verify uniqueness and handle collisions */
int isUnique(record_t record) {
    node_t* currentNode = head;

    while (currentNode != NULL) {
        if (currentNode->data.value == record.value || 
            currentNode->data.key == record.key) 
             return 0; // collision detected, values are not unique

        currentNode = currentNode->next;
    }

    return 1; // no collisions found, values are unique
}
```

