['Here's an example implementation with Node.js:

```javascript
const fs = require('fs');
const path = require('path');
const readline = require('readline');

class FileReader {
    constructor(cacheLimit = 100, timeout = 5000) {
        this.cache = {};
        this.timeout = timeout;
        this.cacheLimit = cacheLimit;
    }

    async readFile(filePath, extension) {
        return new Promise((resolve, reject) => {
            const stat = fs.statSync(filePath);

            if (this.cache[filePath] && Date.now() - this.cache[filePath].timestamp < 1000 * 60 * 5 ) {
                resolve(this.cache[filePath].content);
            } else if (!fs.existsSync(filePath)) {
                reject('File does not exist');
            } else if (stat.size > 1e+7) { // 10 MB in bytes
                console.warn("File size exceeds limit");
                resolve('');
            } else {
                const startTime = Date.now();

                readline.createInterface({
                    input: fs.createReadStream(filePath),
                    crlfDelay: Infinity
                })
                .on('line', (line) => {
                    if (!this.cache[filePath]) {
                        this.cache[filePath] = { content: '', timestamp: Date.now() };
                    }

                    if(extension === '.txt'){
                        this.cache[filePath].content += line + '\n';
                    } else if (extension === '.json'){
                        try{
                            const jsonObject = JSON.parse(line);
                            this.cache[filePath].content.push(jsonObject);
                        } catch(err){
                            console.error('Error parsing JSON:', err)
                        }
                    } else if (extension === '.csv') {
                        this.cache[filePath].content += line + '\n';
                    }
                })
                .on('close', () => {
                    const endTime = Date.now();

                    if(endTime - startTime > this.timeout){
                       console.warn("Operation timed out");
                    } else{
                        resolve(this.cache[filePath].content);
                    }
                });
            }

            // clear cache when it reaches the limit
            if (Object.keys(this.cache).length > this.cacheLimit) {
                let oldestKey = null;
                let oldestTime = Date.now();

                for (let key in this.cache) {
                    if (this.cache[key].timestamp < oldestTime){
                        oldestKey = key;
                        oldestTime = this.cache[key].timestamp;
                    }
                }

                delete this.cache[oldestKey];
            }
        });
    }
}
```
You can use the `FileReader` class as follows:

```javascript
const fileReader = new FileReader();
fileReader.readFile('path_to_your_file', '.txt') // replace with your actual path and extension
    .then(content => console.log(content))
    .catch(err => console.error(err));
```
The `FileReader` class caches the contents of files read from a directory, reducing redundant reads for frequently accessed files. It supports different file types like `.txt`, `.json` and `.csv`. If a timeout occurs while reading, it logs a warning message. The function gracefully degrades under high-load conditions by caching recently accessed files instead of trying to read them from disk, thus reducing the possibility of crashing due to excessive file system operations. It also supports easy extensibility as future file types can be added as per need without modifying the core logic.
