// but this gives you an idea of how you might start implementing it.
PacketHeader **packetHeaders = NULL;
size_t numEntries = 0;
pthread_mutex_t lock; // for synchronization

void initArray(size_t maxNumEntries) {
    pthread_mutex_init(&lock, NULL);
    packetHeaders = malloc(maxNumEntries * sizeof(PacketHeader*));
}

int addEntryToArray(const PacketHeader *header) {
    pthread_mutex_lock(&lock);
    if (numEntries >= maxNumEntries) {
        // Resize the array
        packetHeaders = realloc(packetHeaders, 2*maxNumEntries*sizeof(PacketHeader*));
        if (!packetHeaders) {
            pthread_mutex_unlock(&lock);
            return -1; // failed to allocate memory
        }
    }

    packetHeaders[numEntries] = malloc(sizeof(PacketHeader));
    memcpy(packetHeaders[numEntries], header, sizeof(PacketHeader));
    numEntries++;
    pthread_mutex_unlock(&lock);
    return 0;
}

void freeArray() {
    for (size_t i = 0; i < numEntries; ++i) {
        free(packetHeaders[i]->payloadIdentifier);
        free(packetHeaders[i]);
    }
    free(packetHeaders);
    pthread_mutex_destroy(&lock);
}
```

This code just creates an array of PacketHeader pointers that can be expanded dynamically. It uses a mutex to ensure thread safety during addition and resizing operations. The function `freeArray()` is used to clean up all memory when the packet header array is no longer needed. 

