    if (array.totalPayloadSize + payloadLength > array.payloadLimit) {
        // Handle case where the total size of the payload exceeds the limit. 
        printf("Warning: Total payload size exceeded the limit.\n");
    } else {
        if (array.size == array.capacity) {
            // If capacity is reached, reallocate with doubled capacity.
            PacketHeader* newHeaders = realloc(array.headers, 2 * array.capacity * sizeof(PacketHeader));
            if (!newHeaders) {
