["Here is a high-level overview of how such a system could be implemented in Java. Note that full implementation would require considerable effort and details about specific requirements including how to handle different types of configuration parameters, how to serialize/deserialize them, what kind of exceptions you expect etc. 

```java
import java.util.concurrent.*;
import java.time.*;
import java.io.*;

public class ConfiguredParametersManager {

    private static final int DEFAULT_SIZE = 10;

    //Concurrency control for updates, e.g., compareAndSet 
    private final AtomicReference<ConfigurationMap> configurationMapRef = new AtomicReference<>(new ConfigurationMap());

    public ConfiguredParametersManager() { }

    public void put(String name, Object defaultValue) {
        //Concurrency control for updates, e.g., compareAndSet 
        ConfigurationMap oldConfigurationMap, newConfigurationMap;
        do {
            oldConfigurationMap = configurationMapRef.get();
            newConfigurationMap = new ConfigurationMap(oldConfigurationMap);
            newConfigurationMap.put(name, defaultValue);
        } while(!configurationMapRef.compareAndSet(oldConfigurationMap, newConfigurationMap));
    }

    public Object getCurrentValue(String name) {
        return configurationMapRef.get().get(name).getValue(); 
    }

    //other methods for updates and reads...
}

class ConfigurationParameter<T> {
    private T defaultValue;
    private volatile T currentValue;
    private final ZonedDateTime timestamp = ZonedDateTime.now();

    public ConfigurationParameter(T defaultValue) { 
        this.defaultValue = defaultValue;
        this.currentValue = defaultValue;
    }

    //getters and setters...
}

class ConfigurationMap {
    private final ConcurrentHashMap<String, ConfigurationParameter> map;

    public ConfigurationMap() { 
        this(ConfiguredParametersManager.DEFAULT_SIZE);
    }

    public ConfigurationMap(int initialCapacity) {
        this.map = new ConcurrentHashMap<>(initialCapacity);
    }

    //copy constructor...

    public void put(String name, Object defaultValue) {
        map.putIfAbsent(name, new ConfigurationParameter(defaultValue)); 
    }

    public ConfigurationParameter get(String name) {
        return map.get(name);
    }
