#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    time_t timestamp; // For TTL-based cleanup mechanism
    struct NFAPI_CRC_INDICATION_PDU* next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // For thread safety
size_t maxSize = 1024; // Maximum size constraint, adjust as needed
time_t ttl = 3600; // Time to live for cleanup, in seconds

void* allocate(size_t size) {
    return malloc(size);
}

void deallocate(void* ptr) {
    free(ptr);
}

int addElement(NFAPI_CRC_INDICATION_PDU_T* newElement) {
    pthread_mutex_lock(&lock); // Lock to ensure thread safety

    size_t size = 0;
    for (NFAPI_CRC_INDICATION_PDU_T* current = head; current != NULL; current = current->next) {
        size++;
    }

    if (size >= maxSize) { // Check if maximum size has been reached
        pthread_mutex_unlock(&lock);
        return -1; // Return error code indicating list is full
    }

    newElement->timestamp = time(NULL); // Set timestamp for TTL cleanup mechanism
    newElement->next = head; 
    head = newElement;

    pthread_mutex_unlock(&lock); // Unlock to allow other threads to access the list

    return 0;
}

void cleanup() {
    time_t currentTime = time(NULL);
    pthread_mutex_lock(&lock);

    while (head != NULL && currentTime - head->timestamp > ttl) { // Check if head is outdated
        NFAPI_CRC_INDICATION_PDU_T* temp = head;
        head = head->next;
        deallocate(temp); // Free memory of the old element
    }

    pthread_mutex_unlock(&lock);
}
```

