    unsigned long total_data_size;
    order_t *order_list;
} NFAPI_MESSAGE_T;

NFAPI_MESSAGE_T *initialize_memory(unsigned int N, unsigned int max_segments, unsigned seed) {
    srand(seed); // Seed for random number generation.

    NFAPI_MESSAGE_T *mem = (NFAPI_MESSAGE_T *)calloc(N, sizeof(NFAPI_MESSAGE_T));
    if (!mem) return NULL; // Memory allocation failed.

    int last_flag = -1;
    for (unsigned int i = 0; i < N; ++i) {
        unsigned long total_data_size = 0UL;

        mem[i].order_list = malloc(max_segments * sizeof(order_t));
        if (!mem[i].order_list) goto cleanup; // Memory allocation failed.

        for (unsigned int j = 0; j < max_segments; ++j) {
            unsigned long data_size = rand() % 16384UL + 1UL; // Random PDU size in the range of [1, 16K].
            total_data_size += data_size;

            mem[i].order_list[j].price = 1.0 + (rand() / (RAND_MAX / 99.0)); // Random price in the range of [$1.00, $100.00].

            snprintf(mem[i].order_list[j].product_name, sizeof(mem[i].order_list[j].product_name), "Product %u", j + 1); // Generate product name.
        }

        mem[i].total_data_size = total_data_size;

        int new_flag;
        do {
            new_flag = rand();
        } while (new_flag == last_flag);

        mem[i].CRCFLAG = new_flag;
    }

    return mem; // Successfully initialized memory.

cleanup:
    for (unsigned int i = 0; i < N; ++i) {
        if (mem[i].order_list) free(mem[i].order_list);
    }

    free(mem);
    return NULL; // Memory allocation failed.
}
