['Here's a very basic implementation using C in Linux environment. It won't cover all aspects as described above due to its complexity but it provides you with a starting point.

```c
#include <stdio.h>
#include <stdlib.h>
#include "jansson.h"

typedef struct node {
    char key;
    double value;
    struct node *left, *right;
} Node;

Node* new_node(char item, double val) {
    Node *temp = (Node *)malloc(sizeof(Node));
    temp->key = item;
    temp->value = val;
    temp->left = temp->right = NULL;
    return temp;
}

Node* insert_node(Node* node, char key, double value) {
    if (node == NULL) 
        return new_node(key, value);
    if (key < node->key)
        node->left  = insert_node(node->left, key, value);
    else if (key > node->key)
        node->right = insert_node(node->right, key, value);
    return node;
}

void inorderTraversal(Node *root) {
    if (root != NULL) {
        inorderTraversal(root->left);
        printf("%c:%.2lf ", root->key, root->value);
        inorderTraversal(root->right);
    }
}

Node* minValueNode(Node* node) {
    Node* current = node;
    while (current && current->left != NULL)
        current = current->left;
    return current;
}

Node* delete_node(Node* root, char key) {
    if (root == NULL) 
        return root;
    if (key < root->key)
        root->left = delete_node(root->left, key);
    else if( key > root->key )
        root->right = delete_node(root->right, key);
    else {
        if (root->left == NULL) {
            Node *temp = root->right;
            free(root);
            return temp;
        } 
        else if (root->right == NULL) {
            Node *temp = root->left;
            free(root);
            return temp;
        }

        Node* temp = minValueNode(root->right);
        root->key = temp->key;
        root->value = temp->value;
        root->right = delete_node(root->right, temp->key);
    }
    return root;
}

char* treeToJson(Node *tree) {
    json_t *json = json_object();
    if (tree != NULL) {
        json_object_set_new(json, "Key", json_string(&(tree->key)));
        json_object_set_new(json, "Value", json_real(tree->value));

        json_t *leftJson = treeToJson(tree->left);
        if (leftJson != NULL) {
            json_object_set_new(json, "Left", leftJson);
        }

        json_t *rightJson = treeToJson(tree->right);
        if (rightJson != NULL) {
            json_object_set_new(json, "Right", rightJson);
        }
    }

    return json_dumps(json, JSON_INDENT(2));
}
```
This is a basic binary search tree implementation. There's no logging, error handling or adaptations to different data sources in place. Implementing these would greatly increase the complexity of this example and make it much more difficult to understand. Please note that you need to link against libjansson for this code to work (`-ljansson` flag).
']

