    int uniqueId;
} AllocatedStructure;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int uniqueId = 0;

void* allocateMemoryWithRetries(size_t size, int retryLimit) {
    void* memoryPtr = NULL;
    int retries = 0;

    while (memoryPtr == NULL && retries < retryLimit) {
        pthread_mutex_lock(&mutex);
        memoryPtr = malloc(size);
        pthread_mutex_unlock(&mutex);

        if (memoryPtr != NULL) {
            memset(memoryPtr, 0, size);
            return memoryPtr;
        } else {
            retries++;
        }
    }

    // Memory allocation failed, clean up and return error.
    pthread_mutex_lock(&mutex);
    if (memoryPtr != NULL) free(memoryPtr);
    pthread_mutex_unlock(&mutex);

    return NULL;  // Returning NULL indicates that memory allocation failed.
}

