['```C
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char mac[18];
    char ip[16];
    char subnetMask[16];
} NetworkConfig;

typedef struct node_t {
    NetworkConfig* config;
    struct node_t* next;
    pthread_mutex_t lock;
} Node;

Node* list = NULL;
pthread_mutex_t listLock = PTHREAD_MUTEX_INITIALIZER;

int validateAndAdd(char* mac, char* ip, char* subnetMask) {
    pthread_mutex_lock(&listLock);

    Node* tempNode = list;
    while (tempNode != NULL) {
        if ((strcmp(mac, tempNode->config->mac) == 0 && strlen(mac) > 0) ||
            (strcmp(ip, tempNode->config->ip) == 0 && strlen(ip) > 0)) {
            pthread_mutex_unlock(&listLock);
            return 1; // Already exists or collision detected.
        }
        tempNode = tempNode->next;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        pthread_mutex_unlock(&listLock);
        return -1; // Out of memory error.
    }

    newNode->config = (NetworkConfig*)malloc(sizeof(NetworkConfig));
    strcpy(newNode->config->mac, mac);
    strcpy(newNode->config->ip, ip);
    strcpy(newNode->config->subnetMask, subnetMask);

    pthread_mutex_init(&newNode->lock, NULL);
    newNode->next = list;
    list = newNode;

    pthread_mutex_unlock(&listLock);

    return 0; // Successfully added.
}

// The function to call periodically from the external network configuration service.
void updateFromService() {
    char mac[18], ip[16], subnetMask[16];

    while (1) {
        /* 
         * Fetch MAC, IP and Subnet Mask from the network configuration service.
         */

        int status = validateAndAdd(mac, ip, subnetMask);

        if (status == 0) {
            printf("Configuration added successfully.\n");
        } else if (status == 1) {
            printf("Conflict or duplicate configuration detected. Skipping...\n");
        } else if (status == -1) {
            printf("Out of memory error occurred. Please free up some space and try again.\n");
        }
    }
}
```
