using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.IO;
using Newtonsoft.Json;

public class DatabaseConfig
{
    public string ServerAddress { get; set; }
    public int Port { get; set; }
    public string DatabaseName { get; set; }
    public string Username { get; set; }
    public string Password { get; set; }
}

public class ConnectionPoolManager
{
    private readonly List<SqlConnection> connectionPool = new();
    private const int MaxConnections = 10;  // Adjust this according to your requirements.

    public bool ConfigureDatabaseConnection(string directoryPath)
    {
        string filePath = Path.Combine(directoryPath, "database-config.json");

        if (!File.Exists(filePath))
            return false;

        string jsonString = File.ReadAllText(filePath);
        List<DatabaseConfig> databaseConfigs = JsonConvert.DeserializeObject<List<DatabaseConfig>>(jsonString);

        foreach (var config in databaseConfigs)
        {
            if (connectionPool.Count >= MaxConnections)
                return false;  // Connection pool is full, can't add more connections.

            string connectionString = $"Server={config.ServerAddress},{config.Port};Database={config.DatabaseName};User Id={config.Username};Password={config.Password};";

            try
            {
                using (SqlConnection connection = new SqlConnection(connectionString))
                {
                    connection.Open();  // Test the connection before adding it to the pool.

                    if (connection.State == System.Data.ConnectionState.Open)
                        connectionPool.Add(connection);
                    else
                        Console.WriteLine("Invalid Connection");
                }
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error: {e.Message}");
            }
        }

        return true;
    }

    // You can add methods for iterating over the connection pool and updating specific configurations here.
    // These methods should handle any necessary synchronization to avoid connectivity issues.
}
```

