    std::mutex mtx; // mutex to protect data access

public:
    void addHeader(const PacketHeader& header) {
        std::lock_guard<std::mutex> lock(mtx); // lock before adding a header
        // Check for duplicates (not considering flags and payload length)
        for (auto& h : headers) {
            if (h.seq_num == header.seq_num) {
                // Handle duplicate sequence number gracefully, e.g., ignore the new one
                return;
            }
        }
        // Add a new header safely
        headers.push_back(header);
    }

    PacketHeader getHeaderBySeqNum(int seq_num) {
        std::lock_guard<std::mutex> lock(mtx); // lock before accessing the vector
        for (auto& h : headers) {
            if (h.seq_num == seq_num) {
                return h;
            }
        }
        throw std::runtime_error("No header with given sequence number");
    }

    void removeHeader(int seq_num) {
        std::lock_guard<std::mutex> lock(mtx); // lock before modifying the vector
        for (auto it = headers.begin(); it != headers.end(); ++it) {
            if (it->seq_num == seq_num) {
                headers.erase(it);
                break;
            }
        }
    }

    // Add compression and decompression functions here, e.g., 
    // PacketHeader compress(const PacketHeader& header), etc.
};
```
