```c
#include <pthread.h>
#include <resolv.h>
#include <time.h>

typedef struct {
    time_t expiry;
    u_char ip[4];
} dnsCacheEntry;

dnsCacheEntry *dns_cache = NULL;
pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;
int cacheSize = 0;
time_t ttl = 60; // default time to live (in seconds)

u_char* resolveDNS(const char *hostname){
    pthread_mutex_lock(&cacheMutex);

    for(int i=0; i< cacheSize; ++i){
        if(dns_cache[i].expiry < time(NULL)){ // entry expired, refresh DNS resolution
            res_init(); 

            unsigned char answer[4];
            int ret = dn_expand(hostname, strlen(hostname), (unsigned char*)answer, sizeof(answer));
            if(ret != -1){
                memcpy(&dns_cache[i].ip, &answer, 4);
                dns_cache[i].expiry = time(NULL) + ttl; // update expiry of cache entry

                pthread_mutex_unlock(&cacheMutex);
                return dns_cache[i].ip;
            } else {
                fprintf(stderr, "Error resolving DNS for %s\n", hostname);
                exit(1); // or handle this error in other way suitable for your application
            }
        } 
    }

    pthread_mutex_unlock(&cacheMutex);

    // if not found in cache, perform a new DNS resolution and add it to cache
    res_init();

    unsigned char answer[4];
    int ret = dn_expand(hostname, strlen(hostname), (unsigned char*)answer, sizeof(answer));

    if(ret != -1){
        pthread_mutex_lock(&cacheMutex);

        // resize the cache array to accommodate new entry
        dns_cache = realloc(dns_cache, ++cacheSize * sizeof(*dns_cache));
        memcpy(&dns_cache[cacheSize-1].ip, &answer, 4);
        dns_cache[cacheSize-1].expiry = time(NULL) + ttl; // update expiry of cache entry

        pthread_mutex_unlock(&cacheMutex);
        return dns_cache[cacheSize-1].ip;
    } else {
        fprintf(stderr, "Error resolving DNS for %s\n", hostname);
        exit(1); // or handle this error in other way suitable for your application
    }
}
```

