NFAPI_CRC_INDICATION_PDU_T** generate_pdus(size_t size, int rnti_range) {
    srand((unsigned int)time(NULL)); // Initialize random seed

    NFAPI_CRC_INDICATION_PDU_T** pdus = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (pdus == NULL) {
        return NULL; // Handle memory allocation error...
    }

    int* usedRNTIs = calloc(rnti_range, sizeof(int));
    if (usedRNTIs == NULL) {
        free(pdus);
        return NULL; // Handle memory allocation error...
    }

    for (size_t i = 0; i < size; ++i) {
        pdus[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdus[i] == NULL) {
            // Handle memory allocation error...
            for (size_t j = 0; j < i; ++j) {
                free(pdus[j]);
            }
            free(usedRNTIs);
            return NULL;
        }

        int rnti;
        do {
            rnti = rand() % rnti_range; // Generate a random RNTI within the range.
        } while (usedRNTIs[rnti]);

        usedRNTIs[rnti] = 1; // Mark this RNTI as used.
        pdus[i]->RNTI = rnti;  // Set the RNTI for this PDU_T...
    }

    free(usedRNTIs);
    return pdus;
}
