typedef struct {
    unsigned long timestamp;  // for simplicity, this could be replaced with a more suitable type
    char source_ip[16];       // assuming IPV4 address represented as dotted decimal string
} PacketMetadataEntry;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
PacketMetadataEntry* packetEntries = NULL;
int numEntries = 0;
int maxSize = 0;

void managePacketStream(PacketMetadataEntry entry) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < numEntries; ++i) {
        if (packetEntries[i].timestamp == entry.timestamp && strcmp(packetEntries[i].source_ip, entry.source_ip) == 0) {
            pthread_mutex_unlock(&lock);
            return; // duplicate detected, ignore this packet
        }
    }

    if (numEntries >= maxSize) {  // need to resize the array
        maxSize = maxSize * 2 + 1;   // arbitrary growth strategy
        packetEntries = realloc(packetEntries, maxSize * sizeof(*packetEntries));
        if (!packetEntries) {
            fprintf(stderr, "Failed to allocate memory\n");
            exit(EXIT_FAILURE);  // or handle error appropriately for your application
        }
    }

    packetEntries[numEntries++] = entry;

    pthread_mutex_unlock(&lock);
}
