typedef struct NetworkInterfaceStatus {
    int InterfaceID;
    float BandwidthPart;
    char *MeasurementResults;
} NetworkInterfaceStatus;

typedef struct Array {
    pthread_mutex_t lock;
    size_t count;
    size_t capacity;
    NetworkInterfaceStatus *data;
} Array;

void initArray(Array *array) {
    array->count = 0;
    array->capacity = 16;  // Initial capacity.
    array->data = malloc(sizeof(NetworkInterfaceStatus) * array->capacity);
    pthread_mutex_init(&array->lock, NULL);
}

void addEntry(Array *array, NetworkInterfaceStatus entry) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        // Resize the array.
        array->capacity *= 2;
        array->data = realloc(array->data, sizeof(NetworkInterfaceStatus) * array->capacity);
    }

    array->data[array->count++] = entry;  // Add the new entry.

    pthread_mutex_unlock(&array->lock);
}

void updateEntry(Array *array, int interfaceID, NetworkInterfaceStatus updated) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->data[i].InterfaceID == interfaceID) {
            // Update the existing entry.
            memcpy(&array->data[i], &updated, sizeof(NetworkInterfaceStatus));
            break;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

NetworkInterfaceStatus *getEntry(Array *array, int interfaceID) {
