```python
import numpy as np
from statistics import mean, median, stdev
from collections import deque
from concurrent.futures import ThreadPoolExecutor
from requests.exceptions import RequestException
import requests

class DataProcessor:
    def __init__(self, window_size):
        self.window = deque(maxlen=window_size)
        self.paused = False

    def process_data(self, data):
        if not self.paused and len(self.window) < self.window.maxlen:
            self.window.append(data)
            return True  # Data processed successfully
        elif not self.paused:
            return False  # Window is full, could not process data
        else:
            return None  # Processing paused, did not process any data

    def aggregate_metrics(self):
        if len(self.window) == 0:
            return {'mean': None, 'median': None, 'std_dev': None}
        else:
            return {
                'mean': mean(self.window),
                'median': median(self.window),
                'std_dev': stdev(self.window) if len(self.window) > 1 else float('nan')
            }

    def pause(self):
        self.paused = True

    def resume(self):
        self.paused = False

class DataFetcher:
    def __init__(self, api_url):
        self.api_url = api_url

    def fetch_data(self):
        try:
            response = requests.get(self.api_url)
            if response.status_code == 200:
                return response.json()['data']  # Assuming API returns a JSON with the data in 'data' field
            else:
                print(f"Failed to fetch data, status code: {response.status_code}")
                return None
        except RequestException as e:
            print(f"Request Exception encountered while fetching data: {e}")
            return None

class Enricher:
    def __init__(self, api_url):
        self.api_url = api_url

    def enrich_data(self, data):
        try:
            response = requests.post(self.api_url, json={'data': data})
            if response.status_code == 200:
                return response.json()['enriched_data']  # Assuming API returns a JSON with the enriched data in 'enriched_data' field
            else:
                print(f"Failed to enrich data, status code: {response.status_code}")
                return None
        except RequestException as e:
            print(f"Request Exception encountered while enriching data: {e}")
            return None
```
