typedef struct {
    int pci;
} NFAPI_RXUEINFO_PDU_T;

int isPCIUnique(NFAPI_RXUEINFO_PDU_T* array, int size, int pci) {
    for (int i = 0; i < size; ++i) {
        if (array[i].pci == pci) return 0;
    }
    return 1;
}

NFAPI_RXUEINFO_PDU_T* allocate_rxueinfo_array(size_t num_elements, FILE* log_file, int threshold, const int* whitelist, size_t whitelistSize) {
    srand(time(0));

    NFAPI_RXUEINFO_PDU_T* array = NULL;
    size_t totalReceivedPower = 0;

    for (int attempt = 0; attempt < 3; ++attempt) {
        array = realloc(array, num_elements * sizeof(NFAPI_RXUEINFO_PDU_T));
        if (!array) {
            fprintf(log_file, "Memory allocation failed\n");
            return NULL;
        }

        for (size_t i = 0; i < num_elements; ++i) {
            int pci = rand();

            while(!isPCIUnique(array, i, pci) || memchr(whitelist, pci, sizeof(*whitelist)*whitelistSize)) {
                pci = rand();
            }

            int rxPowerLevel = (rand() % 10) + 1; // random RX power level between 1 and 10

            while ((totalReceivedPower + rxPowerLevel) > threshold) {
                rxPowerLevel = (rand() % 10) + 1; // regenerate if exceeds threshold
            }

            totalReceivedPower += rxPowerLevel;

            array[i].pci = pci;
        }
    }

    return array;
}
```
