<?php
require 'vendor/autoload.php'; // Path to your autoloader file
use GuzzleHttp\Client;
use GuzzleHttp\Exception\RequestException;
use Symfony\Component\Cache\Adapter\FilesystemAdapter;

class AppConfig {
    private $cache;
    private $client;
    private $base_url;

    public function __construct() {
        $this->client = new Client();
        $this->base_url = getenv('API_BASE_URL') ?: 'http://localhost'; // You might use different URLs based on the environment
        $this->cache = new FilesystemAdapter(namespace:'', defaultLifetime: 3600); // Adjust default lifetime to your needs
    }

    public function getConfig($key) {
        $item = $this->cache->getItem($key);
        if (!$item->isHit()) {
            try {
                $response = $this->client->request('GET', $this->base_url . '/' . $key);
                if ($response->getStatusCode() === 200) {
                    $config = json_decode($response->getBody(), true); // Assuming the API returns JSON data
                    $item->set($config);
                    $this->cache->save($item);
                } else {
                    echo 'Error: Unable to fetch config from server';
                }
            } catch (RequestException $e) {
                echo 'Error: Network issue. Could not reach the server. ' . $e->getMessage();
            }
        }
        return $item->get();
    }
}
?>
```
