['Here's an example implementation in C, using the POSIX Threads (pthreads) library to handle concurrency and error handling functions from the standard library to manage errors:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>

// Third-party library functions
void* third_party_transform(const char *data);
int third_party_get_size(void *third_party_obj);

// External data service function
char* get_metadata(const char *entry);

#define BUFFER_SIZE 1024

typedef struct {
    pthread_mutex_t lock;
    int fd;
} file_info_t;

file_info_t open_file(const char* filename) {
    file_info_t info;

    if (pthread_mutex_init(&info.lock, NULL) != 0) {
        perror("Mutex init failed");
        exit(EXIT_FAILURE);
    }

    int fd = open(filename, O_RDONLY);

    if (fd == -1) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    info.fd = fd;
    return info;
}

void close_file(file_info_t* info) {
    if (close(info->fd) == -1) {
        perror("Failed to close file");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_destroy(&info->lock);
}

char* read_line(file_info_t* info) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    pthread_mutex_lock(&info->lock);
    bytes_read = read(info->fd, buffer, BUFFER_SIZE - 1);
    pthread_mutex_unlock(&info->lock);

    if (bytes_read == -1) {
        perror("Failed to read from file");
        exit(EXIT_FAILURE);
    } else if (bytes_read == 0) {
        return NULL; // End of File
    }

    buffer[bytes_read] = '\0';

    return strdup(buffer);
}

void process_file(const char* filename, const char *option) {
    file_info_t info = open_file(filename);
    int line = 1;

    while (1) {
        char* data = read_line(&info);

        if (data == NULL) break; // End of File

        printf("Processing line %d: ", line++);

        void *third_party_obj = third_party_transform(data);

        // Handle errors in the third-party library
        if (third_party_obj == NULL) {
            perror("Failed to transform data");
            continue;
        }

        int size = third_party_get_size(third_party_obj);
        printf("%d bytes processed.\n", size);

        // Integration with external service
        char* metadata = get_metadata(data);

        if (metadata == NULL) {
            perror("Failed to fetch metadata");
        } else {
            printf("Metadata: %s\n", metadata);
            free(metadata);
        }

        free(third_party_obj);
        free(data);
    }

    close_file(&info);
}
```

In this code, we're using a thread-safe file reading function that locks the mutex before reading from the file and unlocks it afterwards. We also have error handling for each operation in the external library or the metadata service. 

If the third party library fails to transform data, or if fetching metadata is unsuccessful, the program will print an error message and continue with the next line of the file. If a file cannot be opened or read from, the program will exit with an error message.
']

