    int RNTI;
    float CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex[MAX_BUFFERS];
NFAPI_CRC_INDICATION_PDU_T* buffer[MAX_BUFFERS];
int currentSize[MAX_BUFFERS] = {0};
int maxSize = MAX_SIZE; // initial size of buffer array

void initBuffers() {
    srand(time(NULL));
    for (int i = 0; i < MAX_BUFFERS; ++i) {
        if (pthread_mutex_init(&mutex[i], NULL) != 0) {
            perror("Mutex initialization failed");
            exit(1);
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocateMemory() {
    NFAPI_CRC_INDICATION_PDU_T* ptr = NULL;

    for (int i = 0; i < MAX_BUFFERS; ++i) {
        if (currentSize[i] >= maxSize && pthread_mutex_trylock(&mutex[i]) == 0 ){
            ptr = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

            if (ptr != NULL) {
                buffer[i] = ptr;
                currentSize[i]++;

                // Log successful memory allocation
                printf("Successfully allocated memory for structure in buffer %d\n", i);
                return ptr;
            } else {
                perror("Memory allocation failed");
                exit(1);
            }
        }
    }

    // Resize buffers if all are full
    if (ptr == NULL) {
        maxSize *= 2;  // increase buffer size by doubling it

        for (int i = 0; i < MAX_BUFFERS; ++i){
            pthread_mutex_lock(&mutex[i]);

            NFAPI_CRC_INDICATION_PDU_T* newBuffer = realloc(buffer[i], maxSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (newBuffer != NULL) {
                buffer[i] = newBuffer;
                ptr = &buffer[i][currentSize[i]];
                currentSize[i]++;

                // Log successful memory allocation after resizing
                printf("Successfully allocated memory for structure in buffer %d after resize\n", i);
            } else {
                perror("Memory reallocation failed");
                exit(1);
            }

            pthread_mutex_unlock(&mutex[i]);
        }
    } 

    return ptr;
}
```
This code demonstrates how to handle memory allocation and resizing dynamically. Note that this is a simplified demonstration of your problem and does not include the signal strength calculations, logging mechanisms or background threading required in the full solution. Furthermore, it's important to remember to release memory when you're done with it to prevent memory leaks.
