['Here is a simplified representation of the `SessionState` structure in C along with the function to handle this collection:

```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct SessionState {
    int clientID;
    double sessionDuration;  // duration in seconds
    time_t lastActiveTimestamp;
    bool connectionStatus;
} SessionState;

typedef struct SessionCollection {
    pthread_mutex_t mutex;
    SessionState **sessions;
    size_t size, capacity;
} SessionCollection;

SessionCollection* createCollection(size_t initialSize) {
    SessionCollection *collection = malloc(sizeof(*collection));
    if (!collection) return NULL;

    collection->capacity = initialSize > 0 ? initialSize : 1;
    collection->sessions = calloc(initialSize, sizeof(*collection->sessions));
    if (!collection->sessions) {
        free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->mutex, NULL);
    collection->size = 0;

    return collection;
}

bool addSession(SessionCollection *collection, SessionState *session) {
    if (!collection || !session) return false;

    pthread_mutex_lock(&collection->mutex);
    if (collection->size == collection->capacity) {
        size_t newCapacity = collection->capacity ? collection->capacity * 2 : 1;
        SessionState **newSessions = realloc(collection->sessions, sizeof(*newSessions) * newCapacity);
        if (!newSessions) {
            pthread_mutex_unlock(&collection->mutex);
            return false;
        }

        collection->capacity = newCapacity;
        collection->sessions = newSessions;
    }

    collection->sessions[collection->size++] = session;
    pthread_mutex_unlock(&collection->mutex);
    return true;
}

SessionState* getSession(SessionCollection *collection, size_t index) {
    if (!collection || index >= collection->size) return NULL;

    SessionState *session = NULL;
    pthread_mutex_lock(&collection->mutex);
    session = collection->sessions[index];
    pthread_mutex_unlock(&collection->mutex);

    return session;
}

void updateSession(SessionCollection *collection, size_t index, SessionState *session) {
    if (!collection || !session || index >= collection->size) return;

    pthread_mutex_lock(&collection->mutex);
    collection->sessions[index] = session;
    pthread_mutex_unlock(&collection->mutex);
}
```
The provided code is a simplified implementation and does not include error checking or other production level considerations such as handling corrupt data, secure memory management, handling concurrent access from multiple threads, etc. But this provides the basic idea of how to manage dynamic collections in C. It uses mutexes for thread safety. The realloc() function handles the case where there is no more room left in our array and we need to allocate more space.
