typedef struct {
    // Your data here...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    int index;
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct ListNode *next;
} ListNode;

typedef struct {
    pthread_mutex_t lock;
    ListNode *head;
    size_t maxSize;
    size_t currentSize;
} DynamicList;

DynamicList* createDynamicList(size_t maxSize) {
    DynamicList* list = malloc(sizeof(DynamicList));
    assert(list != NULL);

    list->head = NULL;
    list->maxSize = maxSize;
    list->currentSize = 0;

    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void addToList(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T *data) {
    assert(list != NULL && data != NULL);

    pthread_mutex_lock(&list->lock);

    if (list->currentSize >= list->maxSize) {
        // Handle error: List is full
    } else {
        ListNode* newNode = malloc(sizeof(ListNode));
        assert(newNode != NULL);

        newNode->data = data;
        newNode->index = list->currentSize++;
        newNode->next = list->head;
        list->head = newNode;
    }

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* getFromList(DynamicList* list, int index) {
    assert(list != NULL && index >= 0 && index < list->currentSize);

    pthread_mutex_lock(&list->lock);

    ListNode* current = list->head;
    while (index-- > 0) {
        current = current->next;
    }
    NFAPI_CRC_INDICATION_PDU_T* data = current->data;

    pthread_mutex_unlock(&list->lock);

    return data;
}

void freeList(DynamicList* list) {
    assert(list != NULL);

    pthread_mutex_lock(&list->lock);

    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* temp = current->next;

        free(current->data);
        free(current);

        current = temp;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
```

This is a basic implementation using a singly linked list. Each node contains the data and an index, and the list itself keeps track of the maximum size and current size, as well as a mutex to ensure thread safety. The `addToList` function validates that there is still space in the list before adding a new element.

