NetworkEvent *createEvent(EventTimestamp timestamp, EventID id, EventDetails details) {
    NetworkEvent *event = malloc(sizeof(NetworkEvent));
    if (event == NULL) {
        return NULL;  // Error handling for memory allocation.
    }
    event->timestamp = timestamp;
    event->id = id;
    event->details = details;
    event->next = NULL;
    event->prev = NULL;
    return event;
}

void addEvent(NetworkEvent **head, NetworkEvent *event) {
    if (*head == NULL) {
        *head = event;
        return;
    }
    NetworkEvent *current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = event;
    event->prev = current;
}

void removeEvent(NetworkEvent **head, EventID id) {
    NetworkEvent *current = *head;
    while (current != NULL && current->id != id) {
        current = current->next;
    }
    if (current == NULL) return;  // No such event.
    if (current->prev != NULL) {
        current->prev->next = current->next;
    }
    if (current->next != NULL) {
        current->next->prev = current->prev;
    }
    free(current);  // Don't forget to free the memory after removing an event.
}
```
