#define HASH_SIZE 10007
int hash_table[HASH_SIZE];

void initializeHashTable() {
    memset(hash_table, -1, sizeof(hash_table));
}

int insertIntoHashTable(int key) {
    int index = abs(key % HASH_SIZE);

    while (hash_table[index] != -1 && hash_table[index] != key) {
        index++;

        if (index == HASH_SIZE) {
            index = 0;
        }
    }

    if (hash_table[index] == key) {
        return 0; // already exists
    } else {
        hash_table[index] = key;
        return 1; // inserted
    }
}

// Function to generate a unique random number within a range
int getUniqueRandomNumber(int min, int max) {
    srand(time(0));

    while (1) {
        int num = rand() % (max - min + 1) + min;

        if (insertIntoHashTable(num)) {
            return num;
        }
    }
}
