    arr->size = initial_size;
}

void set_config(dynamic_array_t* arr, int index, lte_config_t config) {
    pthread_mutex_lock(&arr->lock);  // enter critical section

    if (index < arr->size && index >= 0) {
        arr->configs[index] = config;
    } else {
        printf("Index out of bounds!\n");
    }

    pthread_mutex_unlock(&arr->lock);  // leave critical section
}

lte_config_t get_config(dynamic_array_t* arr, int index) {
    lte_config_t config;

    pthread_mutex_lock(&arr->lock);

    if (index < arr->size && index >= 0) {
        config = arr->configs[index];
    } else {
        printf("Index out of bounds!\n");
    }

    pthread_mutex_unlock(&arr->lock); 

    return config;
}
```
