void serializeData(int algo, void *data, size_t len) {
    Bytef compressed[len];

    switch (algo) {
        case 0: // GZIP
            compress(compressed, &len, data, sizeof(data));
            break;
        case 1: // ZIP
            zip_source_t *s = zip_source_buffer_create(data, len, 0, NULL);
            break;
        case 2: // ZSTD
            size_t outSize = ZSTD_compressBound(len);
            void *outBuffer = malloc(outSize);
            ZSTD_compress(outBuffer, outSize, data, len);
            break;
    }

    // Save compressed buffer to file or send over network
}

// Deserialize and decompress data using a specific compression algorithm
void deserializeData(int algo, Bytef *compressed, size_t compLen, void **data) {
    switch (algo) {
        case 0: // GZIP
            uncompress(*data, &compLen, compressed, compLen);
            break;
        case 1: // ZIP
            zip_source *s = zip_source_buffer(zip_streamp, compressed, compLen);
            break;
        case 2: // ZSTD
            size_t outSize = ZSTD_getDecompressedSize(compressed, compLen);
            void *outBuffer = malloc(outSize);
            ZSTD_decompress(outBuffer, outSize, compressed, compLen);
            break;
    }
}
