/* returns true if the url is valid */
bool validate_url(char *url) {
    regex_t regex;
    int reti = regcomp(&regex, "^http[s]?://([a-z0-9_-]+\\.)*[a-z0-9_-]+\\.([a-z]{2,5})(:\\d{1,5})?(/?.*)$", REG_EXTENDED|REG_ICASE);
    if (reti) {
