typedef struct {
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocateList(int n, int logLevel) {
    if (n == 0 || !logLevel) {
        return NULL;
    }

    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (!list) {
        if (logLevel > 0) printf("Memory allocation failed\n");
        return NULL;
    }

    int lastFlag = -1, successfulAllocations = 0;
    for(int i = 0; i < n; ++i){
        list[i].CRCFLAG = rand() % 256;
        if (list[i].CRCFLAG != lastFlag) {
            successfulAllocations++;
            lastFlag = list[i].CRCFLAG;
            continue;
        }

        if(logLevel > 0){
           printf("Skipped allocation at index %d due to same CRCFLAG value\n", i); 
        }
    }

    if (logLevel > 1) {
        printf("%d structs were successfully allocated\n", successfulAllocations);
    }

    return list;
}

void freeList(NFAPI_CRC_INDICATION_PDU_T* list, int logLevel){
    if (!list || !logLevel) {
        return;
    }

    free(list);

    if (logLevel > 0) {
        printf("Memory freed successfully\n"); 
    }
}
```
