} NFAPI_CRC_INDICATION_PDU_T;

GQueue* queue = NULL; /* the queue to hold the structures */
pthread_mutex_t mutex; /* for thread-safe access */

NFAPI_CRC_INDICATION_PDU_T* create_and_fill() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(*pdu));

    if (pdu == NULL) {
        log_error("Memory allocation failed");
        return NULL;
    }

    /* fill the structure here */

    return pdu;
}

void* producer() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = create_and_fill();

    if (pdu != NULL) {
        pthread_mutex_lock(&mutex);
        g_queue_push_tail(queue, pdu); /* add to the queue */
        pthread_mutex_unlock(&mutex);
    }
}

void* consumer() {
    NFAPI_CRC_INDICATION_PDU_T* pdu;

    pthread_mutex_lock(&mutex);

    if (g_queue_is_empty(queue)) {
        log_warning("Queue is empty");
    } else {
        pdu = g_queue_pop_head(queue); /* remove from the queue */
        pthread_mutex_unlock(&mutex);

        /* process the structure here */

        free(pdu); /* don't forget to deallocate memory */
    }
}
```

