    srand(time(NULL)); 
    long* offsets = calloc(N, sizeof(long));
    int* keys = calloc(M, sizeof(int));

    size_t minSize = N < M ? N : M;
    L = L > minSize ? minSize : L;

    record** records = malloc(sizeof(record*) * L);
    for (size_t i = 0; i < L; ++i) {
        records[i] = malloc(sizeof(record));
        records[i]->offset = &offsets[rand() % N];
        records[i]->key = keys[rand() % M];
    }

    free(keys);
    return records;
}

void populate_records(record** records, size_t L, int minVal, int maxVal) {
    for (size_t i = 0; i < L; ++i) 
        *(records[i]->offset) = rand() % (maxVal - minVal + 1) + minVal;
}

void print_records(record** records, size_t L) {
    for (size_t i = 0; i < L; ++i) 
        printf("Pointer: %ld, Key: %d\n", *(records[i]->offset), records[i]->key);
}

void free_records(record** records, size_t L) {
    for (size_t i = 0; i < L; ++i) 
        free(records[i]);

    free(records);
}
