['```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct node {
    char* identifier;
    int reference_count;
} node;

typedef struct shared_resources {
    long offsets[1024];
    char *identifiers[65536];
    node **nodes;
    size_t nodes_capacity;
    size_t nodes_size;
    pthread_mutex_t lock;
} shared_resources;

shared_resources* initialize_resources(size_t capacity) {
    shared_resources *res = malloc(sizeof(*res));

    if (res != NULL) {
        for (int i = 0; i < sizeof(res->offsets)/sizeof(long); ++i) 
            res->offsets[i] = rand();

        for (int i = 0; i < sizeof(res->identifiers)/sizeof(char*); ++i) {
            char *str = malloc(64);
            if (str != NULL) {
                sprintf(str, "identifier%d", i);
                res->identifiers[i] = str;
            } else return NULL; // handle allocation failure
        }

        res->nodes_capacity = capacity;
        res->nodes_size = 0;
        res->nodes = malloc(capacity * sizeof(node*));

        if (res->nodes != NULL) {
            pthread_mutex_init(&res->lock, NULL);
            return res;
        }
    }

    return NULL; // handle allocation failure or mutex init failure
}

void add_node(shared_resources *res, node *n) {
    if (pthread_mutex_lock(&res->lock)) 
        return;

    if (res->nodes_size < res->nodes_capacity)
        ++res->nodes[res->nodes_size++] = n;

    pthread_mutex_unlock(&res->lock);
}

void remove_node(shared_resources *res, node *n) {
    if (pthread_mutex_lock(&res->lock)) 
        return;

    for (int i = 0; i < res->nodes_size; ++i) {
        if (res->nodes[i] == n) {
            free(n->identifier); // cleanup identifier memory
            free(n); // cleanup node memory

            --res->nodes_size;
            res->nodes[i] = res->nodes[res->nodes_size];
            break;
        }
    }

    pthread_mutex_unlock(&res->lock);
}

void increment_ref(shared_resources *res, int idx) {
    if (pthread_mutex_lock(&res->lock)) 
        return;

    ++res->nodes[idx]->reference_count;

    pthread_mutex_unlock(&res->lock);
}
```
