} file_entry;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

file_entry* readFilesFromDirectories(int numDirs, char *dirNames[], int *numEntries) {
    // Dynamically allocate memory for an array of file_entry structures
    file_entry *entries = malloc(sizeof(file_entry));
    if (entries == NULL) return NULL;

    *numEntries = 0;
    for (int i = 0; i < numDirs; ++i) {
        char *dirName = dirNames[i];

        // Start an asynchronous non-blocking I/O operation to read data from the directory
        // For simplicity, we'll assume that a callback function handleReadData() is called
        // when the data is available. This function will be responsible for parsing the file data,
        // and adding it to our entries array.
        startNonBlockingIO(dirName, handleReadData);
    }

    return entries;
}

void handleReadData(file_entry newEntry) {
    pthread_mutex_lock(&lock);

    // Check for duplicates based on file name and size
    bool isDuplicate = false;
    for (int i = 0; i < *numEntries; ++i) {
        if ((strcmp(entries[i].name, newEntry.name) == 0) && 
            entries[i].size == newEntry.size) {

            isDuplicate = true;
            break;
        }
    }

    // If the entry is not a duplicate, add it to our array and update lastModifiedTime
    if (!isDuplicate) {
        entries[*numEntries] = newEntry;
        ++(*numEntries);

        // Update lastModifiedTime to current system time using utimes()
        struct timespec times[2];
        times[0].tv_sec  = entries[*numEntries - 1].lastModifiedTime;
        times[0].tv_nsec = UTIME_OMIT;

        times[1].tv_sec  = time(NULL);
        times[1].tv_nsec = UTIME_NOW;

        utimes(entries[*numEntries - 1].name, times);
    }

    pthread_mutex_unlock(&lock);
}
```

