    // Allocate memory for the array of data blocks
    DataBlock* dataArray = malloc(numBlocks * sizeof(DataBlock));
    assert(dataArray != NULL);

    size_t uniqueIndex = 0;

    for (size_t i = 0; i < numBlocks; ++i) {
        // Allocate memory for the array of elements within each data block
        Element* elementList = malloc(elementsPerBlock * sizeof(Element));
        assert(elementList != NULL);

        for (size_t j = 0; j < elementsPerBlock; ++j) {
            // Initialize float value with random number between 0 and 1
            elementList[j].value = ((float)rand()/(float)(RAND_MAX)) * 1.0f;

            // Ensure unique index for each data block
            do{
               uniqueIndex = rand();
            }while(indexExistsInArray(dataArray, i, uniqueIndex));
            elementList[j].index = uniqueIndex;
        }

        dataArray[i].elementList = elementList;
        dataArray[i].numElements = elementsPerBlock;
    }

    return dataArray;
}

// Helper function to check if index exists in the array of DataBlocks
int indexExistsInArray(DataBlock* array, size_t numBlocks, size_t uniqueIndex) {
    for (size_t i = 0; i < numBlocks; ++i) {
        for (size_t j = 0; j < array[i].numElements; ++j) {
            if(array[i].elementList[j].index == uniqueIndex){
                return 1; // found duplicate index
            }
        }
    }
    return 0; // no duplicates found
}
