['Here is an example of how you can implement such a system in C using `pthread` for thread safety:

```C
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    int key;
    long offset;
    double value;
    char* str;
} Record;

Record** records = NULL;
int size = 0;  // current number of records
const int initial_size = 10;
pthread_mutex_t lock;

void initialize() {
    pthread_mutex_init(&lock, NULL);

    records = malloc(initial_size * sizeof(Record*));
    if (records == NULL) {
        printf("Error: Memory allocation failed\n");
        exit(1);
    }
}

void insert(int key, long offset, double value, char* str) {
    pthread_mutex_lock(&lock);

    Record** old = records;
    size++;
    if (size > initial_size) {
        // Reallocate a larger array and copy the elements over.
        records = realloc(records, size * sizeof(Record*));
        if (records == NULL) {
            printf("Error: Memory allocation failed\n");
            records = old;  // restore the original pointer
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        printf("Error: Memory allocation failed\n");
        size--;  // do not increase the counter for this case
        pthread_mutex_unlock(&lock);
        return;
    }

    record->key = key;
    record->offset = offset;
    record->value = value;
    record->str = strdup(str);  // Allocate and copy the string.
    if (record->str == NULL) {
        printf("Error: Memory allocation failed\n");
        free(record);  // clean up the allocated memory for this case
        size--;  // do not increase the counter for this case
        pthread_mutex_unlock(&lock);
        return;
    }

    records[size-1] = record;

    pthread_mutex_unlock(&lock);
}

// Similar to insert, but with removal of elements.
void delete(int key) {
    // Find the index and remove it...
}

Record* lookup(int key) {
    for (int i = 0; i < size; i++) {
        if (records[i]->key == key)
            return records[i];
    }

    return NULL;  // record not found
}

void cleanup() {
    pthread_mutex_lock(&lock);

    for(int i = 0; i < size; i++) {
        free(records[i]->str);  // free the string first
        free(records[i]);
    }

    free(records);

    pthread_mutex_unlock(&lock);
}
```
This is a simple implementation of a hash table with linear probing for collision resolution. For better performance, you could use separate chaining or other collision resolutions. 

