    try {
        if (!fs.existsSync(resolvedPath)) {
            console.log('Error: File does not exist');
            return false;
        }

        let stats = fs.statSync(resolvedPath);
        if (!stats.isFile()) {
            console.log('Error: Path is not a file');
            return false;
