uint32_t getTag() {
    pthread_mutex_lock(&lock);
    if (tagCount == 0) {
        logError("No more tags available!");
        return 0; // Returning 0 as an error indicator.
    }
    uint32_t tag = availableTags[--tagCount];
    pthread_mutex_unlock(&lock);
    return tag;
}

uint16_t getRNTI() {
    pthread_mutex_lock(&lock);
    if (rntiCount == 0) {
        logError("No more RNTIs available!");
        return 0; // Returning 0 as an error indicator.
