          "\"key2\": [\"element1\", \"element2\"]"
        "}";

    GVariant *variant = g_variant_new_from_data(G_VARIANT_TYPE("a{sv}"), (void*) json, strlen(json), TRUE, NULL, &error);

    if (!variant) {
        printf("Error: %s\n", error->message);
        g_clear_error(&error);
        return 1;
    }

    GVariantIter iter;
    g_variant_iter_init (&iter, variant);

    // Dynamic memory allocation for an array of records
    MyData **data = malloc(sizeof(*data));
