#include <pthread.h>
#include <stdatomic.h>
#include <stdlib.h>
#include <string.h>

typedef struct TrafficEvent {
    int eventID;
    long timestamp;
    char* location;
} TrafficEvent;

typedef struct CacheEntry {
    int hit_count;
    TrafficEvent event;
} CacheEntry;

#define CACHE_SIZE 1024
CacheEntry cache[CACHE_SIZE];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

TrafficEvent get_event(int eventID) {
    // Attempt to find the event in cache.
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].hit_count > 0 && cache[i].event.eventID == eventID) {
            TrafficEvent event = cache[i].event;
            atomic_fetch_add(&cache[i].hit_count, 1);
            pthread_mutex_unlock(&cache_lock);
            return event;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    // If not found in cache, fetch from database.
    TrafficEvent event = fetch_event_from_database(eventID);

    // Add the fetched event to the cache.
    int min_hit_count = 0;
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].hit_count <= min_hit_count) {
            min_hit_count = cache[i].hit_count;
            free(cache[i].event.location);  // Free previous event's location.
            cache[i].hit_count = 1;
            cache[i].event = event;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    return event;
}
```
