typedef struct {
    int sessionID;
    time_t loginTime;
    time_t logoutTime;
    time_t lastActivityTime;
} UserSession;

typedef struct {
    UserSession *sessions;
    pthread_mutex_t lock;
    int size;
    int capacity;
} SessionList;

void sessionListInit(SessionList* list, int initialCapacity) {
    list->sessions = (UserSession*) malloc(initialCapacity * sizeof(UserSession));
    list->size = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->lock, NULL);
}

void sessionListAdd(SessionList* list, UserSession session) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        list->sessions = realloc(list->sessions, 2 * list->capacity * sizeof(UserSession));
        list->capacity *= 2;
    }
    list->sessions[list->size++] = session;
    pthread_mutex_unlock(&list->lock);
}

void sessionListCleanup(SessionList* list) {
    time_t now = time(NULL);
    for (int i = 0; i < list->size; ++i) {
        UserSession *session = &list->sessions[i];
        if (now - session->lastActivityTime > SESSION_TIMEOUT) {
            memmove(&list->sessions[i], &list->sessions[i + 1], (list->size - i - 1) * sizeof(UserSession));
            --list->size;
        }
    }
}

void* sessionManagerThread(void* arg) {
    SessionList* list = (SessionList*) arg;
    while (1) {
        sleep(CLEANUP_INTERVAL);
        pthread_mutex_lock(&list->lock);
        sessionListCleanup(list);
        pthread_mutex_unlock(&list->lock);
    }
}
