#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int fileSize;
} Record;

void initDataStructures(long *offsets, int *ids, Record *records, int size) {
    // Validate input parameters
    if (size <= 0 || offsets == NULL || ids == NULL || records == NULL) {
        printf("Invalid input\n");
        return;
    }

    // Initialize arrays to zero using loops for efficient memory use
    for(int i = 0; i < size; ++i) {
        offsets[i] = 0L;
        ids[i] = 0;
        records[i].fileSize = 0;
    }
}

void randomizeIdsInRange(int *ids, Record *records, int size, int lowerLimit, int upperLimit) {
    // Validate input parameters
    if (size <= 0 || ids == NULL || records == NULL 
        || lowerLimit < 0 || upperLimit < lowerLimit || upperLimit - lowerLimit + 1 < size) {
        printf("Invalid input\n");
        return;
    }

    // Initialize random number generator with current time for different outputs
    srand(time(NULL));

    int i, j, tmpId, collisionFlag;
    for (i = 0; i < size;) {
        collisionFlag = 0;

        // Generate a random id within range
        tmpId = rand() % (upperLimit - lowerLimit + 1) + lowerLimit;

        // Check if the id is already used
        for(j = 0; j < i; ++j) {
            if(ids[j] == tmpId) {
                collisionFlag = 1;
                break;
            }
        }

        // If no collision occurs, assign to record and iterate
        if(!collisionFlag) {
            ids[i] = tmpId;
            ++i;
        }
    }
}

void manageMemoryAllocation(long **offsetsPtr, int **idsPtr, Record **recordsPtr, int size) {
    // Allocate memory for all structures and handle allocation failures
    *offsetsPtr = (long *) malloc(sizeof(long) * size);
    if (*offsetsPtr == NULL) {
        printf("Memory allocation failed for offset array\n");
        return;
    }

    *idsPtr = (int *) malloc(sizeof(int) * size);
    if (*idsPtr == NULL) {
        printf("Memory allocation failed for id array\n");
        free(*offsetsPtr);
        return;
    }

    *recordsPtr = (Record *) malloc(sizeof(Record) * size);
    if (*recordsPtr == NULL) {
        printf("Memory allocation failed for record structure array\n");
        free(*offsetsPtr);
        free(*idsPtr);
        return;
    }

    // Initialize all elements to zero
    initDataStructures(*offsetsPtr, *idsPtr, *recordsPtr, size);
