["Here is the C function `manage_rx_indications`:

```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int L1_RRC_TAG;
    time_t timestamp;
} NFAPI_L1_RX_INDICATION_PDU;

#define INITIAL_SIZE 1024
#define GROWTH_FACTOR 2
#define MAX_AGE (60 * 60) // 1 hour in seconds

typedef struct {
    NFAPI_L1_RX_INDICATION_PDU* array;
    int size;
    int count;
} DynamicArray;

DynamicArray array;

int manage_rx_indications(NFAPI_L1_RX_INDICATION_PDU pdu) {
    if (pdu.RNTI < 0 || pdu.RNTI >= array.size) return -1; // Invalid RNTI

    if (array.count == 0 || pdu.RNTI > array.count - 1) { // Adding new entry
        if (array.count == array.size) { // Allocating more memory
            NFAPI_L1_RX_INDICATION_PDU* temp = realloc(array.array, sizeof(*temp) * array.size * GROWTH_FACTOR);
            if (!temp) return -2; // Memory allocation failure
            array.array = temp;
            array.size *= GROWTH_FACTOR;
        }

        array.array[pdu.RNTI] = pdu;
        array.count++;
    } else { // Updating existing entry
        array.array[pdu.RNTI].timestamp = time(NULL);
    }

    clean_old(); // Clean up outdated entries
}

void clean_old() {
    for (int i = 0; i < array.count; ) {
        if ((time(NULL) - array.array[i].timestamp) > MAX_AGE) {
            if (i != array.count - 1) { // Move last entry to this position
                array.array[i] = array.array[array.count - 1];
            }
            array.count--;
        } else i++;
    }
}
```

