typedef struct {
    unsigned int version;
    unsigned int sequence_number;
    unsigned long timestamp;
    size_t payload_length;
} PacketHeader;

static const size_t PACKETS_PER_SEGMENT = 1024;

int process_packets(const void *data, size_t length) {
    static PacketHeader *headers = NULL;
    static size_t count = 0;
    static size_t capacity = 0;

    if (length < sizeof(PacketHeader)) {
        return -1;  // Invalid packet data.
    }

    const size_t num_packets = length / sizeof(PacketHeader);

    for (size_t i = 0; i < num_packets; ++i) {
        if (count >= capacity) {
            capacity += PACKETS_PER_SEGMENT;
            PacketHeader *new_headers = realloc(headers, capacity * sizeof(*headers));

            // Handle allocation failure.
            if (!new_headers && capacity > PACKETS_PER_SEGMENT) {
                --capacity;  // Try to free some memory before failing.
                new_headers = realloc(headers, capacity * sizeof(*headers));

                if (!new_headers) {
                    return -1;  // Memory allocation failure.
                }
            } else if (!new_headers && !capacity) {
                return -1;  // Initial memory allocation failed.
            }

            headers = new_headers;
        }

        memcpy(&headers[count++], (const char *)data + i * sizeof(PacketHeader), sizeof(PacketHeader));
    }

    return 0;
}
```
