#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    char* key;
    size_t offset;
    void* value;
} Record;

typedef struct {
    _Atomic(size_t) count;  // atomic operations to avoid data races
    pthread_mutex_t lock;  // mutex for thread safety
    Record** records;      // array of records
} RecordCollection;

// Initialize the collection with given size.
void record_collection_init(RecordCollection* collection, size_t initial_size) {
    atomic_init(&collection->count, 0);
    pthread_mutex_init(&collection->lock, NULL);
    collection->records = malloc(initial_size * sizeof(Record*));
}

// Add a record to the collection. Thread-safe operation.
void record_collection_add(RecordCollection* collection, Record* record) {
    pthread_mutex_lock(&collection->lock);  // lock before modifying data
    size_t count = atomic_fetch_add(&collection->count, 1);
    if (count >= sizeof(collection->records)/sizeof(Record*)) {
        collection->records = realloc(collection->records, 2 * count * sizeof(Record*));
    }
    collection->records[count] = record;
    pthread_mutex_unlock(&collection->lock);  // unlock after modifying data
}

// Process batch of records asynchronously.
void process_batch(RecordCollection* collection, Record** batch, size_t batch_size) {
    for (size_t i = 0; i < batch_size; ++i) {
        record_collection_add(collection, batch[i]);  // add each record to the collection
    }
}
```
This program uses an array of pointers to `Record` objects to manage memory for a collection. When more space is needed, it doubles the size of the array with realloc. This ensures that frequent allocations and deallocations are minimized, resulting in improved performance. 

It uses atomic operations and a mutex lock to ensure thread safety when adding records to the collection. This prevents data races between multiple threads accessing the same memory location simultaneously. 

