#define MAX_RETRIES 10
#define PACKET_SIZE sizeof(PacketHeader)
#define BUFFER_SIZE 5000

typedef struct PacketHeader {
    uint8_t protocolVersion;
    uint32_t sequenceNumber;
    time_t timestamp;
    size_t payloadLength;
    _Bool acknowledgmentStatus;
    uint8_t retryCount;
} PacketHeader;

typedef struct Buffer {
    PacketHeader* headers;
    size_t count;
    size_t capacity;
    atomic_uint lastAckdSeqNum;
    pthread_mutex_t lock;
} Buffer;

void initBuffer(Buffer* buffer) {
    buffer->headers = NULL;
    buffer->count = 0;
    buffer->capacity = 0;
    atomic_init(&buffer->lastAckdSeqNum, 0);
    pthread_mutex_init(&buffer->lock, NULL);
}

void freeBuffer(Buffer* buffer) {
    pthread_mutex_destroy(&buffer->lock);
    free(buffer->headers);
}

// Function to add a packet header to the array.
int addPacketHeader(Buffer* buffer, PacketHeader header) {
    if (header.sequenceNumber <= atomic_load(&buffer->lastAckdSeqNum)) {
        fprintf(stderr, "Error: sequence number is not greater than last acknowledged\n");
        return -1; // Indicating error
    }
    pthread_mutex_lock(&buffer->lock);
    ++buffer->count;
    if (buffer->count > buffer->capacity) {
        PacketHeader* temp = realloc(buffer->headers, PACKET_SIZE * buffer->count);
        if (!temp) {
            fprintf(stderr, "Error: failed to allocate memory for packet headers\n");
            pthread_mutex_unlock(&buffer->lock);
            return -1; // Indicating error
        }
        buffer->headers = temp;
        buffer->capacity = buffer->count;
    }
    buffer->headers[buffer->count-1] = header;
    pthread_mutex_unlock(&buffer->lock);
    return 0; // Indicating success
}

// Function to update a specific packet header.
int updatePacketHeader(Buffer* buffer, size_t index, PacketHeader header) {
    if (index >= buffer->count) {
        fprintf(stderr, "Error: index out of bounds\n");
        return -1; // Indicating error
    }
    pthread_mutex_lock(&buffer->lock);
    PacketHeader* current = &buffer->headers[index];
    if (header.sequenceNumber <= atomic_load(&buffer->lastAckdSeqNum)) {
        fprintf(stderr, "Error: sequence number is not greater than last acknowledged\n");
        pthread_mutex_unlock(&buffer->lock);
        return -1; // Indicating error
    }
    *current = header;
    if (header.acknowledgmentStatus && atomic_load(&buffer->lastAckdSeqNum) < header.sequenceNumber) {
        atomic_store(&buffer->lastAckdSeqNum, header.sequenceNumber);
    }
    pthread_mutex_unlock(&buffer->lock);
    return 0; // Indicating success
}

// Function to validate sequence numbers and identify gaps.
void validateSequenceNumbers(Buffer* buffer) {
    uint32_t expectedSeqNum = atomic_load(&buffer->lastAckdSeqNum) + 1;
    for (size_t i = 0; i < buffer->count; ++i) {
        PacketHeader* header = &buffer->headers[i];
        if (header->sequenceNumber != expectedSeqNum) {
            fprintf(stderr, "Sequence gap detected: %u to %u\n", expectedSeqNum, header->sequenceNumber);
        }
        expectedSeqNum = header->sequenceNumber + 1;
    }
}

// Function to resend packets.
void resendPackets(Buffer* buffer) {
    time_t currentTime = time(NULL);
    for (size_t i = 0; i < buffer->count; ++i) {
        PacketHeader* header = &buffer->headers[i];
