typedef struct LTE_EMBB_BWP_CONFIG {
    int id;
    double bandwidth;
} LTE_EMBB_BWP_CONFIG_T;

typedef struct DynamicArray {
    pthread_mutex_t mutex;  // for thread safety
    LTE_EMBB_BWP_CONFIG_T* array;
    int size;
    int capacity;
} DynamicArray_T;

DynamicArray_T createDynamicArray() {
    DynamicArray_T arr;
    arr.array = (LTE_EMBB_BWP_CONFIG_T*)malloc(sizeof(LTE_EMBB_BWP_CONFIG_T));
    arr.capacity = 1;
    arr.size = 0;
    pthread_mutex_init(&arr.mutex, NULL);  // initialize the mutex
    return arr;
}

void addElement(DynamicArray_T* arr, LTE_EMBB_BWP_CONFIG_T element) {
    pthread_mutex_lock(&arr->mutex);  // acquire lock before accessing shared data

    if (arr->size == arr->capacity) {
        arr->capacity *= 2;
        arr->array = realloc(arr->array, sizeof(LTE_EMBB_BWP_CONFIG_T) * arr->capacity);
    }

    arr->array[arr->size] = element;
    (arr->size)++;

    pthread_mutex_unlock(&arr->mutex);  // release lock after finishing critical section
}

// similarly implement removeElement, updateElement etc. functions following the pattern above for thread safety

void loadConfigurations(DynamicArray_T* arr, const char* fileName) {
    FILE *fp = fopen(fileName, "r");
    if (fp == NULL) return;  // handle file opening error

    fseek(fp, 0, SEEK_END);
    long length = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    char *buffer = malloc(length+1);
    fread(buffer, 1, length, fp);

    cJSON* json = cJSON_Parse(buffer);  // parse JSON using cjson library
    if (json == NULL) return;  // handle parsing error

    for(cJSON *config=json->child; config != NULL; config=config->next){
        LTE_EMBB_BWP_CONFIG_T element = {cJSON_GetObjectItem(config, "id")->valueint, 
                                         cJSON_GetObjectItem(config, "bandwidth")->valuedouble};
        addElement(arr, element);
    }

    // don't forget to free memory after use
    fclose(fp);
    free(buffer);
}

// similarly implement saveConfigurations function following the pattern above for thread safety
```
