['Implementing such a complex system in C would be quite extensive and likely involve several files. However, I can provide a simplified example of how you might approach this problem from a high-level perspective using pthreads for thread safety. 

Please note that the real code will depend heavily on the specific details of your application and requirements such as performance constraints, memory footprint, cache efficiency etc.

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    int* data; // array of integers
    float other_data; 
    char* variable_length_data;
} Record;

typedef struct Node {
    pthread_mutex_t lock;
    Record* record;
    struct Node *next, *prev;
} Node;

Node* head = NULL;
pthread_rwlock_t listLock = PTHREAD_RWLOCK_INITIALIZER;

Record* allocateRecord(int size) {
    Record* rec = malloc(sizeof(Record));
    if (rec == NULL) return NULL; // allocation failed

    rec->data = malloc(size * sizeof(int)); 
    if (rec->data == NULL) {
        free(rec);
        return NULL;
    }
    memset(rec->data, 0, size * sizeof(int)); // zero out memory

    rec->other_data = 0.0f;
    rec->variable_length_data = NULL;
    return rec;
}

void freeRecord(Record* record) {
    if (record != NULL) {
        free(record->data);
        free(record->variable_length_data); 
        free(record);
    }
}

Node* insertTail() {
    Node* node = malloc(sizeof(Node));
    if (node == NULL) return NULL; // allocation failed

    pthread_mutex_init(&node->lock, NULL); 
    node->record = allocateRecord(1024);
    if (node->record == NULL) {
        free(node);
        return NULL;
    }

    pthread_rwlock_wrlock(&listLock); // lock the list for writing
    if (head == NULL) { 
        node->next = node->prev = NULL;
        head = node;
    } else { 
        Node* tail = head->prev; 
        node->next = NULL;
        node->prev = tail; 
        if (tail != NULL) tail->next = node; 
        head->prev = node;
    }
    pthread_rwlock_unlock(&listLock); // unlock the list

    return node; 
}

// This function should be called periodically to clean up unused records.
void removeNode(Node* node) {
    if (node == NULL) return;

    pthread_rwlock_wrlock(&listLock); // lock the list for writing
    Node* prev = node->prev, *next = node->next; 
    if (prev != NULL) prev->next = next; 
    if (next != NULL) next->prev = prev; 
    if (head == node) head = next; 
    pthread_rwlock_unlock(&listLock); // unlock the list

    freeRecord(node->record);
    free(node);
}
```
This code creates a doubly linked list of records, each protected by a mutex. The `insertTail` function allocates a new record and inserts it at the tail of the list. The `removeNode` function removes a node from the list and frees its memory. 

Please note that this code does not include mechanism for handling buffer overflow during resizing, or optimizing for memory bandwidth utilization and cache efficiency etc. Those would need to be implemented based on specific requirements of your application. Furthermore, error checking is kept minimal for simplicity. You should always check the return values of library functions against NULL before proceeding.
