    for (int i = 0; i < size; ++i) {
        if (configArray[i].bandwidth == config.bandwidth) {
            printf("Error: Overlapping bandwidth found!\n");
            pthread_mutex_unlock(&lock);  // Unlock before returning on error
            return;
        }
    }

    // Add new configuration to the array
    if (size == capacity) {
        capacity *= 2;
        configArray = realloc(configArray, sizeof(*configArray) * capacity);
    }
    configArray[size++] = config;

    // Log operation
    logOperation("ADD", config);

    pthread_mutex_unlock(&lock);  // Unlock after critical section
}

// Function to remove a configuration by ID
