    pthread_mutex_lock(&lock);

    for (int i = 0; i < size; ++i) {
        if (configArray[i].id == id) {
            LTE_EMBB_BWP_CONFIG_T config = configArray[i];

            // Shift elements to fill the gap and update size
            for (int j = i; j < size - 1; ++j)
                configArray[j] = configArray[j+1];
            --size;

            // Log operation
            logOperation("REMOVE", config);

            pthread_mutex_unlock(&lock);
            return;
