}

// Function to update a configuration by ID
void updateConfig(LTE_EMBB_BWP_CONFIG_T newConfig) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < size; ++i) {
        if (configArray[i].id == newConfig.id) {
            LTE_EMBB_BWP_CONFIG_T oldConfig = configArray[i];

            // Update the configuration and log operation
            configArray[i] = newConfig;
            logOperation("UPDATE", oldConfig);

            pthread_mutex_unlock(&lock);
            return;
        }
    }

    printf("Error: Configuration not found!\n");
    pthread_mutex_unlock(&lock);  // Unlock before returning on error
}

// Function to log an operation and timestamp it
void logOperation(char *operation, LTE_EMBB_BWP_CONFIG_T config) {
    if (historySize == historyCapacity) {
        historyCapacity *= 2;
        history = realloc(history, sizeof(*history) * historyCapacity);
    }

    HistoryEntry entry;
    strcpy(entry.operation, operation);
    entry.config = config;
    time(&entry.timestamp);

    history[historySize++] = entry;
}

// Function to compact the array periodically (could be scheduled by a timer)
void compactArray() {
    pthread_mutex_lock(&lock);  // Lock for thread safety

    int newSize = 0;

    // Create a temporary array with only active configs
    LTE_EMBB_BWP_CONFIG_T* temp = malloc(sizeof(*temp) * size);
    for (int i = 0; i < size; ++i) {
        if (configArray[i].active) {
            temp[newSize++] = configArray[i];
        }
    }

    // Free the old array and replace it with the compacted one
    free(configArray);
    configArray = malloc(sizeof(*configArray) * newSize);
    memcpy(configArray, temp, sizeof(*temp) * newSize);
    size = newSize;

    pthread_mutex_unlock(&lock);  // Unlock after critical section
}
```

This code does not include error checking for `realloc` or `malloc` calls. Depending on your specific application, you might want to add checks for these functions' return values and handle errors appropriately. This implementation maintains thread-safety through mutual exclusion using a pthread mutex lock/unlock mechanism which can be very inefficient with frequent locking/unlocking operations especially if there are many concurrent modifications. Depending on the actual use case, better solutions might include lock-free data structures or fine-grained locks. 

This implementation also doesn't compact the array automatically periodically for memory optimization. You could set up a timer that would call `compactArray` every so often to remove unused entries and free up some memory. This decision will depend on your specific requirements for latency, throughput, and memory efficiency.
']

