    e->priority_level = priority_level;
    e->description = malloc(strlen(description) + 1);
    if (e->description == NULL) {
        free(e);
        return NULL;
    }

    strcpy(e->description, description);
    e->settings = settings;

    pthread_mutex_lock(&settings->lock);
    settings->refcount++;
    pthread_mutex_unlock(&settings->lock);

    return e;
}

void destroy_entry(Entry* e) {
    free(e->description);
    Settings *s = e->settings;
    pthread_mutex_lock(&s->lock);
    s->refcount--;
    if (s->refcount == 0) {
        pthread_mutex_unlock(&s->lock);
        free(s);
    } else {
        pthread_mutex_unlock(&s->lock);
    }

    free(e);
}

