#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define NR_UPLINK_NAS_TRANSPORT 10000

typedef struct {
    int UE_ID;
    char* NAS_MESSAGE;
    int NAS_MESSAGE_TYPE;
} Node;

Node *list[NR_UPLINK_NAS_TRANSPORT];
int count = 0;
pthread_mutex_t lock;

void sortList() {
    for(int i=1; i<count; ++i) {
        Node* key = list[i];
        int j = i-1;

        while (j>=0 && list[j]->UE_ID > key->UE_ID) {
            list[j+1] = list[j];
            --j;
        }

        list[j+1] = key;
    }
}

int insert(Node* node) {
    pthread_mutex_lock(&lock);

    if (count >= NR_UPLINK_NAS_TRANSPORT) {
        printf("Error: List is full\n");
        return -1;
    }

    for(int i=0; i<count; ++i) {
        if (list[i]->UE_ID == node->UE_ID) {
            printf("Duplicate UE_ID detected. Update existing node or reject the insertion.\n");
            pthread_mutex_unlock(&lock); 
            return -1;
        }
    }

    list[count++] = node;
    sortList();

    pthread_mutex_unlock(&lock);

    return 0;
}

void printUEIDs() {
    for(int i=0; i<count; ++i) {
        printf("UE ID: %d\n", list[i]->UE_ID);
    }
}

// ...
```
