['Here is an attempt at solving your task using C++17 features, Boost and the Strategy Pattern. Please note that complete implementation of all tasks could be very long and complex.

```cpp
#include <vector>
#include <mutex>
#include <chrono>
#include <atomic>
#include <iostream>
#include <boost/asio.hpp>

class PacketHeader {
public:
    int version;
    std::size_t sequenceNumber;
    boost::posix_time::ptime timestamp;
    std::size_t payloadLength;
};

class ProcessingStrategy {
public:
    virtual void processPackets(const PacketHeader& header) = 0;
    virtual ~ProcessingStrategy() = default;
};

class CustomProcessing : public ProcessingStrategy {
public:
    void processPackets(const PacketHeader& header) override {
        // custom packet processing logic here.
    }
};

class PacketManager {
private:
    std::vector<PacketHeader> packets_;
    std::mutex mtx_;
    std::unique_ptr<ProcessingStrategy> strategy_;
    std::atomic<std::size_t> packetCount_{0};
    boost::asio::deadline_timer cooldownTimer_;
    std::chrono::seconds cooldownPeriod_{9};
public:
    PacketManager() : cooldownTimer_(ioService_) {}

    void setStrategy(std::unique_ptr<ProcessingStrategy> strategy) {
        strategy_ = std::move(strategy);
    }

    void addPacket(const PacketHeader& header) {
        if (packets_.size() >= M) {
            packets_.erase(packets_.begin()); // erasing oldest packet.
        }
        packets_.push_back(header);
        ++packetCount_;
    }

    void processPackets() {
        std::lock_guard<std::mutex> lock(mtx_);
        for (const auto& header : packets_) {
            if (cooldownTimer_.expires_from_now().is_negative()) {
                strategy_->processPackets(header);
                ++packetCount_;
                cooldownTimer_.expires_from_now(cooldownPeriod_);
                cooldownTimer_.async_wait([&](const boost::system::error_code& ec) {
                    if (!ec) {
                        processPackets();
                    }
                });
            } else {
                std::cout << "Cooldown period active." << std::endl;
            }
        }
    }

    void logProcessedPackets() const {
        for (const auto& header : packets_) {
            std::cout << "Sequence Number: " << header.sequenceNumber 
                      << ", Packet count: " << packetCount_ << std::endl;
        }
    }
};
```
The class above includes a Strategy pattern to manage different packet processing algorithms and uses Boost's asio library for timed operations like cooldown. However, the actual implementation is quite rudimentary and will need additional work according to your exact requirements.
