['Here is an implementation in C with POSIX Thread (pthread) library for thread safety:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct PacketHeader {
    int protocolVersion;
    unsigned long sequenceNumber;
    time_t timestamp;
    size_t payloadLength;
} PacketHeader;

PacketHeader** packetArray = NULL;
size_t arraySize = 0;
pthread_mutex_t lock;

void initializeArray(size_t M) {
    pthread_mutex_lock(&lock);

    if (packetArray == NULL) {
        packetArray = malloc(M * sizeof(PacketHeader*));
        arraySize = M;

        for (size_t i = 0; i < arraySize; ++i) {
            packetArray[i] = malloc(sizeof(PacketHeader));
            packetArray[i]->sequenceNumber = i+1;
            packetArray[i]->payloadLength = rand() % 65536 + 1; // Random payload length between 1 and 65536
        }
    } else {
        fprintf(stderr, "Error: Array is already initialized!\n");
    }

    pthread_mutex_unlock(&lock);
}

void iterateArray() {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < arraySize; ++i) {
        printf("Sequence Number: %lu, Payload Length: %zu\n", packetArray[i]->sequenceNumber, packetArray[i]->payloadLength);
    }

    pthread_mutex_unlock(&lock);
}

void updateHeader(size_t index, PacketHeader* header) {
    pthread_mutex_lock(&lock);

    if (index < arraySize) {
        packetArray[index]->protocolVersion = header->protocolVersion;
        packetArray[index]->sequenceNumber = header->sequenceNumber;
        packetArray[index]->timestamp = header->timestamp;
        packetArray[index]->payloadLength = header->payloadLength;
    } else {
        fprintf(stderr, "Error: Index out of bounds!\n");
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    srand(time(NULL)); // Seed the random number generator
    pthread_mutex_init(&lock, NULL); // Initialize mutex lock

    initializeArray(10);

    PacketHeader header;
    header.protocolVersion = 2;
    header.sequenceNumber = 456789;
    header.timestamp = time(NULL);
    header.payloadLength = 321;

    updateHeader(5, &header);
    iterateArray();

    pthread_mutex_destroy(&lock); // Destroy mutex lock

    return 0;
}
```
This code initializes an array of `PacketHeader` structures and uses a mutex lock to ensure thread safety during accesses. When the array is initialized, each element has a unique sequence number and random payload length between 1 and 65536 for demonstration purposes. The `iterateArray()` function iterates over the array and prints out sequence numbers and payload lengths. The `updateHeader()` function updates the header at a specific index with new values.
