// Configuration structure
typedef struct {
    char mac[18];
    char ip_address[INET6_ADDRSTRLEN];
    char subnet_mask[INET6_ADDRSTRLEN];
    char gateway[INET6_ADDRSTRLEN];
} device_config;

// Node in the hash table
typedef struct node {
    device_config config;
    struct node* next;
} node;

// Hash table with thread safety and atomic operations for counts
typedef struct {
    pthread_mutex_t lock;
    size_t count;
    node** nodes;
} hash_table;

// Memory pool for efficient allocation and deallocation of device configurations
typedef struct {
    size_t size;
    size_t capacity;
    void* memory;
} memory_pool;

memory_pool createMemoryPool(size_t capacity) {
    memory_pool pool;
    pool.capacity = capacity;
    pool.size = 0;
    pool.memory = malloc(capacity * sizeof(device_config));
    return pool;
}

void destroyMemoryPool(memory_pool* pool) {
    free(pool->memory);
    pool->memory = NULL;
    pool->size = 0;
    pool->capacity = 0;
}

device_config* allocateConfigFromPool(memory_pool* pool) {
    if (pool->size < pool->capacity) {
        return &((device_config*)pool->memory)[pool->size++];
    } else {
        // Handle memory exhaustion - reallocate, notify user, etc.
        return NULL; 
    }
}

void freeConfigFromPool(memory_pool* pool, device_config* config) {
    if (config >= pool->memory && config < ((device_config*)pool->memory + pool->capacity)) {
        // Move the last configuration to fill the gap
        *config = ((device_config*)pool->memory)[--pool->size];
    } else {
        fprintf(stderr, "Attempting to free an invalid config from the memory pool\n");
    }
}

hash_table createHashTable(size_t size) {
    hash_table table;
    table.count = 0;
    pthread_mutex_init(&table.lock, NULL);
    table.nodes = malloc(sizeof(node*) * size);
    for (int i = 0; i < size; ++i) {
        table.nodes[i] = NULL;
    }
    return table;
}

void destroyHashTable(hash_table* table) {
    pthread_mutex_destroy(&table->lock);
    free(table->nodes);
    table->nodes = NULL;
    table->count = 0;
}

size_t hashFunction(const char* mac, size_t tableSize) {
    size_t result = 0;
    for (int i = 0; i < strlen(mac); ++i) {
        result += mac[i];
    }
    return result % tableSize;
}

void insertIntoHashTable(hash_table* table, device_config config) {
    size_t index = hashFunction(config.mac, sizeof(table->nodes) / sizeof(*table->nodes));
    node** bucket = &table->nodes[index];

    pthread_mutex_lock(&table->lock);
    while (*bucket != NULL) {
        if (strcmp((*bucket)->config.mac, config.mac) == 0) {
            fprintf(stderr, "MAC address already exists in the hash table\n");
            pthread_mutex_unlock(&table->lock);
            return;
        }
        bucket = &(*bucket)->next;
    }
    *bucket = malloc(sizeof(node));
    (*bucket)->config = config;
    (*bucket)->next = NULL;
    ++table->count;
    pthread_mutex_unlock(&table->lock);
}

device_config* lookupInHashTable(hash_table* table, const char* mac) {
    size_t index = hashFunction(mac, sizeof(table->nodes) / sizeof(*table->nodes));
    node** bucket = &table->nodes[index];

    pthread_mutex_lock(&table->lock);
    while (*bucket != NULL && strcmp((*bucket)->config.mac, mac) != 0) {
        bucket = &(*bucket)->next;
    }
    device_config* result = *bucket ? &(*bucket)->config : NULL;
    pthread_mutex_unlock(&table->lock);

    return result;
}

void removeFromHashTable(hash_table* table, const char* mac) {
    size_t index = hashFunction(mac, sizeof(table->nodes) / sizeof(*table->nodes));
    node** bucket = &table->nodes[index];

    pthread_mutex_lock(&table->lock);
    while (*bucket != NULL && strcmp((*bucket)->config.mac, mac) != 0) {
        bucket = &(*bucket)->next;
    }
    if (*bucket == NULL) {
        fprintf(stderr, "MAC address not found in the hash table\n");
    } else {
        node* temp = *bucket;
        *bucket = (*bucket)->next;
        free(temp);
        --table->count;
    }
    pthread_mutex_unlock(&table->lock);
}
```
']

