NFAPI_CRC_INDICATION_PDU_T* allocate_memory(size_t size) {
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    int chunk_count = 0;

    while (size > 0) {
        size_t current_chunk_size = min(CHUNK_SIZE, size);
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * current_chunk_size);

        if (new_array == NULL) {
            // Handle memory allocation failure gracefully.
            perror("Memory allocation failed");
            break;
        } else {
            array = new_array;
            size -= CHUNK_SIZE;
            chunk_count++;

