#define MAX_ENTRIES 1024 // Set your maximum entries here

typedef struct {
    uint8_t version;
    uint32_t sequenceNumber;
    time_t timestamp;
    size_t payloadLength;
    struct in_addr sourceAddress;
    struct in_addr destinationAddress;
} PacketHeader;

PacketHeader array[MAX_ENTRIES]; // The dynamic array of packet headers.
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // The global mutex for synchronization.

// Function to initialize a new PacketHeader with some values:
PacketHeader init_header(uint8_t version, uint32_t sequenceNumber, time_t timestamp, size_t payloadLength, struct in_addr sourceAddress, struct in_addr destinationAddress) {
    PacketHeader h;
    h.version = version;
    h.sequenceNumber = sequenceNumber;
    h.timestamp = timestamp;
    h.payloadLength = payloadLength;
    h.sourceAddress = sourceAddress;
    h.destinationAddress = destinationAddress;
    return h;
}

// Function to add a header to the array:
void add_header(PacketHeader h, size_t index) {
    pthread_mutex_lock(&mutex); // Lock the mutex before modifying data.
    if (index < MAX_ENTRIES) {  // Check that the index is within bounds.
        array[index] = h;       // Assign the header to its location in the array.
    }
    pthread_mutex_unlock(&mutex); // Unlock the mutex after modifying data.
}

// Function to get a header from the array:
PacketHeader get_header(size_t index) {
    pthread_mutex_lock(&mutex);  // Lock the mutex before accessing data.
    PacketHeader h;              // Declare a new empty header.
    if (index < MAX_ENTRIES) {  // Check that the index is within bounds.
        h = array[index];       // Assign the value from the array to our new header.
    }
    pthread_mutex_unlock(&mutex); // Unlock the mutex after accessing data.
    return h;                   // Return the new header.
}
```

