    char* ipAddress;
    ConfigParams configParams;
} NetworkDeviceConfig;

NetworkDeviceConfig* initializeConfig(char *configFile) {
    FILE *file = fopen (configFile, "r");

    if (file == NULL) {
        printf("Error opening file!\n");
        return NULL;  // return NULL on error
    }

    NetworkDeviceConfig* devices = malloc(sizeof(NetworkDeviceConfig));  // Allocate on stack for small network
    int deviceCount = 0;
    char line[256];

    while (fgets(line, sizeof(line), file)) {   // Assume each line is a new config
        NetworkDeviceConfig* temp = realloc(devices, (deviceCount + 1) * sizeof(NetworkDeviceConfig));  // Allocate on heap for large network

        if(temp != NULL) {
            devices = temp;

            devices[deviceCount].netId = malloc(20);  // Allocate netId and ipAddress dynamically on heap
            devices[deviceCount].ipAddress = malloc(16);

            sscanf(line, "%s %s %d %d", devices[deviceCount].netId, devices[deviceCount].ipAddress, &devices[deviceCount].configParams.bandwidth, &devices[deviceCount].configParams.qos_priority);  // Parse config from line

            deviceCount++;
        } else {
            printf("Error allocating memory for new device configuration!\n");
            return NULL;  // return NULL on error
        }
    }

    fclose(file);

    return devices;
}
```

This function initializes the network device configurations by parsing each line of a given file. The memory allocation for the devices is performed on the stack initially to avoid unnecessary heap operations. However, if there are too many lines and not enough stack space is available, it switches to dynamic allocation on the heap. This optimizes resource efficiency while also ensuring scalability and flexibility.

