int checkFileHeader(FILE *file, const char *magicNumber) {
    rewind(file);
    char buffer[strlen(magicNumber) + 1];
    fread(buffer, 1, strlen(magicNumber), file);
    buffer[strlen(magicNumber)] = '\0';

    if (strcmp(buffer, magicNumber) != 0) {
        return 0;
    }
    return 1;
}

int checkFileAccessible(const char *fileName) {
    if (access(fileName, R_OK) == -1) {
        fprintf(stderr, "File '%s' is not accessible\n", fileName);
        return 0;
    }
    return 1;
}

int checkDirectoryWritable(const char *directoryPath) {
    struct stat st = {0};

    if (stat(directoryPath, &st) == -1) {
        mkdir(directoryPath, 0700);
    }

    if ((st.st_mode & S_IWUSR) == 0) {
        fprintf(stderr, "Directory '%s' is not writable\n", directoryPath);
        return 0;
    }
    return 1;
}

int checkDiskSpaceAvailable(const char *directoryPath, long requiredSize) {
    struct stat st = {0};

    if (stat(directoryPath, &st) == -1) {
        fprintf(stderr, "Cannot get disk space for '%s'\n", directoryPath);
        return 0;
    }

    if ((long long) st.st_size < requiredSize) {
        fprintf(stderr, "Not enough disk space available in '%s'\n", directoryPath);
        return 0;
    }
    return 1;
}

int jpegToPdf(const char *inputFile, const char *outputDir, const char *outputFile) {
    if (!checkFileAccessible(inputFile)) {
        return 0;
    }

    FILE *file = fopen(inputFile, "rb");
    if (file == NULL) {
        fprintf(stderr, "Cannot open input file\n");
        return 0;
    }

    if (!checkDirectoryWritable(outputDir)) {
        fclose(file);
        return 0;
    }

    long jpegSize = ftell(file) - 2; // Subtracting 2 to exclude magic number from file size.
    if (!checkDiskSpaceAvailable(outputDir, jpegSize)) {
        fclose(file);
        return 0;
    }

    if (!checkFileHeader(file, "\xFF\xD8")) { // JPEG Magic Number
        fprintf(stderr, "Invalid JPEG file header\n");
        fclose(file);
        return 0;
    }

    char command[1024];
    sprintf(command, "/path/to/third-party convert -j %s -p %s", inputFile, outputDir); // Replace with actual command.

    int retries = 3;
    while (retries--) {
        if (system(command) == 0) {
            break;
        }

        fprintf(stderr, "Conversion failed\n");
    }

    fclose(file);

    return 1;
}
```
