#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h> // C11 standard library for atomic operations

typedef struct {
    int protocolVersion;
    unsigned long sequenceNumber;
    time_t timestamp;
    size_t payloadLength;
    char classificationIdentifier[32];
} PacketHeader;

// Use a dynamic array (vector) to manage packets
typedef struct {
    PacketHeader *headers;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock; // For thread-safe operations
    atomic_bool isReallocating; // Flag for reallocation operation
} DynamicPacketArray;

// Initialize the dynamic array with an initial capacity of M entries
void initDynamicPacketArray(DynamicPacketArray *array, size_t capacity) {
    pthread_mutex_init(&array->lock, NULL);
    atomic_store(&array->isReallocating, false);
    array->headers = malloc(sizeof(PacketHeader) * capacity);
    array->count = 0;
    array->capacity = capacity;
}

// Add a packet header to the array (Thread safe operation)
int addToDynamicArray(DynamicPacketArray *array, PacketHeader header) {
    pthread_mutex_lock(&array->lock);

    if(header.payloadLength < 0 || !isValidSequenceNumber(header.sequenceNumber)) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Invalid packet header
    }

    if(array->count >= array->capacity) {
        if(!atomic_load(&array->isReallocating)) {
            atomic_store(&array->isReallocating, true);
            PacketHeader *newHeaders = realloc(array->headers, sizeof(PacketHeader) * array->capacity * 2);
            if(newHeaders != NULL) {
                array->headers = newHeaders;
                array->capacity *= 2;
            } else {
                atomic_store(&array->isReallocating, false);
                pthread_mutex_unlock(&array->lock);
                return -1; // Reallocation failed
            }
        } else {
            while(atomic_load(&array->isReallocating)) {} // Wait for reallocation to finish
        }
    }

    array->headers[array->count++] = header;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}
```
