    try{
        require($moduleName . '.php');
    } catch (Exception $e) {
        error_log("Failed to load module: " . $e->getMessage());
        return;
    }

    $memLimit = 5000000; // 5 MB limit for memory allocation
    $retryCount = 3;
    $recordArray = null;
    while ($retryCount > 0) {
        $longOffsetValues = array();
        $intKeys = array();
        try{
            $recordArray = new SplFixedArray($maxRecords);
            for ($i=0; $i < $maxRecords; $i++) { 
                $recordArray[$i]['int'] = mt_rand(1, 100); // Assuming int in record is a random number between 1 and 100
                echo "Module: $moduleName, Test: $label, Record Index: $i\n";
            }
        } catch (Exception $e) {
            $retryCount--;
            $maxRecords = floor($maxRecords / 2); // Reduce max records for next try
            error_log("Failed to allocate memory: " . $e->getMessage());
            continue;
        }

        if (memory_get_usage() > $memLimit) {
            $recordArray = null;
            $retryCount--;
            error_log("Memory limit exceeded. Retrying with reduced maxRecords");
            continue;
        } else {
            break;
        }
    }

    if ($recordArray === null) {
        return;
    }

    $startTestTime = microtime(true);
    try{
        $f(); // Execute test logic
    } catch (Exception $e){
        error_log("Failed to execute test: " . $e->getMessage());
    }

    $endTestTime = microtime(true);
    $executionTime = $endTestTime - $startTestTime;
    echo "Execution time for test '$label': $executionTime sec\n";

    $totalEndTime = microtime(true);
    $suiteExecutionTime = $totalEndTime - $start_time;
    echo "Suite execution time: $suiteExecutionTime sec\n";
}
```
