#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct Record {
    int key;
    long offset;
    char* buffer;
} Record;

typedef struct DataStructure {
    long** offsets;
    int** keys;
    Record** records;
    pthread_mutex_t mutex;
    size_t n, m, k, l; // number of arrays and size of each array
} DataStructure;

DataStructure* createDataStructure(size_t n, size_t m, size_t k, size_t l) {
    srand(time(NULL));
    if (n <= 0 || m <= 0 || k <= 0 || l <= 0) return NULL; // invalid parameters

    DataStructure* data = (DataStructure*)malloc(sizeof(DataStructure));
    if (!data) return NULL;  // memory allocation failed

    // allocate arrays and initialize with random values
    data->offsets = malloc(n * sizeof(long*));
    data->keys = malloc(k * sizeof(int*));
    for (size_t i = 0; i < n; ++i) {
        data->offsets[i] = malloc(m * sizeof(long));
        for (size_t j = 0; j < m; ++j) {
            data->offsets[i][j] = rand() % 2001 - 1000; // random value between -1000 and 1000
        }
    }

    for (size_t i = 0; i < k; ++i) {
        data->keys[i] = malloc(m * sizeof(int));
        for (size_t j = 0; j < m; ++j) {
            data->keys[i][j] = (i*m + j + 1); // unique sequential values
        }
    }

    data->records = malloc(l * sizeof(Record*));
    for (size_t i = 0; i < l; ++i) {
        data->records[i] = (Record*)malloc(sizeof(Record));
        data->records[i]->key = rand(); // random key
        data->records[i]->offset = rand() % 2001 - 1000; // random offset

        size_t bufferSize = m/2;
        data->records[i]->buffer = malloc(bufferSize);
        for (size_t j = 0; j < bufferSize; ++j) {
            data->records[i]->buffer[j] = rand() % ('z' - 'a') + 'a'; // random alphanumeric char
        }
    }

    pthread_mutex_init(&data->mutex, NULL); // initialize mutex for thread safety
    return data;
}
```
